export const KAREL_BUILTIN_DETAILS: Record<string, KBuiltinDetail> = {"ABORT_TASK":{"kind":"procedure","purpose":"Aborts the specified running or paused task","params":[{"name":"task_name","dir":"in","type":"STRING","text":"task_name is the name of the task to be aborted. If task name is '*ALL*', all executing or paused tasks are aborted except the tasks that have the ``ignore abort request'' attribute set."},{"name":"force_sw","dir":"in","type":"BOOLEAN","text":"force_sw, if true, specifies to abort a task even if the task has the ``ignore abort request'' set. force_sw is ignored if task_name is '*ALL*'."},{"name":"cancel_mtn_sw","dir":"in","type":"BOOLEAN","text":"cancel_mtn_sw specifies whether motion is canceled for all groups belonging to the specified task."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"MULTI","seeAlso":["PAUSE_TASK","NO_ABORT","%NO_ABORT"]},"ABS":{"kind":"function","purpose":"Returns the absolute value of the argument x, which can be an INTEGER or REAL expression","returns":"INTEGER or REAL","params":[{"name":"x","dir":"in","type":"INTEGER|REAL","text":"Returns the absolute value of x, with the same data type as x."}],"env":"SYSTEM"},"ACOS":{"kind":"function","purpose":"Returns the arc cosine (cos-1) in degrees of the specified argument","returns":"REAL","params":[{"name":"x","dir":"in","type":"REAL","text":"x must be between -1.0 and 1.0; otherwise the program will abort with an error."}],"notes":["Returns the arccosine of x."],"env":"SYSTEM"},"ACT_SCREEN":{"kind":"procedure","purpose":"Activates a screen","params":[{"name":"screen_name","dir":"in","type":"STRING","text":"screen_name must be a string containing the name of a previously defined screen, see DEF_SCREEN Built-in."},{"name":"old_screen_n","dir":"out","type":"STRING","text":"The name of the screen that this replaces is returned in old_screen_n."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Causes the display device associated with the screen to be cleared and all windows attached to the screen to be displayed.","Requires the USER or USER2 menu to be selected before activating the new screen, otherwise the status will be set to 9093. — To force the selection of the teach pendant user menu before activating the screen, use FORCE_SPMENU (tp_panel, SPI_TPUSER, 1). — To force the selection of the CRT/KB user menu before activating the screen, use FORCE_SPMENU (crt_panel, SPI_TPUSER, 1).","If the USER menu is exited and re-entered, your screen will be reactivated as long as the KAREL task which called ACT_SCREEN continues to run. When the KAREL task is aborted, the system's user screen will be re-activated."],"env":"PBCORE","seeAlso":["DEF_SCREEN"]},"ACT_TBL":{"kind":"procedure","purpose":"Acts on a key while displaying a table on the teach pendant","params":[{"name":"action","dir":"in,out","type":"INTEGER","text":"action must be one of the constants defined in the include file KLEVKEYS.KL. ACT_TBL will act on the key and return. The following keys have special meanings: — ky_disp_updt (Initial Display) - Table title is displayed, function key labels are displayed. Default item is displayed and highlighted in first line. Remaining lines are displayed. Dynamic display is initiated for all values. This should be the first key passed into ACT_TBL. — ky_reissue (Read Key) - ACT_TBL reads a key, acts on it, and returns it in action. — ky_cancel (Cancel Table) - All dynamic display is cancelled. This should be the last key passed into ACT_TBL if term_char does not equal ky_new_menu. If a new menu was selected, ACT_TBL will have already cancelled the dynamic display and you should not use ky_cancel."},{"name":"def_item","dir":"in,out","type":"INTEGER","text":"def_item is the row containing the item you want to be highlighted when the table is entered. On return, def_item is the row containing the item that was currently highlighted when the termination character was pressed."},{"name":"table_data","dir":"in,out","type":"XWORK_T","text":"table_data is used to display and control the table. Do not change this data; it is used internally."},{"name":"term_char","dir":"out","type":"INTEGER","text":"term_char receives a code indicating the character or other condition that terminated the table. The codes for key terminating conditions are defined in the include file KLEVKEYS.KL. Keys normally returned are pre-defined constants as follows: — ky_undef - No termination character was pressed — ky_select - A selectable item was selected — key_new_menu - A new menu was selected — ky_f1 through ky_f10 - A function key was selected"},{"name":"attach_wind","dir":"out","type":"BOOLEAN","text":"attach_wind should be set TRUE if the table manager needs to be attached to the display devices when action is ky_disp_updt and detached from the display devices when action is ky_cancel. If it is already attached, this parameter can be set to FALSE. Typically this should be TRUE."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["The INIT_TBL and ACT_TBL built-in routines should only be used instead of DISCTRL_TBL if special processing needs to be done with each keystroke or if function key processing needs to be done without exiting the table menu.","The built-in INIT_TBL must be called before using this built-in. Do not continue if an error occurs in INIT_TBL."],"env":"UIF"},"ADD_BYNAMEPC":{"kind":"procedure","purpose":"To add an integer, real, or string value into a KAREL byte given a data buffer.","params":[{"name":"dat_buffer","dir":"in","type":"ARRAY OF BYTE","text":"dat_buffer - an array of up to 244 bytes."},{"name":"dat_index","dir":"in,out","type":"INTEGER","text":"dat_index - the starting byte number to place the string value."},{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name - specifies the name of the program that contains the specified variable."},{"name":"var_name","dir":"in","type":"STRING","text":"var_name - refers to a static program variable. This is only supported by an integer, real, or string variable (arrays and structures are not supported)."},{"name":"status","dir":"out","type":"INTEGER","text":"status - the status of the attempted operation. If not 0, then an error occurred and data was not placed into the buffer. The ADD_BYNAMEPC built-in adds integer, real, and string values to the data buffer in the same manner as the KAREL built-ins ADD_INTPC, ADD_REALPC, and ADD_STRINGPC."}],"env":"PC"},"ADD_DICT":{"kind":"procedure","purpose":"Adds the specified dictionary to the specified language.","params":[{"name":"file_name","dir":"in","type":"STRING","text":"file_name specifies the device, path, and file name of the dictionary file to add. The file type is assumed to be '.TX' (text file)."},{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the name of the dictionary to use when reading and writing dictionary elements. Only 4 characters are used."},{"name":"lang_name","dir":"in","type":"STRING","text":"lang_name specifies to which language the dictionary will be added. One of the following pre-defined constants should be used: dp_default dp_english dp_japanese dp_french dp_german dp_spanish"},{"name":"add_option","dir":"in","type":"INTEGER","text":"add_option should be the following: dp_dram Dictionary will be loaded to DRAM memory and retained until the next INIT START."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred adding the dictionary file."}],"notes":["The default language should be used unless more than one language is required."],"env":"PBCORE","seeAlso":["REMOVE_DICT"]},"ADD_INTPC":{"kind":"procedure","purpose":"To add an INTEGER value (type 16 - 10 HEX) into a KAREL byte data buffer.","params":[{"name":"dat_buffer","dir":"in","type":"ARRAY OF BYTE","text":"dat_buffer - an array of up to 244 bytes."},{"name":"dat_index","dir":"in,out","type":"INTEGER","text":"dat_index - the starting byte number to place the integer value."},{"name":"number","dir":"in","type":"INTEGER","text":"number - the integer value to place into the buffer."},{"name":"status","dir":"out","type":"INTEGER","text":"status - the status of the attempted operation. If not 0, then an error occurred and data was not put into the buffer. The KAREL built-ins ADD_BYNAMEPC, ADD_INTPC, ADD_REALPC, and ADD_STRINGPC can be used to format a KAREL byte buffer in the following way: INTEGER data is added to the buffer as follows (buffer bytes are displayed in HEX): beginning index = dat_index 2 bytes - variable type 4 bytes - the number 2 bytes of zero (0) - end of buffer marker The following is an example of an INTEGER placed into a KAREL array of bytes starting at index = 1: 0 10 0 0 0 5 0 0 where: 0 10 = INTEGER variable type 0 0 0 5 = integer number 5 0 0 = end of data in the buffer On return from the built-in, index = 7."}],"env":"PC"},"ADD_REALPC":{"kind":"procedure","purpose":"To add a REAL value (type 17 - 11 HEX) into a KAREL byte data buffer.","params":[{"name":"dat_buffer","dir":"in","type":"ARRAY OF BYTE","text":"dat_buffer - an array of up to 244 bytes."},{"name":"dat_index","dir":"in,out","type":"INTEGER","text":"dat_index - the starting byte number to place the real value."},{"name":"number","dir":"in","type":"REAL","text":"number - the real value to place into the buffer."},{"name":"status","dir":"out","type":"INTEGER","text":"status - the status of the attempted operation. If not 0, then an error occurred and data was not placed into the buffer. The KAREL built-ins ADD_BYNAMEPC, ADD_INTPC, ADD_REALPC, and ADD_STRINGPC can be used to format a KAREL byte buffer in the following way: REAL data is added to the buffer as follows (buffer bytes are displayed in HEX): beginning index = dat_index 2 bytes - variable type 4 bytes - the number 2 bytes of zero (0) - end of buffer marker The following is an example of an REAL placed into a KAREL array of bytes starting at index = 1: 0 11 43 AC CC CD 0 0 where: 0 11 = REAL variable type 43 AC CC CD = real number 345.600006 0 0 = end of data in the buffer On return from the built-in, index = 7."}],"env":"PC"},"ADD_STRINGPC":{"kind":"procedure","purpose":"To add a string value (type 209 - D1 HEX) into a KAREL byte data buffer.","params":[{"name":"dat_buffer","dir":"in","type":"ARRAY OF BYTE","text":"dat_buffer - an array of up to 244 bytes."},{"name":"dat_index","dir":"in,out","type":"INTEGER","text":"dat_index - the starting byte number to place the string value."},{"name":"item","dir":"in","type":"STRING","text":"item - the string value to place into the buffer."},{"name":"status","dir":"out","type":"INTEGER","text":"status - the status of the attempted operation. If not 0, then an error occurred and data was not placed into the buffer. The KAREL built-ins ADD_BYNAMEPC, ADD_INTPC, ADD_REALPC, and ADD_STRINGPC can be used to format a KAREL byte buffer in the following way: STRING data is added to the buffer as follows: beginning index = dat_index 2 bytes - variable type 1 byte - length of text string text bytes 2 bytes of zero (0) - end of buffer marker The following is an example of an STRING placed into a KAREL array of bytes starting at index = 1: 0 D1 7 4D 48 53 48 45 4C 4C 0 0 0 where: 0 D1 = STRING variable type 7 = there are 7 characters in string 'MHSHELL' 4D 48 53 48 45 4C 4C 0 = 'MHSHELL' with end of string 0 0 0 = end of data in the buffer On return from the built-in, index = 12."}],"env":"PC"},"APPEND_NODE":{"kind":"procedure","purpose":"Adds an uninitialized node to the end of the PATH argument","params":[{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["path_var is the path variable to which the node is appended.","The appended PATH node is uninitialized. The node can be assigned values by directly referencing its NODEDATA structure."],"env":"PBCORE","seeAlso":["INSERT_NODE"]},"APPEND_QUEUE":{"kind":"procedure","purpose":"Appends an entry to a queue if the queue is not full","params":[{"name":"value","dir":"in","type":"INTEGER","text":"value specifies the value to be appended to the queue."},{"name":"queue","dir":"in,out","type":"QUEUE_TYPE","text":"queue specifies the queue variable for the queue."},{"name":"queue_data","dir":"in,out","type":"ARRAY OF INTEGER","text":"queue_data specifies the array used to hold the data in the queue. The length of this array determines the maximum number of entries in the queue."},{"name":"sequence_no","dir":"out","type":"INTEGER","text":"sequence_no is returned with the sequence number of the entry just appended."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with the zero if an entry can be appended to the queue. Otherwise it is returned with 61001, ``Queue is full."}],"env":"PBQMGR","seeAlso":["INSERT_QUEUE"]},"APPROACH":{"kind":"function","purpose":"Returns a unit VECTOR representing the z-axis of a POSITION argument","returns":"VECTOR","params":[{"name":"posn","dir":"in","type":"POSITION","text":"Returns a VECTOR consisting of the approach vector (positive z-axis) of the argument posn."}],"env":"VECTR"},"ARRAY_LEN":{"kind":"function","purpose":"Returns the number of elements contained in the specified array argument","returns":"INTEGER","params":[{"name":"ary_var","dir":"in","type":"ARRAY","text":"The returned value is the number of elements declared for ary_var, not the number of elements that have been initialized in ary_var."}],"env":"SYSTEM"},"ASIN":{"kind":"function","purpose":"Returns arcsine (sin-1) in degrees of the specified argument","returns":"REAL","params":[{"name":"x","dir":"in","type":"REAL","text":"x must be between -1 and 1, otherwise the program will abort with an error."}],"notes":["Returns the arcsine of x."],"env":"SYSTEM"},"ATAN2":{"kind":"function","purpose":"Returns a REAL angle, measured counterclockwise in degrees, from the positive x-axis to a line connecting the origin and a point whose x- and y- coordinates are specified as the x- and y- arguments","returns":"REAL","params":[{"name":"x1","dir":"in","type":"REAL","text":"x1 and y1 specify the x and y coordinates of the point."},{"name":"y1","dir":"in","type":"REAL","text":"x1 and y1 specify the x and y coordinates of the point."}],"notes":["If x1 and y1 are both zero, the interpreter will abort the program."],"env":"SYSTEM"},"ATT_WINDOW_D":{"kind":"procedure","purpose":"Attach a window to the screen on a display device","params":[{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window."},{"name":"disp_dev_nam","dir":"in","type":"STRING","text":"disp_dev_nam must be one of the display devices already defined: 'CRT' CRT Device 'TP' Teach Pendant Device"},{"name":"row","dir":"in","type":"INTEGER","text":"row and col indicate the position in the screen. Row 1 indicates the top row; col 1 indicates the left-most column. The entire window must be visible in the screen where positioned. For example, if the screen is 24 rows by 80 columns (as defined by its associated display device) and the window is 2 rows by 80 columns, row must be in the range 1-23; col must be 1."},{"name":"col","dir":"in","type":"INTEGER","text":"row and col indicate the position in the screen. Row 1 indicates the top row; col 1 indicates the left-most column. The entire window must be visible in the screen where positioned. For example, if the screen is 24 rows by 80 columns (as defined by its associated display device) and the window is 2 rows by 80 columns, row must be in the range 1-23; col must be 1."},{"name":"screen_name","dir":"out","type":"STRING","text":"The name of the active screen is returned in screen_name. This can be used to detach the window later."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Causes data in the specified window to be displayed or attached to the screen currently active on the specified display device.","It is an error if the window is already attached to the screen."],"env":"PBCORE"},"ATT_WINDOW_S":{"kind":"procedure","purpose":"Attach a window to a screen","params":[{"name":"window_name","dir":"in","type":"STRING","text":"window_name and screen_name must be previously defined window and screen names."},{"name":"screen_name","dir":"in","type":"STRING","text":"window_name and screen_name must be previously defined window and screen names."},{"name":"row","dir":"in","type":"INTEGER","text":"row and col indicate the position in the screen. Row 1 indicates the top row; col 1 indicates the left-most column. The entire window must be visible in the screen as positioned. For example, if the screen is 24 rows by 80 columns (as defined by its associated display device) and the window is 2 rows by 80 columns, row must be in the range 1-23; col must be 1."},{"name":"col","dir":"in","type":"INTEGER","text":"row and col indicate the position in the screen. Row 1 indicates the top row; col 1 indicates the left-most column. The entire window must be visible in the screen as positioned. For example, if the screen is 24 rows by 80 columns (as defined by its associated display device) and the window is 2 rows by 80 columns, row must be in the range 1-23; col must be 1."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Causes data in the specified window to be displayed or attached to the specified screen at a specified row and column.","If the screen is currently active, the data will immediately be displayed on the device. Otherwise, there is no change in the displayed data.","It is an error if the window is already attached to the screen."],"env":"PBCORE"},"AVL_POS_NUM":{"kind":"procedure","purpose":"Returns the first available position number in a teach pendant program","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. A program must be opened before calling this built-in."},{"name":"pos_num","dir":"out","type":"INTEGER","text":"pos_num is set to the first available position number."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."}],"env":"TPE"},"BYNAME":{"kind":"function","purpose":"Allows a KAREL program to pass a variable, whose name is contained in a STRING, as a parameter to a KAREL routine. This means the programmer does not have to determine the variable name during program creation and translation.","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the program that contains the specified variable. If prog_name is equal to '' (double quotes), then the routine defaults to the task name being executed."},{"name":"var_name","dir":"in","type":"STRING","text":"var_name must refer to a static, program variable."},{"name":"entry","dir":"in,out","type":"INTEGER","text":"entry returns the entry number in the variable data table where var_name is located. This variable does not need to be initialized and should not be modified."}],"notes":["This built-in can be used only to pass a parameter to a KAREL routine.","If var_name does not contain a valid variable name or if the variable is not of the type expected as a routine parameter, the program is aborted.","System variables cannot be passed using BYNAME.","The PATH data type cannot be passed using BYNAME. However, a user-defined type that is a PATH can be used instead."],"env":"SYSTEM"},"BYTES_AHEAD":{"kind":"procedure","purpose":"Returns the number of bytes of input data presently in the read-ahead buffer for a KAREL file. Allows KAREL programs to check instantly if data has been received from a serial port and is available to be read by the program. BYTES_AHEAD is also supported on socket messaging and pipes.","params":[{"name":"file_id","dir":"in","type":"FILE","text":"file_id specifies the file that was opened. The file_id must be opened with the ATR_READAHD attribute set greater than zero."},{"name":"n_bytes","dir":"out","type":"INTEGER","text":""},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["n_byte is the number of bytes in the read_ahead buffer.","A non-zero status will be returned for non-serial devices such as files."],"env":"FLBT"},"BYTES_LEFT":{"kind":"function","purpose":"Returns the number of bytes remaining in the current input data record","returns":"INTEGER","params":[{"name":"file_id","dir":"in","type":"FILE","text":"file_id specifies the file that was opened."}],"notes":["If no read or write operations have been done or the last operation was a READ file_id (CR), a zero is returned.","If file_id does not correspond to an opened file or one of the pre-defined ``files'' opened to the respective CRT/KB, teach pendant, and vision windows, the program is aborted. Note An infeed character (LF) is created when the ENTER key is pressed, and is counted by BYTES_LEFT.","This function will return a non-zero value only when data is input from a keyboard (teach pendant or CRT/KB), not from files or ports. Warning This function is used exclusively for reading from a window to determine if more data has been entered. Do not use this function with any other file device. Otherwise, you could injure personnel or damage equipment."],"env":"FLBT"},"CALL_PROG":{"kind":"procedure","purpose":"Allows a KAREL program to call an external KAREL or teach pendant program. This means that the programmer does not have to determine the program to be called until run time.","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name is the name of the program to be executed, in the current calling task."},{"name":"prog_index","dir":"in,out","type":"INTEGER","text":"prog_index returns the entry number in the program table where prog_name is located. This variable does not need to be initialized and should not be modified."}],"notes":["CALL_PROG cannot be used to run internal or external routines."],"env":"PBCORE","seeAlso":["CALL_PROGLIN"]},"CALL_PROGLIN":{"kind":"procedure","purpose":"Allows a KAREL program to call an external KAREL or teach pendant program, beginning at a specified line. This means that the programmer does not need to know, at creation and translation, what program will be called. The programmer can decide this at run time.","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name is the name of the program to be executed, in the current calling task."},{"name":"prog_line","dir":"in","type":"INTEGER","text":"prog_line specifies the line at which to begin execution for a teach pendant program. 0 or 1 is used for the beginning of the program."},{"name":"prog_index","dir":"in,out","type":"INTEGER","text":"prog_index returns the entry number in the program table where prog_name is located. This variable does not need to be initialized and should not be modified."},{"name":"pause_entry","dir":"in","type":"BOOLEAN","text":"pause_entry specifies whether to pause program execution upon entry of the program."}],"notes":["KAREL programs always execute at the beginning of the program.","CALL_PROGLIN cannot be used to run internal or external routines."],"env":"BYNAM","seeAlso":["CALL_PROG"]},"CHECK_DICT":{"kind":"procedure","purpose":"Checks the specified dictionary for a specified element","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name is the name of the dictionary to check."},{"name":"element_no","dir":"in","type":"STRING","text":"element_no is the element number within the dictionary."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then the element could not be found."}],"env":"UIF","seeAlso":["REMOVE_DICT"]},"CHECK_EPOS":{"kind":"procedure","purpose":"Checks that the specified position is valid and that no motion errors will be generated when moving to this position","params":[{"name":"eposn","dir":"in","type":"XYZWPREXT","text":"eposn is the XYZWPREXT position to be checked."},{"name":"uframe","dir":"in","type":"POSITION","text":"uframe specifies the uframe position to use with eposn."},{"name":"utool","dir":"in","type":"POSITION","text":"utool specifies the utool position to use with eposn."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the check. If the position is reachable, the status will be 0."},{"name":"group_no","dir":"in","type":"INTEGER","text":"group_no is optional, but if specified will be the group number for eposn. If not specified the default group of the program is used.","optional":true}],"env":"PBCORE"},"CHECK_NAME":{"kind":"procedure","purpose":"Checks a specified file or program name for illegal characters.","params":[{"name":"name_spec","dir":"in","type":"STRING","text":"Name_spec specifies the string to check for illegal characters. The string can be the file name or program name. It should not include the extension of the file or the program. This built-in does not handle special system names such as *SYSTEM*."},{"name":"status","dir":"out","type":"INTEGER","text":""}],"env":"FDEV"},"CHR":{"kind":"function","purpose":"Returns the character that corresponds to a numeric code","returns":"STRING","params":[{"name":"code","dir":"in","type":"INTEGER","text":"code represents the numeric code of the character for either the ASCII, Graphic, or Multinational character set."}],"notes":["Returns a single character string that is assigned the value of code."],"env":"SYSTEM"},"CLEAR":{"kind":"procedure","purpose":"Clears the specified program and/or variables from memory","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the program name and type of data to clear. The following types are valid: no ext:KAREL or Teach Pendant program and variables.TP:Teach Pendant program.PC:KAREL program.VR:KAREL variables"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"PBCORE"},"CLEAR_SEMA":{"kind":"procedure","purpose":"Clear the indicated semaphore by setting the count to zero","params":[{"name":"semaphore_no","dir":"in","type":"INTEGER","text":"semaphore_no must be in the range of 1 to the number of semaphores defined on the controller."}],"notes":["The semaphore indicated by semaphore_no is cleared.","All semaphores are cleared at COLD start. It is good practice to clear a semaphore prior to using it. Before several tasks begin sharing a semaphore, one and only one of these task, should clear the semaphore."],"env":"MULTI","seeAlso":["PEND_SEMA","SEMA_COUNT"]},"CLOSE_TPE":{"kind":"procedure","purpose":"Closes the specified teach pendant program","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id indicates the teach pendant program to close. All teach pendant programs that are opened must be closed before they can be executed. Any unclosed programs remain opened until the KAREL program which opened it is aborted or runs to completion."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."}],"env":"PBCORE","seeAlso":["OPEN_TPE"]},"CLR_IO_STAT":{"kind":"procedure","purpose":"Clear the results of the last operation on the file argument","params":[{"name":"file_id","dir":"in","type":"FILE","text":"Causes the last operation result on file_id, which is returned by IO_STATUS, to be cleared to zero."}],"env":"PBCORE"},"CLR_PORT_SIM":{"kind":"procedure","purpose":"Sets the specified port to be unsimulated","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port to unsimulate. Codes are defined in FR:KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number to unsimulate."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if parameters are valid and the simulation of the specified port is cleared."}],"env":"IOSETUP","seeAlso":["SET_PORT_SIM"]},"CLR_POS_REG":{"kind":"procedure","purpose":"Removes all data for the specified group in the specified position register","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the register number whose data should be cleared."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is zero, data for all groups is cleared."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"REGOPE","seeAlso":["SET_POS_REG","GET_POS_REG"]},"CNCL_STP_MTN":{"kind":"procedure","purpose":"Cancels all stopped motions","notes":["All stopped motions will be canceled for all groups that the program controls.","The statements following the motion statements will be executed.","CNCL_STP_MTN will have no effect if no motions are currently stopped.","Motion cannot be cancelled for a different task."],"env":"MOTN"},"CNC_DYN_DISB":{"kind":"procedure","purpose":"Cancels the dynamic display based on the value of a BOOLEAN variable in a specified window.","params":[{"name":"b_var","dir":"in","type":"BOOLEAN","text":"b_var is the boolean variable whose dynamic display is to be canceled."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"status","dir":"out","type":"INTEGER","text":"status returns an error if there is no dynamic display active specifying this variable and window. If not equal to 0, then an error occurred."}],"notes":["If there is more than one display active for this variable in this window, all the displays are canceled."],"env":"UIF","seeAlso":["INI_DYN_DISB"]},"CNC_DYN_DISE":{"kind":"procedure","purpose":"Cancels the dynamic display based on the value of an INTEGER variable in a specified window.","params":[{"name":"e_var","dir":"in","type":"INTEGER","text":"e_var is the integer variable whose dynamic display is to be canceled."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"status","dir":"out","type":"INTEGER","text":"status returns an error if there is no dynamic display active specifying this variable and window. If not equal to 0, then an error occurred."}],"notes":["Refer to the CNC_DYN_DISB built-in procedure for a description of the other parameters listed above."],"env":"UIF","seeAlso":["INI_DYN_DISE"]},"CNC_DYN_DISI":{"kind":"procedure","purpose":"Cancels the dynamic display of an INTEGER variable in a specified window.","params":[{"name":"int_var","dir":"in","type":"INTEGER","text":"int_var is the integer variable whose dynamic display is to be canceled."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"status","dir":"out","type":"INTEGER","text":"status returns an error if there is no dynamic display active specifying this variable and window. If not equal to 0, then an error occurred."}],"notes":["Refer to the CNC_DYN_DISB built-in procedure for a description of the other parameters listed above."],"env":"UIF","seeAlso":["INI_DYN_DISI"]},"CNC_DYN_DISP":{"kind":"procedure","purpose":"Cancels the dynamic display based on the value of a port in a specified window.","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type and port_no are integer values specifying the port whose dynamic display is to be canceled."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_type and port_no are integer values specifying the port whose dynamic display is to be canceled."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"status","dir":"out","type":"INTEGER","text":"status returns an error if there is no dynamic display active specifying this variable and window. If not equal to 0, then an error occurred."}],"notes":["Refer to the CNC_DYN_DISB built-in procedure for a description of the other parameters listed above."],"env":"UIF","seeAlso":["INI_DYN_DISP"]},"CNC_DYN_DISR":{"kind":"procedure","purpose":"Cancels the dynamic display of a REAL number variable in a specified window.","params":[{"name":"real_var","dir":"in","type":"REAL","text":"real_var is the REAL variable whose dynamic display is to be canceled."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"status","dir":"out","type":"INTEGER","text":"status returns an error if there is no dynamic display active specifying this variable and window. If not equal to 0, then an error occurred."}],"notes":["Refer to the CNC_DYN_DISB built-in procedure for a description of the other parameters listed above."],"env":"UIF","seeAlso":["INI_DYN_DISR"]},"CNC_DYN_DISS":{"kind":"procedure","purpose":"Cancels the dynamic display of a STRING variable in a specified window.","params":[{"name":"str_var","dir":"in","type":"STRING","text":"str_var is the STRING variable whose dynamic display is to be canceled."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"status","dir":"out","type":"INTEGER","text":"status returns an error if there is no dynamic display active specifying this variable and window. If not equal to 0, then an error occurred."}],"notes":["Refer to the CNC_DYN_DISB built-in procedure for a description of the other parameters listed above."],"env":"UIF","seeAlso":["INI_DYN_DISS"]},"CNV_CNF_STRG":{"kind":"procedure","purpose":"Converts the specified CONFIG into a STRING using an optional group_no","params":[{"name":"source","dir":"in","type":"CONFIG","text":"target receives the STRING form of the configuration specified by source. target must be long enough to accept a valid configuration string for the robot arm attached to the controller. Otherwise, the program will be aborted with an error. Using a length of 25 is generally adequate because the longest configuration string of any robot is 25 characters long."},{"name":"target","dir":"out","type":"STRING","text":"target receives the STRING form of the configuration specified by source. target must be long enough to accept a valid configuration string for the robot arm attached to the controller. Otherwise, the program will be aborted with an error. Using a length of 25 is generally adequate because the longest configuration string of any robot is 25 characters long."},{"name":"group_no","dir":"in","type":"INTEGER","text":"The config mask from group_no is used during conversion. If group_no is omitted, then default group for the program is assumed. If group_no is specified, it must be in the range 1 to the total number of groups defined on the controller.","optional":true}],"env":"STRNG","seeAlso":["CNV_STR_CONF"]},"CNV_CONF_STR":{"kind":"procedure","purpose":"Converts the specified CONFIG into a STRING","params":[{"name":"source","dir":"in","type":"CONFIG","text":"target receives the STRING form of the configuration specified by source. target must be long enough to accept a valid configuration string for the robot arm attached to the controller. Otherwise, the program will be aborted with an error. Using a length of 25 is generally adequate because the longest configuration string of any robot is 25 characters long."},{"name":"target","dir":"out","type":"STRING","text":"target receives the STRING form of the configuration specified by source. target must be long enough to accept a valid configuration string for the robot arm attached to the controller. Otherwise, the program will be aborted with an error. Using a length of 25 is generally adequate because the longest configuration string of any robot is 25 characters long."}],"env":"STRNG","seeAlso":["CNV_STR_CONF"]},"CNV_INT_STR":{"kind":"procedure","purpose":"Formats the specified INTEGER into a STRING","params":[{"name":"source","dir":"in","type":"INTEGER","text":"source is the INTEGER to be formatted into a STRING."},{"name":"length","dir":"in","type":"INTEGER","text":"length specifies the minimum length of the target. The actual length of target may be greater if required to contain the contents of source and at least one leading blank."},{"name":"base","dir":"in","type":"INTEGER","text":"base indicates the number system in which the number is to be represented. base must be in the range 2-16 or 0 (zero) indicating base 10."},{"name":"target","dir":"out","type":"STRING","text":"length specifies the minimum length of the target. The actual length of target may be greater if required to contain the contents of source and at least one leading blank."}],"notes":["If the values of length or base are invalid, target is returned uninitialized.","If target is not declared long enough to contain source and at least one leading blank, it is returned with one blank and the rest of its declared length filled with ``*\"."],"env":"PBCORE","seeAlso":["CNV_STR_INT"]},"CNV_JPOS_REL":{"kind":"procedure","purpose":"Allows a KAREL program to examine individual joint angles as REAL values","params":[{"name":"joint_pos","dir":"in","type":"JOINTPOS","text":"joint_pos is one of the KAREL joint position data types: JOINTPOS, or JOINTPOS1 through JOINTPOS9."},{"name":"real_array","dir":"out","type":"ARRAY[num_joints] OF REAL","text":"num_joints can be smaller than the number of joints in the system. A value of nine can be used if the actual number of joints is unknown. Joint number one will be stored in real_array element number one, etc. Excess array elements will be ignored."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["The measurement of the real_array elements is in degrees."],"env":"SYSTEM","seeAlso":["CNV_REL_JPOS"]},"CNV_REAL_STR":{"kind":"procedure","purpose":"Formats the specified REAL value into a STRING","params":[{"name":"source","dir":"in","type":"REAL","text":"source is the REAL value to be formatted."},{"name":"length","dir":"in","type":"INTEGER","text":"length specifies the minimum length of the target. The actual length of target may be greater if required to contain the contents of source and at least one leading blank."},{"name":"num_digits","dir":"in","type":"INTEGER","text":"num_digits specifies the number of digits displayed to the right of the decimal point. If num_digits is a negative number, source will be formatted in scientific notation (where the ABS(num_digits) represents the number of digits to the right of the decimal point.) If num_digits is 0, the decimal point is suppressed."},{"name":"target","dir":"out","type":"STRING","text":"length specifies the minimum length of the target. The actual length of target may be greater if required to contain the contents of source and at least one leading blank."}],"notes":["If length or num_digits are invalid, target is returned uninitialized.","If the declared length of target is not large enough to contain source with one leading blank, target is returned with one leading blank and the rest of its declared length filled with ``*''s (asterisks)."],"env":"STRNG","seeAlso":["CNV_STR_REAL"]},"CNV_REL_JPOS":{"kind":"procedure","purpose":"Allows a KAREL program to manipulate individual angles of a joint position","params":[{"name":"real_array","dir":"in","type":"ARRAY[num_joints] OF REAL","text":"real_array must have a declared size, equal to or greater than, the number of joints in the system. A value of nine can be used for num_joints, if the actual number of joints is unknown. Array element number one will be stored in joint number one, and so forth. Excess array elements will be ignored. If the array is not large enough the program will abort with an invalid argument error."},{"name":"joint_pos","dir":"out","type":"JOINTPOS","text":"joint_pos is one of the KAREL joint position types: JOINTPOS, or JOINTPOS1 through JOINTPOS9. joint_pos receives the joint position form of real_array."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If any of the elements of real_array that correspond to a joint angle are uninitialized, the program will be paused with an uninitialized variable error.","The measurement of the real_array elements is degrees."],"env":"SYSTEM"},"CNV_STR_CONF":{"kind":"procedure","purpose":"Converts the specified configuration string into a CONFIG data type","params":[{"name":"source","dir":"in","type":"STRING","text":"source must be a valid configuration string for the robot arm attached to the controller."},{"name":"target","dir":"out","type":"CONFIG","text":"target receives the CONFIG form of the configuration string specified by source."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"STRNG","seeAlso":["CNV_CONF_STR"]},"CNV_STR_INT":{"kind":"procedure","purpose":"Converts the specified STRING into an INTEGER","params":[{"name":"source","dir":"in","type":"STRING","text":"source is converted into an INTEGER and stored in target."},{"name":"target","dir":"out","type":"INTEGER","text":"source is converted into an INTEGER and stored in target."}],"notes":["If source does not contain a valid representation of an INTEGER, target is set uninitialized."],"env":"PBCORE","seeAlso":["CNV_INT_STR"]},"CNV_STR_REAL":{"kind":"procedure","purpose":"Converts the specified STRING into a REAL","params":[{"name":"source","dir":"in","type":"STRING","text":"Converts source to a REAL number and stores the result in target."},{"name":"target","dir":"out","type":"REAL","text":"Converts source to a REAL number and stores the result in target."}],"notes":["If source is not a valid decimal representation of a REAL number, target will be set uninitialized. source may contain scientific notation of the form nn.nnEsnn where s is a + or - sign."],"env":"PBCORE","seeAlso":["CNV_REAL_STR"]},"CNV_STR_TIME":{"kind":"procedure","purpose":"Converts a string representation of time to an integer representation of time.","params":[{"name":"source","dir":"in","type":"STRING","text":"source must be entered using ``DD-MMM-YYY HH:MM:SS'' format. The seconds specifier, ``SS,'' is optional. A value of zero (0) is used if seconds is not specified. If source is invalid, target will be set to 0."},{"name":"target","dir":"out","type":"INTEGER","text":"target can be used with the SET_TIME Built-In Procedure to reset the time on the system. If target is 0, the time on the system will not be changed."}],"notes":["The size of the string parameter, source, is STRING[20]."],"env":"TIM","seeAlso":["SET_TIME"]},"CNV_TIME_STR":{"kind":"procedure","purpose":"Converts an INTEGER representation of time to a STRING","params":[{"name":"source","dir":"in","type":"INTEGER","text":"The GET_TIME Built-In Procedure is used to determine the INTEGER representation of time. CNV_TIME_STR is used to convert source to target, which will be displayed in ``DD-MMM-YYY HH:MM:'' format."},{"name":"target","dir":"out","type":"STRING","text":"The GET_TIME Built-In Procedure is used to determine the INTEGER representation of time. CNV_TIME_STR is used to convert source to target, which will be displayed in ``DD-MMM-YYY HH:MM:'' format."}],"env":"TIM","seeAlso":["GET_TIME"]},"COMPARE_FILE":{"kind":"procedure","purpose":"Compares the contents of one file with anotherfile","params":[{"name":"filea","dir":"in","type":"STRING","text":"filea specifies the device, name, and type of the file to compare. If no device is specified, the default device is used. You must specify both a name and type."},{"name":"fileb","dir":"in","type":"STRING","text":"fileb specifies the device, name, and type of the file to compare. If no device is specified, the default device is used. You must specify both a name and type."},{"name":"result_file","dir":"out","type":"FILE","text":"result_file this must be an open FILE variable open for write. The comparison result will be written to this FILE."},{"name":"ascii_flag","dir":"in","type":"BOOLEAN","text":"ascii_flag specifies that the file(s) should be compared based on ASCII (text) content."},{"name":"diff_count","dir":"out","type":"INTEGER","text":"diff_count how many ASCII (text) lines differed."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"FDEV","seeAlso":["DELETE_FILE"]},"CONT_TASK":{"kind":"procedure","purpose":"Continues the specified task","params":[{"name":"task_name","dir":"in","type":"STRING","text":"task_name is the name of the task to be continued. If the task was not paused, an error is returned in status."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["A task can be in an interrupt routine when CONT_TASK is executed. However, you should be aware of the following circumstances because CONT_TASK only affects the current interrupt level, and interrupt levels of a task might be independently paused or running. — If the interrupt routine and the task are both paused, CONT_TASK will continue the interrupt routine but the task will remain paused. — If the interrupt routine is running and the task is paused, CONT_TASK will appear to have no effect because it will try to continue the running interrupt routine. — If the interrupt routine is paused and the task is running, CONT_TASK will continue the interrupt routine."],"env":"MULTI","seeAlso":["PAUSE_TASK"]},"COPY_FILE":{"kind":"procedure","purpose":"Copies the contents of one file to another with the overwrite option","params":[{"name":"from_file","dir":"in","type":"STRING","text":"from_file specifies the device, name, and type of the file from which to copy. from_file can be specified using the wildcard (*) character. If no device is specified, the default device is used. You must specify both a name and type. However, these can be a wildcard (*) character."},{"name":"to_file","dir":"in","type":"STRING","text":"to_file specifies the device, name, and type of the file to which to copy. to_file can be specified using the wildcard (*) character. If no device is specified, the default device is used."},{"name":"overwrite_sw","dir":"in","type":"BOOLEAN","text":"overwrite_sw specifies that the file(s) should be overwritten if they exist."},{"name":"nowait_sw","dir":"in","type":"BOOLEAN","text":"If nowait_sw is TRUE, execution of the program continues while the command is executing. If it is FALSE, the program stops, including condition handlers, until the operation is complete. If you have time critical condition handlers in the program, put them in another program that executes as a separate task."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If the program is aborted during the copy, the copy will completed before aborting.","If the device you are copying to becomes full during the copy, an error will be returned. Note nowait_sw is not available in this release and should be set to FALSE."],"env":"FDEV","seeAlso":["DELETE_FILE"]},"COPY_PATH":{"kind":"procedure","purpose":"Copies a complete path, part of a path, or a path in reverse node order (including associated data), to another identical type path variable.","params":[{"name":"source_path","dir":"in","type":"PATH","text":"source_path specifies the source path to copy from. This path can be a standard path or a user defined path."},{"name":"start_node","dir":"in","type":"INTEGER","text":"start_node specifies the number of the first node to copy. A value of 0 will copy the complete path, including header information. The start_node number must be between 0 and the highest node number in the source path. Otherwise, error status will be returned."},{"name":"end_node","dir":"in","type":"INTEGER","text":"end_node specifies the number of the last node to copy. A value of 0 will copy the complete path, including header information. The end_node number must be between 0 and the highest node number of the source path. Otherwise, error status will be returned."},{"name":"dest_path","dir":"in","type":"PATH","text":"dest_path specifies the destination path to copy to. This path can be a standard path or a user defined path. However, the dest_path type must be identical to the source_path type. If they are not identical, an error status will be returned."},{"name":"status","dir":"out","type":"INTEGER","text":"status of 0 is returned if the parameters are valid and the COPY_PATH operation was successful. Non-zero status indicates the COPY_PATH operation was unsuccessful. Note To copy a complete path from one path variable to another identical path variable, set the start_node and end_node parameters to 0 (zero). An example of a partial path copy to a destination path. Executing the COPY_PATH(P1, 2, 5, P2) command will copy node 2 through node 5 (inclusive) of path P1 to node 1 through 4 of Path P2, provided the path length of P1 is greater than or equal to 5. The destination path P2 will become a 4 node path. The original destination path is completely overwritten. An example of a source path copy in reverse order to a destination path. Executing the COPY_PATH(P1, 5, 2, P2) command will copy node 5 through node 2 (inclusive) of path P1 to node 1 through 4 of Path P2, provided the path length of P1 is greater than or equal to 5. The destination path P2 will become a 4 node path. The original destination path is completely overwritten. Specifically, the above command will copy node 5 of P1 to node 1 of P2, node 4 of P1 to node 2 of P2, and so forth."}],"env":"PATHOP"},"COPY_QUEUE":{"kind":"procedure","purpose":"Copies one or more consecutive entries from a queue into an array of integers. The entries are not removed but are copied, starting with the oldest and proceeding to the newest, or until the output array, or integers, are full. A parameter specifies the number of entries at the head of the list (oldest entries) to be skipped.","params":[{"name":"queue_t","dir":"in","type":"QUEUE_TYPE","text":"queue_t specifies the queue variable for the queue from which the values are to be read."},{"name":"queue_data","dir":"in","type":"ARRAY OF INTEGER","text":"queue_data specifies the array variable for the queue from which the values are to be read."},{"name":"n_skip","dir":"in","type":"INTEGER","text":"n_skip specifies the number of oldest entries to be skipped. A value of zero indicates to return the oldest entries."},{"name":"sequence_no","dir":"in","type":"INTEGER","text":"sequence_no specifies the sequence number of the oldest entry to be copied. If the sequence_no is zero, the starting point for the copy is determined by the n_skip parameter."},{"name":"out_data","dir":"out","type":"ARRAY OF INTEGER","text":"out_data is an integer array into which the values are to be copied; the size of the array is the maximum number of values returned."},{"name":"n_got","dir":"out","type":"INTEGER","text":"n_got is returned with the number of entries returned. This will be one of the following: — Zero if there are n_skip or fewer entries in the queue. — (queue_to n_entries_skip) if this is less than ARRAY_LEN(out_data) — ARRAY_LEN(out_data) if this is less than or equal to queue.n_entries - n_skip"},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero"}],"env":"PBQMGR","seeAlso":["INSERT_QUEUE"]},"COPY_TPE":{"kind":"procedure","purpose":"Copies one teach pendant program to another teach pendant program.","params":[{"name":"from_prog","dir":"in","type":"STRING","text":"from_prog specifies the teach pendant program name, without the.tp extension, to be copied."},{"name":"to_prog","dir":"in","type":"STRING","text":"to_prog specifies the new teach pendant program name, without the.tp extension, that from_prog will be copied to."},{"name":"overwrite_sw","dir":"in","type":"BOOLEAN","text":"overwrite_sw, if set to TRUE, will automatically overwrite the to_prog if it already exists and it is not currently selected. If set to FALSE, the to_prog will not be overwritten if it already exists."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, the copy did not occur."}],"env":"TPE","seeAlso":["CREATE_TPE"]},"COS":{"kind":"function","purpose":"Returns the REAL cosine of the REAL angle argument, specified in degrees","params":[{"name":"angle","dir":"in","type":"REAL","text":"angle is an angle specified in the range of ±18000 degrees. Otherwise, the program will be aborted with an error."}],"env":"SYSTEM"},"CREATE_TPE":{"kind":"procedure","purpose":"Creates a teach pendant program of the specified name","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the program to be created."},{"name":"prog_type","dir":"in","type":"INTEGER","text":"prog_type specifies the type of the program to be created. The following constants are valid for program type: PT_MNE_UNDEF:TPE program of undefined sub type PT_MNE_JOB:TPE job PT_MNE_PROC:TPE process PT_MNE_MACRO:TPE macro"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If it is not equal to 0, then an error occurred. Some of the possible errors are as follows: 7015 Specified program exist 9030 Program name is NULL 9031 Remove num from top of Program name 9032 Remove space from Program name 9036 Memory is not enough 9038 Invalid character in program name"}],"notes":["The program is created to reference all motion groups on the system. The program is created without any comment or any other program attributes. Once the program is created, SET_ATTR_PRG can be used to specify program attributes."],"env":"TPE","seeAlso":["SET_ATTR_PRG"]},"CREATE_VAR":{"kind":"procedure","purpose":"Creates the specified KAREL variable","params":[{"name":"var_prog_nam","dir":"in","type":"STRING","text":"var_prog_nam specifies the program name that the variable should be created in. If var_prog_nam is ' ', the default, which is the name of the program currently executing, is used."},{"name":"var_nam","dir":"in","type":"STRING","text":"var_nam specifies the variable name that will be created."},{"name":"typ_prog_nam","dir":"in","type":"STRING","text":"If a variable is to be created as a user-defined type, the user-defined type must already be created in the system. typ_prog_nam specifies the program name of the user-defined type. If typ_prog_nam is ' ', the default, which is the name of the program currently executing, is used."},{"name":"type_nam","dir":"in","type":"STRING","text":"type_nam specifies the type name of the variable to be created. The following type names are valid: 'ARRAY OF BYTE' 'ARRAY OF SHORT' 'BOOLEAN' 'CAM_SETUP' 'CONFIG' 'FILE' 'INTEGER' 'JOINTPOS' 'JOINTPOS1' 'JOINTPOS2' 'JOINTPOS3' 'JOINTPOS4' 'JOINTPOS5' 'JOINTPOS6' 'JOINTPOS7' 'JOINTPOS8' 'JOINTPOS9' 'MODEL' 'POSITION' 'REAL' 'STRING[n]', where n is the string length; the default is 12 if not specified. 'VECTOR' 'VIS_PROCESS' 'XYZWPR' 'XYZWPREXT' Any other type names are considered user-defined types."},{"name":"group_num","dir":"in","type":"INTEGER","text":"group_num specifies the group number to be used for positional data types."},{"name":"inner_dim","dir":"in","type":"INTEGER","text":"inner_dim specifies the dimensions of the innermost array. For example, inner_dim = 30 for ARRAY[10,20,30] OF INTEGER. inner_dim should be set to 0 if the variable is not an array."},{"name":"mid_dim","dir":"in","type":"INTEGER","text":"mid_dim specifies the dimensions of the middle array. For example, mid_dim = 20 for ARRAY[10,20,30] OF INTEGER. mid_dim should be set to 0 if the variable is not a 2-D array."},{"name":"outer_dim","dir":"in","type":"INTEGER","text":"outer_dim specifies the dimensions of the outermost array. For example, outer_dim = 10 for ARRAY[10,20,30] OF INTEGER. outer_dim should be set to 0 if the variable is not a 3-D array."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."},{"name":"mem_pool","dir":"in","type":"INTEGER","text":"mem_pool is an optional parameter that specifies the memory pool from which the variable is created. If not specified, then the variable is created in DRAM which is temporary memory. The DRAM variable must be recreated at every power up and the value is always reset to uninitialized.","optional":true}],"notes":["If mem_pool = -1, then the variable is created in CMOS RAM which is permanent memory."],"env":"MEMO","seeAlso":["RENAME_VAR"]},"CURJPOS":{"kind":"function","purpose":"Returns the current joint position of the tool center point (TCP) for the specified group of axes, even if one of the axes is in an overtravel","returns":"JOINTPOS","params":[{"name":"axs_lim_mask","dir":"out","type":"INTEGER","text":"axs_lim_mask specifies which axes are outside the axis limits."},{"name":"ovr_trv_mask","dir":"out","type":"INTEGER","text":"ovr_trv_mask specifies which axes are in overtravel. Note axis_limit_mask and ovr_trv_mask are not available in this release and can be set to 0."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed.","optional":true}],"notes":["If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"SYSTEM","seeAlso":["CURPOS"]},"CURPOS":{"kind":"function","purpose":"Returns the current Cartesian position of the tool center point (TCP) for the specified group of axes even if one of the axes is in an overtravel","returns":"XYZWPREXT","params":[{"name":"axis_limit_mask","dir":"out","type":"INTEGER","text":"axis_limit_mask specifies which axes are outside the axis limits."},{"name":"ovr_trv_mask","dir":"out","type":"INTEGER","text":"ovr_trv_mask specifies which axes are in overtravel. Note axis_limit_mask and ovr_trv_mask are not available in this release and will be ignored if set."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed.","optional":true}],"notes":["If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller.","The group must be kinematic.","Returns the current position of the tool center point (TCP) relative to the current value of the system variable $UFRAME for the specified group."],"env":"SYSTEM"},"CURR_PROG":{"kind":"function","purpose":"Returns the name of the program currently being executed","returns":"STRING[12]","notes":["The variable assigned to CURR_PROG must be declared with a string variable length ≥12"],"env":"BYNAM"},"DAQ_CHECKP":{"kind":"procedure","purpose":"To check the status of a pipe and the number of bytes available to be read from the pipe.","params":[{"name":"pipe_num","dir":"in","type":"INTEGER","text":"pipe_num is the number of the pipe (1 - 5) to check."},{"name":"pipe_stat","dir":"out","type":"INTEGER","text":"pipe_stat is the status of the pipe returned. The status is a combination of the following flags: — DAQ_PIPREG is when the pipe is registered (value = 1). — DAQ_ACTIVE is when the pipe is active, i.e., has been started (value = 2). — DAQ_CREATD is when the pipe is created (value = 4). — DAQ_SNAPSH is when the pipe is in snapshot mode (value = 8). — DAQ_1STRD is when the pipe has been read for the first time (value = 16). — DAQ_OVFLOW is when the pipe is overflowed (value = 32). — DAQ_FLUSH is when the pipe is being flushed (value = 64)."},{"name":"bytes_avail","dir":"out","type":"INTEGER","text":"bytes_avail is the number of bytes that are available to be read from the pipe. DAQ_CHECKP Built-In Procedure The pipe_stat returned parameter can be AND'ed with the above flag constants to determine whether the pipe is registered, is active, and so forth. For example, you must check to see if the pipe is active before writing to it. DAQ_CHECKP Built-In Procedure The DAQ_OVFLOW flag will never be set for the task that writes to the pipe when it calls DAQ_CHECKP. This flag applies only to tasks that read from the pipe."}],"seeAlso":["DAQ_WRITE"]},"DAQ_REGPIPE":{"kind":"procedure","purpose":"To register a pipe for use in KAREL.","params":[{"name":"pipe_num","dir":"in","type":"INTEGER","text":"pipe_num is the number of the pipe (1-5) to be registered."},{"name":"mem_type","dir":"in","type":"INTEGER","text":"mem_type allows you to allocate the memory to be used for the pipe. The following constants can be used: — DAQ_DRAM allows you to allocate DRAM memory. — DAQ_CMOS allows you to allocate CMOS memory."},{"name":"pipe_size","dir":"in","type":"INTEGER","text":"pipe_size is the size of the pipe, is expressed as the number of data records that it can hold. The data record size itself is determined by the data type of var_name."},{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name is the name of the program containing the variable to be used for writing to the pipe. If passed as an empty string, the name of the current program is used."},{"name":"var_name","dir":"in","type":"STRING","text":"var_name is the name of the variable that defines the data type to be used for writing to the pipe. Once registered, you can write any variable of this data type to the pipe."},{"name":"pipe_name","dir":"in","type":"STRING","text":"pipe_name is the name of the pipe file. For example, if the pipe name is passed as 'foo.dat', the pipe will be accessible using the file string 'PIP:FOO.DAT'. A unique file name with an extension is required even if the pipe is being used only for sending to the PC."},{"name":"stream_size","dir":"in","type":"INTEGER","text":"stream_size is the number of records to automatically stream to an output file, if the pipe is started as a streamed pipe. A single write of the specified variable constitutes a single record in the pipe. If stream size is set to zero, the pipe will not automatically stream records to a file device; all data will be kept in the pipe until the pipe is read. Use stream_size to help optimize network loading when the pipe is used to send data to the PC. If it is zero or one, the monitoring task will send each data record as soon as it is seen in the pipe. If the number is two or more, the monitor will wait until there are that many data records in the pipe before sending them all to the PC. In this manner, the overhead of sending network packets can be minimized. Data will not stay in the pipe longer than the time specified by the FlushTime argument supplied with the FRCPipe.StartMonitor Method."},{"name":"status","dir":"out","type":"INTEGER","text":"status is the status of the attempted operation. If not 0, then an error occurred and the pipe was not registered."}],"env":"DAQ","seeAlso":["DAQ_UNREG"]},"DAQ_START":{"kind":"procedure","purpose":"To activate a KAREL pipe for writing.","params":[{"name":"pipe_num","dir":"in","type":"INTEGER","text":"pipe_num is the number of the pipe (1 - 5) to be started. The pipe must have been previously registered"},{"name":"pipe_mode","dir":"in","type":"INTEGER","text":"pipe_mode is the output mode to be used for the pipe. The following constants are used: — DAQ_SNAPSHT is the snapshot mode (each read of the pipe will result in all of the pipe's contents). — DAQ_STREAM is the stream mode (each read from the same pipe file will result in data written since the previous read)."},{"name":"stream_dev","dir":"in","type":"STRING","text":"stream_dev is the device to which records will be automatically streamed. This parameter is ignored if the stream size was set to 0 during registration."},{"name":"status","dir":"out","type":"INTEGER","text":"status is the status of the attempted operation. If not 0, then an error occurred and the pipe was not unregistered."}],"env":"DAQ","seeAlso":["DAQ_REGPIPE","DAQ_STOP"]},"DAQ_STOP":{"kind":"procedure","purpose":"To stop a KAREL pipe for writing.","params":[{"name":"pipe_num","dir":"in","type":"INTEGER","text":"pipe_num is the number of the pipe (1 - 5) to be stopped."},{"name":"force_off","dir":"in","type":"BOOLEAN","text":"force_off occurs if TRUE force the pipe to be turned off, even if another application made a start request on the pipe. If set FALSE, if all start requests have been accounted for with stop requests, the pipe is turned off, else it remains on."},{"name":"status","dir":"out","type":"INTEGER","text":"status is the status of the attempted operation. If not 0, then an error occurred and the pipe was not stopped."}],"seeAlso":["DAQ_START"]},"DAQ_UNREG":{"kind":"procedure","purpose":"To unregister a previously-registered KAREL pipe, so that it may be used for other data.","params":[{"name":"pipe_num","dir":"in","type":"INTEGER","text":"pipe_num is the number of the pipe (1 - 5) to be unregistered."},{"name":"status","dir":"out","type":"INTEGER","text":"status is the status of the attempted operation. If not 0, then an error occurred and the pipe was not unregistered."}],"env":"DAQ","seeAlso":["DAQ_REGPIPE"]},"DAQ_WRITE":{"kind":"procedure","purpose":"To write data to a KAREL pipe.","params":[{"name":"pipe_num","dir":"in","type":"INTEGER","text":"pipe_num is the number of the pipe (1 - 5) to which data is written."},{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name is the name of the program containing the variable to be written. If passed as an empty string, the name of the current program is used."},{"name":"var_name","dir":"in","type":"STRING","text":"var_name is the name of the variable to be written."},{"name":"status","dir":"out","type":"INTEGER","text":"status is the status of the attempted operation. If not 0, then an error occurred and the data was not written."}],"env":"DAQ"},"DEF_SCREEN":{"kind":"procedure","purpose":"Defines a screen","params":[{"name":"screen_name","dir":"in","type":"STRING","text":"screen_name must be a unique, valid name (string), one to four characters long."},{"name":"disp_dev_name","dir":"in","type":"STRING","text":"disp_dev_name must be one of the display devices already defined, otherwise an error is returned. The following are the predefined display devices: 'TP' Teach Pendant Device'CRT' CRT/KB Device"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. (If not equal to 0, then an error occurred.)"}],"notes":["Define a screen, associated with a specified display device, to which windows could be attached and be activated (displayed)."],"env":"UIF","seeAlso":["ACT_SCREEN"]},"DEF_WINDOW":{"kind":"procedure","purpose":"Define a window","params":[{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a valid name string, one to four characters long, and must not duplicate a window with the same name."},{"name":"n_rows","dir":"in","type":"INTEGER","text":"n_rows and n_cols specify the size of the window in standard-sized characters. Any line containing double-wide or double-wide-double-high characters will contain only half this many characters. The first row and column begin at 1."},{"name":"n_cols","dir":"in","type":"INTEGER","text":"n_rows and n_cols specify the size of the window in standard-sized characters. Any line containing double-wide or double-wide-double-high characters will contain only half this many characters. The first row and column begin at 1."},{"name":"options","dir":"in","type":"INTEGER","text":"options must be one of the following: 0:No option wd_com_cursr:Common cursor wd_scrolled:Vertical scrolling wd_com_cursr + wd_scrolled:Common cursor + Vertical scrolling"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Define a window that can be attached subsequently to a screen, have files opened to it, be written or have input echoed to it, and have information dynamically displayed in it.","If common cursor is specified, wherever a write leaves the cursor is where the next write will go, regardless of the file variable used. Also, any display attributes set for any file variable associated with this window will apply to all file variables associated with the window. If this is not specified, the cursor position and display attributes (except character size attributes, which always apply to the current line of a window) are maintained separately for each file variable open to the window. The common-cursor attribute is useful for windows that can be written to by more than one task and where these writes are to appear end-to-end. An example might be a log display.","If vertical scrolling is specified and a line-feed, new-line, or index-down character is received and the cursor is in the bottom line of the window, all lines except the top line are moved up and the bottom line is cleared. If an index-up character is written, all lines except the bottom line are moved down and the top line is cleared. If this is not specified, the bottom or top line is cleared, but the rest of the window is unaffected."],"env":"PBCORE","seeAlso":["ATT_WINDOW_S"]},"DELETE_FILE":{"kind":"procedure","purpose":"Deletes the specified file","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the device, name, and type of the file to delete. file_spec can be specified using the wildcard (*) character. If no device name is specified, the default device is used."},{"name":"nowait_sw","dir":"in","type":"BOOLEAN","text":"If nowait_sw is TRUE, execution of the program continues while the command is executing. If it is FALSE, the program stops, including condition handlers, until the operation is complete. If you have time critical condition handlers in the program, put them in another program that executes as a separate task. Note nowait_sw is not available in this release and should be set to FALSE."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"FDEV","seeAlso":["RENAME_FILE"]},"DELETE_NODE":{"kind":"procedure","purpose":"Deletes a path node from a PATH","params":[{"name":"path_var","dir":"in","type":"PATH","text":"node_num specifies the node to be deleted from the PATH specified by path_var. node_num must be in the range from one to PATH_LEN(path_var). If it is outside this range, the status is returned with an error."},{"name":"node_num","dir":"in","type":"INTEGER","text":"node_num specifies the node to be deleted from the PATH specified by path_var. node_num must be in the range from one to PATH_LEN(path_var). If it is outside this range, the status is returned with an error."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["All nodes past the deleted node will be renumbered."],"env":"PATHOP","seeAlso":["INSERT_NODE"]},"DELETE_QUEUE":{"kind":"procedure","purpose":"Deletes an entry from a queue","params":[{"name":"sequence_no","dir":"in","type":"INTEGER","text":"sequence_no specifies the sequence number of the entry to be deleted. Use COPY_QUEUE to get a list of the sequence numbers."},{"name":"queue_t","dir":"in,out","type":"QUEUE_TYPE","text":"queue_t specifies the queue variable for the queue."},{"name":"queue_data","dir":"in,out","type":"ARRAY OF INTEGER","text":"queue_data specifies the array used to hold the data in the queue. The length of this array determines the maximum number of entries in the queue."},{"name":"status","dir":"out","type":"INTEGER","text":"status returns 61003, ``Bad sequence no,'' if the specified sequence number is not in the queue."}],"notes":["Use COPY_QUEUE to get a list of the sequence numbers."],"env":"PBQMGR","seeAlso":["INSERT_QUEUE"]},"DEL_INST_TPE":{"kind":"procedure","purpose":"Deletes the specified instruction in the specified teach pendant program","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. A program must be opened with read/write access, using the OPEN_TPE built-in, before calling the DEL_INST_TPE built-in."},{"name":"lin_num","dir":"in","type":"INTEGER","text":"lin_num specifies the line number of the instruction to be deleted."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."}],"env":"TPE","seeAlso":["SELECT_TPE"]},"DET_WINDOW":{"kind":"procedure","purpose":"Detach a window from a screen","params":[{"name":"window_name","dir":"in","type":"STRING","text":"window_name and screen_name must be valid and already defined."},{"name":"screen_name","dir":"in","type":"STRING","text":"window_name and screen_name must be valid and already defined."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Removes the specified window from the specified screen.","The areas of other window(s) hidden by this window are redisplayed. Any area occupied by this window and not by any other window is cleared.","An error occurs if the window is not attached to the screen."],"env":"PBCORE","seeAlso":["ATT_WINDOW_D"]},"DISCTRL_ALPH":{"kind":"procedure","purpose":"Displays and controls alphanumeric string entry in a specified window.","params":[{"name":"window_name","dir":"in","type":"STRING","text":"window_name identifies the window where the str is currently displayed."},{"name":"row","dir":"in","type":"INTEGER","text":"row specifies the row number where the str is displayed."},{"name":"col","dir":"in","type":"INTEGER","text":"col specifies the column number where the str is displayed."},{"name":"str","dir":"in,out","type":"STRING","text":"str specifies the KAREL string to be modified, which is currently displayed on the window_name at position row and col."},{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the dictionary that contains the words that can be entered. dict_name can also be set to one of the following predefined values. 'PROG':program name entry 'COMM':comment entry"},{"name":"dict_ele","dir":"in","type":"INTEGER","text":"dict_ele specifies the dictionary element number for the words. dict_ele can contain a maximum of 5 lines with no \"&new_line\" accepted on the last line. See the example below."},{"name":"term_char","dir":"out","type":"INTEGER","text":"term_char receives a code indicating the character that terminated the menu. The code for key terminating conditions are defined in the include file FR:KLEVKEYS.KL. The following predefined constants are keys that are normally returned: ky_enter ky_prev ky_new_menu"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of an attempted operation. If not equal to 0, then an error occurred. Note DISCTRL_ALPH will only display and control string entry if the USER or USER2 menu is the selected menu. Therefore, use FORCE_SPMENU(device_stat, SPI_TPUSER, 1) before calling DISCTRL_ALPH to force the USER menu."}],"notes":["If a predefined value for dict_name is used, then dict_ele is ignored.","DISCTRL_ALPH will display and control string entry from the teach pendant device. To display and control string entry from the CRT/KB device, you must create an INTEGER variable, device_stat, and set it to crt_panel. To set control to the teach pendant device, set device_stat to tp_panel. Refer to the example below."],"env":"UIF","seeAlso":["DISCTRL_LIST"]},"DISCTRL_FORM":{"kind":"procedure","purpose":"Displays and controls a form on the teach pendant or CRT/KB screen","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name is the four-character name of the dictionary containing the form."},{"name":"ele_number","dir":"in","type":"INTEGER","text":"ele_number is the element number of the form."},{"name":"value_array","dir":"in","type":"ARRAY OF STRING","text":"value_array is an array of variable names that corresponds to each edit or display only data item in the form. Each variable name can be specified as a '[prog_name]var_name'. — [prog_name] is the name of the program that contains the specified variable. If [prog_name] is not specified, the current program being executed is used. '[*SYSTEM*]' should be used for system variables. — var_name must refer to a static, global program variable. — var_name can contain node numbers, field names, and/or subscripts. — var_name can also specify a port variable with index. For example, 'DIN[1]'."},{"name":"inactive_array","dir":"in","type":"ARRAY OF BOOLEAN","text":"inactive_array is an array of booleans that corresponds to each item in the form. — Each boolean defaults to FALSE, indicating it is active. — You can set any boolean to TRUE which will make that item inactive and non-selectable. — The array size can be greater than or less than the number of items in the form. — If an inactive_array is not used, then an array size of 1 can be used. The array does not need to be initialized."},{"name":"change_array","dir":"out","type":"ARRAY OF BOOLEAN","text":"change_array is an array of booleans that corresponds to each edit or display only data item in the form. — If the corresponding value is set, then the boolean will be set to TRUE, otherwise it is set to FALSE. You do not need to initialize the array. — The array size can be greater than or less than the number of data items in the form. — If change_array is not used, an array size of 1 can be used."},{"name":"term_mask","dir":"in","type":"INTEGER","text":"term_mask is a bit-wise mask indicating conditions that will terminate the form. This should be an OR of the constants defined in the include file klevkmsk.kl. kc_func_key — Function keys kc_enter_key — Enter and Return keys kc_prev_key — PREV key If either a selectable item or a new menu is selected, the form will always terminate, regardless of term_mask."},{"name":"def_item","dir":"in,out","type":"INTEGER","text":"For version 6.20 and 6.21, def_item receives the item you want to be highlighted when the form is entered. def_item returns the item that was currently highlighted when the termination character was pressed."},{"name":"term_char","dir":"out","type":"INTEGER","text":"term_char receives a code indicating the character or other condition that terminated the form. The codes for key terminating conditions are defined in the include file klevkeys.kl. Keys normally returned are pre-defined constants as follows: ky_undef — No termination character was pressed ky_select — A selectable item was selected ky_new_menu — A new menu was selected ky_f1 — Function key 1 was selected ky_f2 — Function key 2 was selected ky_f3 — Function key 3 was selected ky_f4 — Function key 4 was selected ky_f5 — Function key 5 was selected ky_f6 — Function key 6 was selected ky_f7 — Function key 7 was selected ky_f8 — Function key 8 was selected ky_f9 — Function key 9 was selected ky_f10 — Function key 10 was selected"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If status returns a value other than 0, an error has occurred. Note DISCTRL_FORM will only display the form if the USER2 menu is the selected menu. Therefore, use FORCE_SPMENU(device_stat, SPI_TPUSER2, 1) before calling DISCTRL_FORM to force the USER2 menu."}],"notes":["For version 6.22 and later, def_item receives the item you want to be highlighted when the form is entered. def_item is continuously updated while the form is displayed and contains the number of the item that is currently highlighted","DISCTRL_FORM will display the form on the teach pendant device. To display the form on the CRT/KB device, you must create an INTEGER variable, device_stat, and set it to crt_panel. To set control to the teach pendant device, set device_stat to tp_panel."],"env":"PBCORE"},"DISCTRL_LIST":{"kind":"procedure","purpose":"Displays and controls cursor movement and selection in a list in a specified window","params":[{"name":"display_data","dir":"in,out","type":"DISP_DAT_T","text":"display_data is used to display the list. Refer to the DISP_DAT_T data type for details."},{"name":"list_data","dir":"in","type":"ARRAY OF STRING","text":"list_data contains the list of data to display."},{"name":"action","dir":"in","type":"INTEGER","text":"action must be one of the following: dc_disp: Positions cursor as defined in display_data dc_up: Moves cursor up one row dc_dn: Moves cursor down one row dc_lf: Moves cursor left one field dc_rt: Moves cursor right one field"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["file_var must be opened to the window where the list data is to appear.","Using DISCTRL_FORM is the preferred method for displaying and controlling information in a window."],"env":"PBCORE","seeAlso":["DISCTRL_FORM"]},"DISCTRL_PLMN":{"kind":"procedure","purpose":"Creates and controls cursor movement and selection in a pull-up menu","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the name of the dictionary that contains the menu data."},{"name":"element_no","dir":"in","type":"INTEGER","text":"element_no is the element number of the first menu item within the dictionary."},{"name":"ftn_key_num","dir":"in","type":"INTEGER","text":"ftn_key_num is the function key where the pull-up menu should be displayed."},{"name":"def_item","dir":"in,out","type":"INTEGER","text":"def_item is the item that should be highlighted when the menu is entered. 1 specifies the first item. On return, def_item is the item that was currently highlighted when the termination character was pressed."},{"name":"term_char","dir":"out","type":"INTEGER","text":"term_char receives a code indicating the character that terminated the menu. The codes for key terminating conditions are defined in the include file FROM:KLEVKEYS.KL. Keys normally returned are pre-defined constants as follows: ky_enter — A menu item was selected ky_prev — A menu item was not selected ky_new_menu — A new menu was selected ky_f1 ky_f2 ky_f3 ky_f4 ky_f5"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["The menu data in the dictionary consists of a list of enumerated values that are displayed and selected from a pull-up menu on the teach pendant device. A maximum of 9 values should be used. Each value is a string of up to 12 characters. A sequence of consecutive dictionary elements, starting with element_no, define the values. Each value must be put in a separate element, and must not end with &new_line. The characters are assigned the numeric values 1..9 in sequence. The last dictionary element must be \"\"."],"env":"UIF"},"DISCTRL_SBMN":{"kind":"procedure","purpose":"Creates and controls cursor movement and selection in a sub-window menu","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the name of the dictionary that contains the menu data."},{"name":"element_no","dir":"in","type":"INTEGER","text":"element_no is the element number of the first menu item within the dictionary."},{"name":"def_item","dir":"in,out","type":"INTEGER","text":"def_item is the item that should be highlighted when the menu is entered. 1 specifies the first item. On return, def_item is the item that was currently highlighted when the termination character was pressed."},{"name":"term_char","dir":"out","type":"INTEGER","text":"term_char receives a code indicating the character that terminated the menu. The codes for key terminating conditions are defined in the include file FROM:KLEVKEYS.KL. Keys normally returned are pre-defined constants as follows: ky_enter — A menu item was selected ky_prev — A menu item was not selected ky_new_menu — A new menu was selected ky_f1 ky_f2 ky_f3 ky_f4 ky_f5"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["The menu data in the dictionary consists of a list of enumerated values that are displayed and selected from the 'subm' subwindow on the Teach Pendant device. There can be up to 5 subwindow pages, for a maximum of 35 values. Each value is a string of up to 16 characters. If 4 or less enumerated values are used, then each string can be up to 40 characters. A sequence of consecutive dictionary elements, starting with element_no, define the values. Each value must be put in a separate element, and must not end with &new_line. The characters are assigned the numeric values 1..35 in sequence. The last dictionary element must be \"\"."],"env":"UIF"},"DISCTRL_TBL":{"kind":"procedure","purpose":"Displays and controls a table on the teach pendant","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name is the four-character name of the dictionary containing the table header."},{"name":"ele_number","dir":"in","type":"INTEGER","text":"ele_number is the element number of the table header."},{"name":"num_rows","dir":"in","type":"INTEGER","text":"num_rows is the number of rows in the table."},{"name":"num_columns","dir":"in","type":"INTEGER","text":"num_columns is the number of columns in the table."},{"name":"col_data","dir":"in","type":"ARRAY OF COL_DESC_T","text":"col_data is an array of column descriptor structures, one for each column in the table. For a complete description, refer to the INIT_TBL Built-In routine."},{"name":"inact_array","dir":"in","type":"ARRAY OF BOOLEAN","text":"inact_array is an array of booleans that corresponds to each column in the table. — You can set each boolean to TRUE which will make that column inactive. This means the you cannot move the cursor to this column. — The array size can be less than or greater than the number of items in the table. — If inact_array is not used, then an array size of 1 can be used, and the array does not need to be initialized."},{"name":"change_array","dir":"out","type":"ARRAY OF BOOLEAN","text":"change_array is a two dimensional array of BOOLEANs that corresponds to formatted data items in the table. — If the corresponding value is set, then the boolean will be set to TRUE, otherwise it is set to FALSE. You do not need to initialize the array. — The array size can be less than or greater than the number of data items in the table. — If change_array is not used, then an array size of 1 can be used."},{"name":"def_item","dir":"in,out","type":"INTEGER","text":"def_item is the row containing the item you want to be highlighted when the table is entered. On return, def_item is the row containing the item that was currently highlighted when the termination character was pressed."},{"name":"term_char","dir":"out","type":"INTEGER","text":"term_char receives a code indicating the character or other condition that terminated the table. The codes for key terminating conditions are defined in the include file FROM:KLEVKEYS.KL. Keys normally returned are pre-defined constants as follows: ky_undef — No termination character was pressed ky_select — A selectable item as selected ky_new_menu — A new menu was selected ky_f1 — Function key 1 was selected ky_f2 — Function key 2 was selected ky_f3 — Function key 3 was selected ky_f4 — Function key 4 was selected ky_f5 — Function key 5 was selected ky_f6 — Function key 6 was selected ky_f7 — Function key 7 was selected ky_f8 — Function key 8 was selected ky_f9 — Function key 9 was selected ky_f10 — Function key 10 was selected"},{"name":"term_mask","dir":"in","type":"INTEGER","text":"term_mask is a bit-wise mask indicating conditions that will terminate the request. This should be an OR of the constants defined in the include file FROM:KLEVKMSK.KL. kc_display — Displayable keys kc_func_key — Function keys kc_keypad — Key-pad and Edit keys kc_enter_key — Enter and Return keys kc_delete — Delete and Backspace keys kc_lr_arw — Left and Right Arrow keys kc_ud_arw — Up and Down Arrow keys kc_other — Other keys (such as Prev)"},{"name":"value_array","dir":"in","type":"ARRAY OF STRING","text":"value_array is an array of variable names that corresponds to each column of data item in the table. Each variable name can be specified as '[prog_name]var_name'. — [prog_name] specifies the name of the program that contains the specified variable. If [prog_name] is not specified, then the current program being executed is used. — var_name must refer to a static, global program variable. — var_name can contain node numbers, field names, and/or subscripts."},{"name":"attach_wind","dir":"in","type":"BOOLEAN","text":"attach_wind should be set to 1 if the table manager window needs to be attached to the display device. If it is already attached, this parameter can be set to 0."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["DISCTRL_TBL is similar to the INIT_TBL and ACT_TBL Built-In routines and should be used if no special processing needs to be done with each keystroke."],"env":"UIF"},"DISMOUNT_DEV":{"kind":"procedure","purpose":"Dismounts the specified device.","params":[{"name":"device","dir":"in","type":"STRING","text":"device specifies the device to be dismounted."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"FDEV","seeAlso":["FORMAT_DEV"]},"DOSFILE_INF":{"kind":"procedure","purpose":"Returns information for a device as a string in the value parameter.","params":[{"name":"device","dir":"in","type":"STRING","text":"device can be UD1:"},{"name":"item","dir":"in","type":"INTEGER","text":"item is the constant of the data to be returned: — DF_MANUFNAME (Manufacture's name) — DF_PRODNAME (Product name) — DF_SERIALNO (Serial number) — DF_PRODID (Product ID number as assigned by USB authority) — DF_VENDID (Vendor ID number as assigned by USB authority)"},{"name":"value_str","dir":"out","type":"STRING","text":"value_str is the string where the data is returned."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of an attempted operation. If not equal to 0, then an error occurred."}],"notes":["DOSFILE_INF is only available on R-30iB Controller"],"env":"PBCORE"},"ERR_DATA":{"kind":"procedure","purpose":"Reads the requested error from the error history and returns the error","params":[{"name":"seq_num","dir":"in,out","type":"INTEGER","text":"seq_num is the sequence number of the previous error requested. seq_num should be set to 0 if the oldest error in the history is desired. seq_num should be set to MAXINT if the most recent error is desired. seq_num is set to the sequence number of the error that is returned. — If the initial value of seq_num is greater than the sequence number of the newest error in the log, seq_num is returned as zero and no other data is returned. — If the initial value of seq_num is less than the sequence number of the oldest error in the log, the oldest error is returned."},{"name":"error_code","dir":"out","type":"INTEGER","text":"error_code returns the error code and error_string returns the error message. error_string must be at least 40 characters long or the program will abort with an error. error_code and cause_code are in the following format: ffccc (decimal) where ff represents the facility code of the error. ccc represents the error code within the specified facility."},{"name":"error_string","dir":"out","type":"STRING","text":"error_code returns the error code and error_string returns the error message. error_string must be at least 40 characters long or the program will abort with an error. error_code and cause_code are in the following format: ffccc (decimal) where ff represents the facility code of the error. ccc represents the error code within the specified facility."},{"name":"cause_code","dir":"out","type":"INTEGER","text":"cause_code returns the reason code if it exists and cause_string returns the message. cause_string must be at least 40 characters long or the program will abort with an error."},{"name":"cause_string","dir":"out","type":"STRING","text":"cause_code returns the reason code if it exists and cause_string returns the message. cause_string must be at least 40 characters long or the program will abort with an error."},{"name":"time_int","dir":"out","type":"INTEGER","text":"time_int returns the time that error_code was posted. The time is in encoded format, and CNV_TIME_STR Built-In should be used to get the date-and-time string."},{"name":"severity","dir":"out","type":"INTEGER","text":"severity returns one of the following error_codes: 0:WARNING1:PAUSE2:ABORT"},{"name":"prog_nam","dir":"out","type":"STRING","text":"If the error occurs in the execution of a program, prog_nam specifies the name of the program in which the error occurred."}],"notes":["If the error is posted by POST_ERR, or if the error is not associated with a particular program (e.g., E-STOP), prog_nam is returned as ` \"\" '.","Calling ERR_DATA immediately after POST_ERR may not return the error just posted since POST_ERR returns before the error is actually in the error log."],"env":"ERRS","seeAlso":["POST_ERR"]},"EXP":{"kind":"function","purpose":"Returns a REAL value equal to e (approximately 2.71828) raised to the power specified by a REAL argument","returns":"REAL","params":[{"name":"x","dir":"in","type":"REAL","text":"x must be less than 80. Otherwise, the program will be paused with an error."}],"notes":["EXP returns e (base of the natural logarithm) raised to the power x."],"env":"SYSTEM"},"FILE_LIST":{"kind":"procedure","purpose":"Generates a list of files with the specified name and type on the specified device.","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the device, name, and type of the list of files to be found. file_spec can be specified using the wildcard (*) character."},{"name":"n_skip","dir":"in","type":"INTEGER","text":"n_skip is used when more files exist than the declared length of ary_nam. Set n_skip to 0 the first time you use FILE_LIST. If ary_nam is completely filled with variable names, copy the array to another ARRAY of STRINGs and execute the FILE_LIST again with n_skip equal to n_files. The second call to FILE_LIST will skip the files found in the first pass and only locate the remaining files."},{"name":"format","dir":"in","type":"INTEGER","text":"format specifies the format of the file name and file type. The following values are valid for format: 1 file_name only, no blanks 2 file_type only, no blanks3 file_name.file_type, no blanks4 filename.ext size date time The total length is 40 characters. — The file_name starts with character 1. — The file_type (extension) starts with character 10. — The size starts with character 21. — The date starts with character 26. — The time starts with character 36. Date and time are only returned if the device supports time stamping; otherwise just the filename.ext size is stored."},{"name":"ary_nam","dir":"out","type":"ARRAY OF STRING","text":"ary_nam is an ARRAY of STRINGs to store the file names. If the string length of ary_nam is not large enough to store the formatted information, an error will be returned."},{"name":"n_files","dir":"out","type":"INTEGER","text":"n_files is the number of files stored in ary_name."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"BYNAM","seeAlso":["PROG_LIST"]},"FORCE_LINK":{"kind":"procedure","purpose":"Forces the display of custom web pages or generic links.","params":[{"name":"pane_id","dir":"in","type":"INTEGER","text":"pane_id specifies the pane and should be one of the following predefined constants: tp_panel for primary iPendant pane tp2_panel for dual iPendant pane tp3_panel for third iPendant pane 4-9 are reserved for panes during remote connections"},{"name":"url","dir":"in","type":"STRING","text":"url is an acronym for Uniform Resource Location and is an address to a resource on the Internet or a custom web page on the controller. It can be any valid URL location. Linking URLs are also provided to force configuration and other special uses."}],"env":"PBCORE"},"FORCE_SPMENU":{"kind":"procedure","purpose":"Forces the display of the specified menu","params":[{"name":"device_code","dir":"in","type":"INTEGER","text":"device_code specifies the device and should be one of the following predefined constants: tp_panel Teach pendant device crt_panel CRT device"},{"name":"spmenu_id","dir":"in","type":"INTEGER","text":"spmenu_id and screen_no specify the menu to force. The predefined constants beginning with SPI_ define the spmenu_id and the predefined constants beginning with SCR_ define the screen_no. If no SCR_ is listed, use 1. SPI_TPHINTS — UTILITIES Hints SPI_TPPRGADJ — UTILITIES Prog Adjust SPI_TPMIRROR — UTILITIES Mirror Image SPI_TPSHIFT — UTILITIES Program Shift SPI_TPTSTRUN — TEST CYCLE SPI_TPMANUAL, SCR_MACMAN — MANUAL Macros SPI_TPOTREL — MANUAL OT Release SPI_TPALARM, SCR_ALM_ALL — ALARM Alarm Log SPI_TPALARM, SCR_ALM_MOT — ALARM Motion Log SPI_TPALARM, SCR_ALM_SYS — ALARM System Log SPI_TPALARM, SCR_ALM_APPL — ALARM Appl Log SPI_TPDIGIO — I/O Digital SPI_TPANAIO — I/O Analog SPI_TPGRPIO — I/O Group SPI_TPROBIO — I/O Robot SPI_TPUOPIO — I/O UOP SPI_TPSOPIO — I/O SOP SPI_TPPLCIO — I/O PLC SPI_TPSETGEN — SETUP General SPI_TPFRAM — SETUP Frames SPI_TPPORT — SETUP Port Init SPI_TPMMACRO, SCR_MACSETUP — SETUP Macro SPI_TPREFPOS — SETUP Ref Position SPI_TPPWORD — SETUP Passwords SPI_TPHCCOMM — SETUP Host Comm SPI_TPSYRSR — SETUP RSR/PNS SPI_TPFILS — FILE SPI_TPSTATUS, SCR_AXIS — STATUS Axis SPI_TPMEMORY — STATUS Memory SPI_TPVERSN — STATUS Version ID SPI_TPPRGSTS — STATUS Program SPI_TPSFTY — STATUS Safety Signals SPI_TPUSER — USER SPI_TPSELECT — SELECT SPI_TPTCH — EDIT SPI_TPREGIS, SCR_NUMREG — DATA Registers SPI_SFMPREG, SCR_POSREG — DATA Position Reg SPI_TPSYSV, SCR_NUMVAR — DATA KAREL Vars SPI_TPSYSV, SCR_POSVAR — DATA KAREL Posns SPI_TPPOSN — POSITION SPI_TPSYSV, SCR_CLOCK — SYSTEM Clock SPI_TPSYSV, SCR_SYSVAR — SYSTEM Variables SPI_TPMASCAL — SYSTEM Master/Cal SPI_TPBRKCTR — SYSTEM Brake Cntrl SPI_TPAXLM — SYSTEM Axis Limits SPI_CRTKCL, SCR_KCL — KCL> (crt_panel only) SPI_CRTKCL, SCR_CRT — KAREL EDITOR (crt_panel only) SPI_TPUSER2 — Menu for form/table managers"},{"name":"screen_no","dir":"in","type":"INTEGER","text":"spmenu_id and screen_no specify the menu to force. The predefined constants beginning with SPI_ define the spmenu_id and the predefined constants beginning with SCR_ define the screen_no. If no SCR_ is listed, use 1. SPI_TPHINTS — UTILITIES Hints SPI_TPPRGADJ — UTILITIES Prog Adjust SPI_TPMIRROR — UTILITIES Mirror Image SPI_TPSHIFT — UTILITIES Program Shift SPI_TPTSTRUN — TEST CYCLE SPI_TPMANUAL, SCR_MACMAN — MANUAL Macros SPI_TPOTREL — MANUAL OT Release SPI_TPALARM, SCR_ALM_ALL — ALARM Alarm Log SPI_TPALARM, SCR_ALM_MOT — ALARM Motion Log SPI_TPALARM, SCR_ALM_SYS — ALARM System Log SPI_TPALARM, SCR_ALM_APPL — ALARM Appl Log SPI_TPDIGIO — I/O Digital SPI_TPANAIO — I/O Analog SPI_TPGRPIO — I/O Group SPI_TPROBIO — I/O Robot SPI_TPUOPIO — I/O UOP SPI_TPSOPIO — I/O SOP SPI_TPPLCIO — I/O PLC SPI_TPSETGEN — SETUP General SPI_TPFRAM — SETUP Frames SPI_TPPORT — SETUP Port Init SPI_TPMMACRO, SCR_MACSETUP — SETUP Macro SPI_TPREFPOS — SETUP Ref Position SPI_TPPWORD — SETUP Passwords SPI_TPHCCOMM — SETUP Host Comm SPI_TPSYRSR — SETUP RSR/PNS SPI_TPFILS — FILE SPI_TPSTATUS, SCR_AXIS — STATUS Axis SPI_TPMEMORY — STATUS Memory SPI_TPVERSN — STATUS Version ID SPI_TPPRGSTS — STATUS Program SPI_TPSFTY — STATUS Safety Signals SPI_TPUSER — USER SPI_TPSELECT — SELECT SPI_TPTCH — EDIT SPI_TPREGIS, SCR_NUMREG — DATA Registers SPI_SFMPREG, SCR_POSREG — DATA Position Reg SPI_TPSYSV, SCR_NUMVAR — DATA KAREL Vars SPI_TPSYSV, SCR_POSVAR — DATA KAREL Posns SPI_TPPOSN — POSITION SPI_TPSYSV, SCR_CLOCK — SYSTEM Clock SPI_TPSYSV, SCR_SYSVAR — SYSTEM Variables SPI_TPMASCAL — SYSTEM Master/Cal SPI_TPBRKCTR — SYSTEM Brake Cntrl SPI_TPAXLM — SYSTEM Axis Limits SPI_CRTKCL, SCR_KCL — KCL> (crt_panel only) SPI_CRTKCL, SCR_CRT — KAREL EDITOR (crt_panel only) SPI_TPUSER2 — Menu for form/table managers"}],"env":"PBCORE","seeAlso":["ACT_SCREEN"]},"FORMAT_DEV":{"kind":"procedure","purpose":"Deletes any existing information and records a directory and other internal information on the specified device.","params":[{"name":"device","dir":"in","type":"STRING","text":"device specifies the device to initialize."},{"name":"volume_name","dir":"in","type":"STRING","text":"volume_name acts as a label for a particular unit of storage media. volume_name can be a maximum of 11 characters and will be truncated to 11 characters if more are specified."},{"name":"nowait_sw","dir":"in","type":"BOOLEAN","text":"If nowait_sw is TRUE, execution of the program continues while the command is executing. If it is FALSE, the program stops, including condition handlers, until the operation is complete. If you have time critical condition handlers in the program, put them in another program that executes as a separate task. Note nowait_sw is not available in this release and should be set to FALSE."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"FDEV","seeAlso":["DISMOUNT_DEV"]},"FRAME":{"kind":"function","purpose":"Returns a frame with a POSITION data type representing the transformation to the coordinate frame specified by three (or four) POSITION arguments.","returns":"Position","params":[{"name":"pos1","dir":"in","type":"POSITION","text":"pos1 and pos2 arguments must be at least 10 millimeters apart and pos3 must be at least 10 millimeters away from the line connecting pos1 and pos2. If either condition is not met, the program is paused with an error. Figure A–2. FRAME Built-In Function"},{"name":"pos2","dir":"in","type":"POSITION","text":"pos1 and pos2 arguments must be at least 10 millimeters apart and pos3 must be at least 10 millimeters away from the line connecting pos1 and pos2. If either condition is not met, the program is paused with an error. Figure A–2. FRAME Built-In Function"},{"name":"pos3","dir":"in","type":"POSITION","text":"pos1 and pos2 arguments must be at least 10 millimeters apart and pos3 must be at least 10 millimeters away from the line connecting pos1 and pos2. If either condition is not met, the program is paused with an error. Figure A–2. FRAME Built-In Function"},{"name":"pos4","dir":"in","type":"POSITION","text":"The returned value is computed as follows: — pos1 is assumed to be the origin unless a pos4 argument is supplied. See Figure A–2. — If pos4 is supplied, the origin is shifted to pos4, and the new coordinate frame retains the same orientation in space as the first coordinate frame. See Figure A–2. — The x-axis is parallel to a line from pos1 to pos2. — The xy-plane is defined to be that plane containing pos1, pos2, and pos3, with pos3 in the positive half of the plane. — The y-axis is perpendicular to the x-axis and in the xy-plane. — The z-axis is through pos1 and perpendicular to the xy-plane. The positive direction is determined by the right hand rule. — The configuration of the result is set to that of pos1, or pos4 if it is supplied.","optional":true}],"env":"SYSTEM"},"GET_ATTR_PRG":{"kind":"procedure","purpose":"Gets attribute data from the specified teach pendant or KAREL program","params":[{"name":"program_name","dir":"in","type":"STRING","text":"program_name specifies the program from which to get attribute."},{"name":"attr_number","dir":"in","type":"INTEGER","text":"attr_number is the attribute whose value is to be returned. The following attributes are valid: AT_PROG_TYPE: Program type AT_PROG_NAME: Program name (String[12]) AT_OWNER: Owner (String[8]) AT_COMMENT: Comment (String[16]) AT_PROG_SIZE: Size of program AT_ALLC_SIZE: Size of allocated memory AT_NUM_LINE: Number of lines AT_CRE_TIME: Created (loaded) time AT_MDFY_TIME: Modified time AT_SRC_NAME: Source file (or original file) name (String[128]) AT_SRC_VRSN: Source file versionA AT_DEF_GROUP: Default motion group mask (for task attribute). AT_PROTECT: Protection code; 1:Protection OFF; 2:Protection ON AT_STORAGE: Storage type; TPSTOR_CMOS; TPSTOR_SHADOW; TPSTOR_FILE; TPSTOR_SHOD AT_STK_SIZE: Stack size (for task attribute) AT_TASK_PRI: Task priority (for task attribute) AT_DURATION: Time slice duration (for task attribute) AT_BUSY_OFF: Busy lamp off (for task attribute) AT_IGNR_ABRT: Ignore abort request (for task attribute) AT_IGNR_PAUS: Ignore pause request (for task attribute) AT_CONTROL: Control code (for task attribute)"},{"name":"int_value","dir":"out","type":"INTEGER","text":"If the attribute data is a number, it is returned in int_value and string_value is not modified."},{"name":"string_value","dir":"out","type":"STRING","text":"If the attribute data is a number, it is returned in int_value and string_value is not modified."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If it is not equal to 0, then an error has occurred. Some of the errors which could occur are: 7073 The program specified in program_name does not exist 17027 string_value is not large enough to contain the attribute string. The value has been truncated to fit. 17033 attr_number has an illegal value"}],"notes":["The program type returned for AT_PROG_TYPE will be one of the following constants: PT_KRLPRG: Karel program PT_MNE_UNDEF: Teach pendant program of undefined sub type PT_MNE_JOB: Teach pendant job PT_MNE_PROC: Teach pendant process PT_MNE_MACRO: Teach pendant macro","If the attribute data is a string, it is returned in string_value and int_value is not modified."],"env":"PBCORE","seeAlso":["SET_TSK_ATTR"]},"GET_FILE_POS":{"kind":"function","purpose":"Returns the current file position (where the next READ or WRITE operation will take place) in the specified file","returns":"INTEGER","params":[{"name":"file_id","dir":"in","type":"FILE","text":"The file associated with file_id must be open. Otherwise, the program is aborted with an error."}],"notes":["GET_FILE_POS returns the number of bytes before the next byte to be read or written in the file.","Line terminators are counted in the value returned.","If the file associated with file_id is open for read-only, it cannot be on the FROM or RAM disks as a compressed file. Warning GET_FILE_POS is only supported for files opened on the RAM Disk device. Do not use GET_FILE_POS on another device; otherwise, you could injure personnel and damage equipment."],"env":"FLBT"},"GET_JPOS_REG":{"kind":"function","purpose":"Gets a JOINTPOS value from the specified register","returns":"REGOPE","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the position register to get."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed.","optional":true}],"notes":["If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller.","GET_JPOS_REG returns the position in JOINTPOS format. Use POS_REG_TYPE to determine the position representation."],"env":"REGOPE","seeAlso":["SET_POS_REG"]},"GET_JPOS_TPE":{"kind":"function","purpose":"Gets a JOINTPOS value from the specified position in the specified teach pendant program","returns":"JOINTPOS","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the teach pendant program. A program must be opened before calling this built-in."},{"name":"position_no","dir":"in","type":"INTEGER","text":"position_no specifies the position in the program to get."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed.","optional":true}],"notes":["If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller.","No conversion is done for the position representation. The position data must be in JOINTPOS format. If the stored position is not in JOINTPOS, an error status is returned. Use GET_POS_TYP to get the position representation.","If the specified position in the program is uninitialized, the returned JOINTPOS value is uninitialized and the status is set to 17038, \"Uninitialized TPE position\"."],"env":"PBCORE","seeAlso":["SET_POS_TPE"]},"GET_PORT_ASG":{"kind":"procedure","purpose":"Allows a KAREL program to determine the physical port(s) to which a specified logical port is assigned.","params":[{"name":"log_port_type","dir":"in","type":"INTEGER","text":"log_port_type specifies the code for the type of port whose assignment is being accessed. Codes are defined in FR:KLIOTYPS.KL."},{"name":"log_port_no","dir":"in","type":"INTEGER","text":"log_port_no specifies the number of the port whose assignment is being accessed."},{"name":"rack_no","dir":"out","type":"INTEGER","text":"rack_no is returned with the rack containing the port module. For process I/O boards, memory-image, and dummy ports, this is zero; for Allen-Bradley ports, this is 16."},{"name":"slot_no","dir":"out","type":"INTEGER","text":""},{"name":"phy_port_type","dir":"out","type":"INTEGER","text":"phy_port_type is returned with the type of port assigned to. Often this will be the same as log_port_type. Exceptions are if log_port_type is a group type (io_gpin or io_gpout) or a port is assigned to memory-image or dummy ports."},{"name":"phy_port_no","dir":"out","type":"INTEGER","text":"phy_port_no is returned with the number of the port assigned to. If log_port_type is a group, this is the port number for the least-significant bit of the group."},{"name":"n_ports","dir":"out","type":"INTEGER","text":"n_ports is returned with the number of physical ports assigned to the logical port. This will be 1 in all cases except when log_port_type is a group type. In this case, n_ports indicates the number of bits in the group."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid and the specified port is assigned. Otherwise, it is returned with an error code."}],"env":"IOSETUP"},"GET_PORT_ATR":{"kind":"function","purpose":"Gets an attribute from the specified port","returns":"INTEGER","params":[{"name":"port_id","dir":"in","type":"INTEGER","text":"port_id specifies which port is to be queried. Use one of the following predefined constants: port_1 port_2 port_3 port_4 port_5"},{"name":"atr_type","dir":"in","type":"INTEGER","text":"atr_type specifies the attribute whose current setting is to be returned. Use one of the following predefined constants: atr_readahd:Read ahead buffer atr_baud:Baud rate atr_parity:Parity atr_sbits:Stop bit atr_dbits:Data length atr_xonoff:Xon/Xoff atr_eol:End of line atr_modem:Modem line"},{"name":"atr_value","dir":"out","type":"INTEGER","text":"atr_value receives the current value for the specified attribute."}],"notes":["GET_PORT_ATR returns the status of this action to the port."],"env":"FLBT","seeAlso":["SET_PORT_ATR"]},"GET_PORT_CMT":{"kind":"procedure","purpose":"Allows a KAREL program to determine the comment that is set for a specified logical port","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port whose comment is being returned. Codes are defined in FR:KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number whose comment is being set."},{"name":"comment_str","dir":"out","type":"STRING","text":"comment_str is returned with the comment for the specified port. This should be declared as a STRING with a length of at least 16 characters."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid and the comment is returned for the specified port."}],"env":"IOSETUP","seeAlso":["SET_PORT_MOD"]},"GET_PORT_MOD":{"kind":"procedure","purpose":"Allows a KAREL program to determine what special port modes are set for a specified logical port","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port whose mode is being returned. Codes are defined in FR:KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number whose mode is being set."},{"name":"mode_mask","dir":"out","type":"INTEGER","text":"mode_mask is returned with a mask specifying which modes are turned on. The following modes are defined: 1:reverse mode Sense of the port is reversed; if the port is set to TRUE, the physical output is set to FALSE. If the port is set to FALSE, the physical output is set to TRUE. If a physical input is TRUE, when the port is read, FALSE is returned. If a physical input is FALSE, when the port is read, TRUE is returned. 2:complementary mode The logical port is assigned to two physical ports whose values are complementary. In this case, port_no must be an odd number. If port n is set to TRUE, then port n is set to TRUE and port n + 1 is set to FALSE. If port n is set to FALSE, then port n is set to FALSE and port n + 1 is set to TRUE. This is effective only for output ports."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid and the specified mode is returned for the specified port."}],"env":"IOSETUP"},"GET_PORT_SIM":{"kind":"procedure","purpose":"Gets port simulation status","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port to get. Codes are defined in FRS:KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the number of the port whose simulation status is being returned."},{"name":"simulated","dir":"out","type":"INTEGER","text":"simulated returns TRUE if the port is being simulated, FALSE otherwise."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the port is valid."}],"env":"IOSETUP","seeAlso":["SET_PORT_MOD"]},"GET_PORT_VAL":{"kind":"procedure","purpose":"Allows a KAREL program to determine the current value of a specified logical port","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port whose comment is being returned. Codes are defined in FR:KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number whose comment is being set."},{"name":"value","dir":"out","type":"STRING","text":"value is returned with the current value (status) of the specified port. For BOOLEAN port types, (i.e. DIN), this will be 0 = OFF, or 1 = ON."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid and the comment is returned for the specified port."}],"env":"IOSETUP","seeAlso":["SET_PORT_MOD"]},"GET_POS_FRM":{"kind":"procedure","purpose":"Gets the uframe number and utool number of the specified position in the specified teach pendant program.","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. A program must be opened before calling this built-in."},{"name":"position_no","dir":"in","type":"INTEGER","text":"position_no specifies the position in the teach pendant program."},{"name":"gnum","dir":"in","type":"INTEGER","text":"gnum specifies the group number of position."},{"name":"ufram_no","dir":"out","type":"INTEGER","text":"ufram_no is returned with the frame number of position_no."},{"name":"utool_no","dir":"out","type":"INTEGER","text":"utool_no is returned with the tool number of position_no."},{"name":"status","dir":"out","type":"INTEGER","text":"status indicates the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If the specified position, position_no, is uninitialized, the status is set to 17038, \"Uninitialized TPE position.\""],"env":"PBCORE"},"GET_POS_REG":{"kind":"function","purpose":"Gets an XYZWPR value from the specified register","returns":"XYZWPREXT","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the position register to get."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed.","optional":true}],"notes":["If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller.","GET_POS_REG returns the position in XYZWPREXT format. Use POS_REG_TYPE to determine the position representation."],"env":"REGOPE","seeAlso":["GET_REG"]},"GET_POS_TPE":{"kind":"function","purpose":"Gets an XYZWPREXT value from the specified position in the specified teach pendant program","returns":"XYZWPREXT","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. A program must be opened before calling this built-in."},{"name":"position_no","dir":"in","type":"INTEGER","text":"position_no specifies the position in the program to get."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed.","optional":true}],"notes":["No conversion is done for the position representation. The positional data must be in XYZWPR or XYZWPREXT, otherwise, an error status is returned. Use GET_POS_TYP to get the position representation.","If the specified position in the program is uninitialized, the returned XYZWPR value is uninitialized and status is set to 17038, \"Uninitialized TPE Position.\"","If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"PBCORE","seeAlso":["GET_POS_TYP"]},"GET_POS_TYP":{"kind":"procedure","purpose":"Gets the position representation of the specified position in the specified teach pendant program","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. A program must be opened before calling this built-in."},{"name":"position_no","dir":"in","type":"INTEGER","text":"position_no specifies the position in the program."},{"name":"group_no","dir":"in","type":"INTEGER","text":"group_no specifies the group number."},{"name":"posn_typ","dir":"out","type":"INTEGER","text":"Position type is returned by posn_typ. posn_typ is defined as follows:2:XYZWPR6:XYZWPREXT9:JOINTPOS"},{"name":"num_axs","dir":"out","type":"INTEGER","text":"If it is in joint position, the number of the axis in the representation is returned by num_axs."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."}],"notes":["If the specified position in the program is uninitialized, then a status is set to 17038, \"Unintialized TPE Position.\""],"env":"PBCORE"},"GET_PREG_CMT":{"kind":"procedure","purpose":"To retrieve the comment information of a KAREL position register based on a given register number.","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"Register_no specifies which position register to retrieve the comments from. The comment of the given position register is returned in the comment_string."},{"name":"comment_string","dir":"out","type":"STRING","text":"Register_no specifies which position register to retrieve the comments from. The comment of the given position register is returned in the comment_string."},{"name":"status","dir":"out","type":"INTEGER","text":""}],"env":"REGOPE"},"GET_QUEUE":{"kind":"procedure","purpose":"Retrieves the specified oldest entry from a queue","params":[{"name":"queue_t","dir":"in,out","type":"QUEUE_TYPE","text":"queue_t specifies the queue variable for the queue from which the value is to be obtained."},{"name":"queue_data","dir":"in,out","type":"ARRAY OF INTEGER","text":"queue_data specifies the array variable with the queue data."},{"name":"value","dir":"out","type":"INTEGER","text":"value is returned with the oldest entry obtained from the queue."},{"name":"sequence_no","dir":"out","type":"INTEGER","text":"sequence_no is returned with the sequence number of the returned entry."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with the zero if an entry is successfully obtained from the queue. Otherwise, a value of 61002, ``Queue is empty,'' is returned."}],"env":"PBQMGR","seeAlso":["MODIFY_QUEUE"]},"GET_REG":{"kind":"procedure","purpose":"Gets an INTEGER or REAL value from the specified register","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the register to get."},{"name":"real_flag","dir":"out","type":"BOOLEAN","text":"real_flag is set to TRUE and real_value to the register content if the specified register has a real value. Otherwise, real_flag is set to FALSE and int_value is set to the contents of the register."},{"name":"int_value","dir":"out","type":"INTEGER","text":"real_flag is set to TRUE and real_value to the register content if the specified register has a real value. Otherwise, real_flag is set to FALSE and int_value is set to the contents of the register."},{"name":"real_value","dir":"out","type":"REAL","text":"real_flag is set to TRUE and real_value to the register content if the specified register has a real value. Otherwise, real_flag is set to FALSE and int_value is set to the contents of the register."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"REGOPE"},"GET_REG_CMT":{"kind":"procedure","purpose":"To retrieve the comment information of a KAREL register based on a given register number.","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"Register_no specifies which register to retrieve the comments from. The comment of the given register is returned in comment_string."},{"name":"comment_string","dir":"out","type":"STRING","text":"Register_no specifies which register to retrieve the comments from. The comment of the given register is returned in comment_string."},{"name":"status","dir":"out","type":"INTEGER","text":""}],"env":"REGOPE"},"GET_SREG_CMT":{"kind":"procedure","purpose":"Gets the comment from the specified string register.","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the string register to get."},{"name":"comment","dir":"out","type":"STRING[254]","text":"comment contains the comment of the specified string register."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"REGOPE","seeAlso":["SET_SREG_CMT"]},"GET_STR_REG":{"kind":"procedure","purpose":"Gets the value from the specified string register.","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the string register to get."},{"name":"value","dir":"out","type":"STRING[254]","text":"value contains the value of the specified string register."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"REGOPE","seeAlso":["SET_SREG_CMT"]},"GET_TIME":{"kind":"procedure","purpose":"Retrieves the current time (in integer representation) from within the KAREL system","params":[{"name":"i","dir":"out","type":"INTEGER","text":"i holds the INTEGER representation of the current time stored in the KAREL system. This value is represented in 32-bit INTEGER format as follows: INTEGER Representation of Current Time 31–25 24–21 20–16 year month day 15–11 10–5 4–0 hour minute second"}],"notes":["The contents of the individual fields are as follows: — DATE: Bits 31-25 — Year since 1980 Bits 24-21 — Month (1-12) Bits 20-16 — Day of the month — TIME: Bits 15-11 — Number of hours (0-23) Bits 10-5 — Number of minutes (0-59) Bits 4-0 — Number of 2-second increments (0-29)","INTEGER values can be compared to determine if one time is more recent than another.","Use the CNV_TIME_STR built-in procedure to convert the INTEGER into the ``DD-MMM-YYY HH:MM:SS'' STRING format."],"env":"TIM","seeAlso":["CNV_TIME_STR"]},"GET_TPE_CMT":{"kind":"procedure","purpose":"This built-in provides the ability for a KAREL program to read the comment associated with a specified position in a teach pendant program.","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the open_id returned from a previous call to OPEN_TPE."},{"name":"pos_no","dir":"in","type":"INTEGER","text":"pos_no specifies the number of the position in the TPP program to get a comment from."},{"name":"comment","dir":"out","type":"STRING","text":"comment is associated with specified positions and is returned with a zero length string if the position has no comment. If the string variable is too short for the comment, an error is returned and the string is not changed."},{"name":"status","dir":"out","type":"INTEGER","text":"status indicates zero if the operation was successful, otherwise an error code will be displayed."}],"env":"TPE","seeAlso":["OPEN_TPE FOR MORE"]},"GET_TPE_PRM":{"kind":"procedure","purpose":"Gets the values of the parameters when parameters are passed in a TPE CALL or MACRO instruction.","params":[{"name":"param_no","dir":"in","type":"INTEGER","text":"param_no indicates the number of the parameter. There can be at most ten parameters."},{"name":"data_type","dir":"out","type":"INTEGER","text":"data_type indicates the data type for the parameter, as follows: — 1: INTEGER — 2: REAL — 3: STRING"},{"name":"int_value","dir":"out","type":"INTEGER","text":"int_value is the value of the parameter if the data_type is INTEGER."},{"name":"real_value","dir":"out","type":"REAL","text":"real_value is the value of the parameter if the data_type is REAL."},{"name":"str_value","dir":"out","type":"STRING","text":"str_value is the value of the parameter if the data_type is STRING."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."}],"notes":["If the parameter designated by param_no does not exist, a status of 17042 is returned, which is the error message: \"ROUT-042 WARN TPE parameters do not exist.\" If this error is returned, confirm the param_no and the parameter in the CALL or MACRO command in the main TPE program."],"env":"PBCORE"},"GET_TSK_INFO":{"kind":"procedure","purpose":"Get the value of the specified task attribute","params":[{"name":"task_name","dir":"in,out","type":"STRING","text":"task_name is the name of the task of interest. task_name is used as input only if task_no is uninitialized or set to 0, otherwise, task_name is considered an output parameter."},{"name":"task_no","dir":"in,out","type":"INTEGER","text":"task_no is the task number of interest. If task_no is uninitialized or set to 0, it is returned as an output parameter."},{"name":"attribute","dir":"in","type":"INTEGER","text":"attribute is the task attribute whose value is to be returned. It will be returned in value_int unless otherwise specified. The following attributes are valid: TSK_HOLDCOND: Task hold conditions TSK_LINENUM: Current executing line number TSK_LOCKGRP: Locked group TSK_MCTL: Motion controlled groups TSK_NOABORT: Ignore abort request TSK_NOBUSY: Busy lamp off TSK_NOPAUSE: Ignore pause request TSK_NUMCLDS: Number of child tasks TSK_PARENT: Parent task number TSK_PAUSESFT: Pause on shift release TSK_PRIORITY: Task priority TSK_PROGNAME: Current program name returned in value_str TSK_PROGTYPE: Program type - refer to description below TSK_ROUTNAME: Current routine name returned in value_str TSK_STACK: Stack size TSK_STATUS: Task status — refer to description below TSK_STEP: Single step task TSK_TIMESLIC: Time slice duration in ms TSK_TPMOTION: TP motion enable TSK_TRACE: Trace enable TSK_TRACELEN: Length of trace array"},{"name":"value_int","dir":"out","type":"INTEGER","text":"attribute is the task attribute whose value is to be returned. It will be returned in value_int unless otherwise specified. The following attributes are valid: TSK_HOLDCOND: Task hold conditions TSK_LINENUM: Current executing line number TSK_LOCKGRP: Locked group TSK_MCTL: Motion controlled groups TSK_NOABORT: Ignore abort request TSK_NOBUSY: Busy lamp off TSK_NOPAUSE: Ignore pause request TSK_NUMCLDS: Number of child tasks TSK_PARENT: Parent task number TSK_PAUSESFT: Pause on shift release TSK_PRIORITY: Task priority TSK_PROGNAME: Current program name returned in value_str TSK_PROGTYPE: Program type - refer to description below TSK_ROUTNAME: Current routine name returned in value_str TSK_STACK: Stack size TSK_STATUS: Task status — refer to description below TSK_STEP: Single step task TSK_TIMESLIC: Time slice duration in ms TSK_TPMOTION: TP motion enable TSK_TRACE: Trace enable TSK_TRACELEN: Length of trace array"},{"name":"value_str","dir":"out","type":"STRING","text":"attribute is the task attribute whose value is to be returned. It will be returned in value_int unless otherwise specified. The following attributes are valid: TSK_HOLDCOND: Task hold conditions TSK_LINENUM: Current executing line number TSK_LOCKGRP: Locked group TSK_MCTL: Motion controlled groups TSK_NOABORT: Ignore abort request TSK_NOBUSY: Busy lamp off TSK_NOPAUSE: Ignore pause request TSK_NUMCLDS: Number of child tasks TSK_PARENT: Parent task number TSK_PAUSESFT: Pause on shift release TSK_PRIORITY: Task priority TSK_PROGNAME: Current program name returned in value_str TSK_PROGTYPE: Program type - refer to description below TSK_ROUTNAME: Current routine name returned in value_str TSK_STACK: Stack size TSK_STATUS: Task status — refer to description below TSK_STEP: Single step task TSK_TIMESLIC: Time slice duration in ms TSK_TPMOTION: TP motion enable TSK_TRACE: Trace enable TSK_TRACELEN: Length of trace array"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If it is not equal to 0, then an error occurred."}],"notes":["TSK_STATUS is the task status: The return values are: PG_RUNACCEPT: Run request has been accepted PG_ABORTING: Abort has been accepted PG_RUNNING: Task is running PG_PAUSED: Task is paused PG_ABORTED: Task is aborted","TSK_PROGTYPE is the program type. The return values are: PG_NOT_EXEC: Program has not been executed yet PG_MNEMONIC: Teach pendant program is or was executing PG_AR_KAREL: KAREL program is or was executing"],"env":"PBCORE"},"GET_USEC_SUB":{"kind":"procedure","purpose":"Returns an INTEGER value indicating the elapsed time in microseconds (1/1,000,000).","returns":"INTEGER","params":[{"name":"us2","dir":"in","type":"INTEGER","text":"us2 is the second time returned from GET_USEC_TIM."},{"name":"us1","dir":"in","type":"INTEGER","text":"us1 is the first time returned from GET_USEC_TIM."}],"notes":["The returned value is the INTEGER representation of the elapsed time us2 - us1 in microseconds.","This is intended to measure fast operations. The result will wrap after 2 minutes and will no longer be valid."],"env":"TIM"},"GET_USEC_TIM":{"kind":"function","purpose":"Returns an INTEGER value indicating the current time in microseconds (1/1,000,000) from within the KAREL system.","returns":"INTEGER","notes":["The returned value is the INTEGER representation of the current time in microseconds stored in the KAREL system.","This function is used with the GET_USEC_SUB built-in function to determine the elapsed time of an operation."],"env":"TIM"},"GET_VAR":{"kind":"procedure","purpose":"Allows a KAREL program to retrieve the value of a specified variable","params":[{"name":"entry","dir":"in,out","type":"INTEGER","text":"entry returns the entry number in the variable data table of var_name in the device directory where var_name is located. This variable should not be modified."},{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the program that contains the specified variable. If prog_name is blank, it will default to the current task name being executed. Set the prog_name to `*SYSTEM*' to get a system variable. prog_name can also access a system variable on a robot in a ring."},{"name":"var_name","dir":"in","type":"STRING","text":"var_name must refer to a static, program variable. var_name can contain node numbers, field names, and/or subscripts."},{"name":"value","dir":"out","type":"ANY","text":"value is the value of var_name."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If both var_name and value are ARRAYs, the number of elements copied will equal the size of the smaller of the two arrays.","If both var_name and value are STRINGs, the number of characters copied will equal the size of the smaller of the two strings.","If both var_name and value are STRUCTUREs of the same type, value will be an exact copy of var_name.","If the value of var_name is uninitialized, then value will be set to uninitialized and status will be set to 12311.","The designated names of all the robots can be found in the system variable $PH_MEMBERS[]. This also include information about the state of the robot. The ring index is the array index for this system variable. KAREL users can write general purpose programs by referring to the names and other information in this system variable rather than explicit names."],"env":"SYSTEM","seeAlso":["SET_VAR"]},"INDEX":{"kind":"function","purpose":"Returns the index for the first character of the first occurrence of a specified STRING argument in another specified STRING argument. If the argument is not found, a 0 value is returned.","returns":"INTEGER","params":[{"name":"main","dir":"in","type":"STRING","text":"The returned value is the index position in main corresponding to the first character of the first occurrence of find or 0 if find does not occur in main."},{"name":"find","dir":"in","type":"STRING","text":"The returned value is the index position in main corresponding to the first character of the first occurrence of find or 0 if find does not occur in main."}],"env":"SYSTEM"},"INIT_QUEUE":{"kind":"procedure","purpose":"Sets a queue variable entry to have no entries in the queue","params":[{"name":"queue_t","dir":"out","type":"QUEUE_TYPE","text":"queue_t is the queue to be initialized"}],"env":"PBQMGR","seeAlso":["MODIFY_QUEUE","QUEUE_TYPE"]},"INIT_TBL":{"kind":"procedure","purpose":"Initializes a table on the teach pendant","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name is the four-character name of the dictionary containing the table header."},{"name":"ele_number","dir":"in","type":"INTEGER","text":"ele_number is the element number of the table header."},{"name":"num_rows","dir":"in","type":"INTEGER","text":"num_rows is the number of rows in the table."},{"name":"num_columns","dir":"in","type":"INTEGER","text":"num_columns is the number of columns in the table."},{"name":"col_data","dir":"in","type":"ARRAY OF COL_DESC_T","text":"col_data is an array of column descriptor structures, one for each column in the table. It contains the following fields: — item_type: Data type of values in this column. The following data type constants are defined: TPX_INT_ITEM — Integer type TPX_REL_ITEM — Real type TPX_FKY_ITEM — Function key enumeration type TPX_SUB_ITEM — Subwindow enumeration type TPX_KST_ITEM — KAREL string type TPX_KSL_ITEM — KAREL string label type (can select, not edit) TPX_KBL_ITEM — KAREL boolean type TPX_BYT_ITEM — Byte type TPX_SHT_ITEM — Short type TPX_PBL_ITEM — Port boolean type TPX_PIN_ITEM — Port integer type — start_col: Starting character column (1..40) of the display field for this data column. — field_width: Width of the display field for this data column. — num_ele: Dictionary element used to display values for certain data types. The format of the dictionary elements for these data types are as follows: – TPX_FKY_ITEM: The enumerated values are placed on function key labels. There can be up to 2 pages of function key labels, for a maximum of 10 labels. Each label is a string of up to 8 characters. However, the last character of a label which is followed by another label should be left blank or the two labels will run together. – A single dictionary element defines all of the label values. Each value must be put on a separate line using &new_line. The values are assigned to the function keys F1..F5, F6..F10 and the numeric values 1..10 in sequence. Unlabeled function keys should be left blank. If there are any labels on the second function key page, F6..F10, the labels for keys 5 and 10 must have the character ``>'' in column 8. If there are no labels on keys F6..F10, lines do not have to be specified for any key label after the last non-blank label."},{"name":"inact_array","dir":"in","type":"ARRAY OF BOOLEAN","text":"inact_array is an array of booleans that corresponds to each column in the table. — You can set each boolean to TRUE which will make that column inactive. This means the you cannot move the cursor to this column. — The array size can be less than or greater than the number of items in the table. — If inact_array is not used, then an array size of 1 can be used, and the array does not need to be initialized."},{"name":"change_array","dir":"in","type":"ARRAY OF ARRAY OF BOOLEAN","text":"change_array is a two dimensional array of BOOLEANs that corresponds to formatted data items in the table. — If the corresponding value is set, then the boolean will be set to TRUE, otherwise it is set to FALSE. You do not need to initialize the array. — The array size can be less than or greater than the number of data items in the table. — If change_array is not used, then an array size of 1 can be used."},{"name":"value_array","dir":"in","type":"ARRAY OF STRING","text":"value_array is an array of variable names that corresponds to each column of data item in the table. Each variable name can be specified as '[prog_name]var_name'. — [prog_name] specifies the name of the program that contains the specified variable. If [prog_name] is not specified, then the current program being executed is used. — var_name must refer to a static, global program variable. — var_name can contain node numbers, field names, and/or subscripts."},{"name":"vptr_array","dir":"out","type":"ARRAY OF ARRAY OF INTEGER","text":""},{"name":"table_data","dir":"in,out","type":"XWORK_T","text":"table_data is used to display and control the table. Do not change this data; it is used internally."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["The INIT_TBL and ACT_TBL built-in routines should only be used instead of DISCTRL_TBL if special processing needs to be done with each keystroke or if function key processing needs to be done without exiting the table menu.","INIT_TBL must be called before using the ACT_TBL built-in.INIT_TBL does not need to be called if using the DISCTRL_TBL built-in."],"env":"UIF"},"INI_DYN_DISB":{"kind":"procedure","purpose":"Initiates the dynamic display of a BOOLEAN variable. This procedure displays elements of a STRING ARRAY depending of the current value of the BOOLEAN variable.","params":[{"name":"b_var","dir":"in","type":"BOOLEAN","text":"The dynamic display is initiated based on the value of b_var. If b_var is FALSE, strings[1] is displayed; if b_var is TRUE, strings[2] is displayed. If b_var is uninitialized, a string of *'s is displayed. Both b_var and strings must be static (not local) variables."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"field_width","dir":"in","type":"INTEGER","text":"If field_width is non-zero, the display is extended with blanks if the element of strings[n] is shorter than this specified width. The area is cleared when the dynamic display is canceled."},{"name":"attr_mask","dir":"in","type":"INTEGER","text":"attr_mask is a bit-wise mask that indicates character display attributes. This should be one of the following constants: 0:Normal 1:Bold (Supported only on the CRT) 2:Blink (Supported only on the CRT) 4:Underline 8:Reverse video"},{"name":"char_size","dir":"in","type":"INTEGER","text":"char_size specifies whether data is to be displayed in normal, double-wide, or double-high, double-wide sizes. This should be one of the following constants: 0:Normal 1:Double-wide (Supported only on the CRT) 2:Double-high, double-wide"},{"name":"row","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"col","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"interval","dir":"in","type":"INTEGER","text":"interval indicates the minimum time interval, in milliseconds, between updates of the display. This must be greater then zero. The actual time might be greater since the task that formats the display runs at a low priority."},{"name":"strings","dir":"in","type":"ARRAY OF STRING","text":"strings[n] contains the text that will be displayed."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["To have multiple display attributes, use the OR operator to combine the constant attribute values together. For example, to have the text displayed as bold and underlined use 1 OR 4."],"env":"UIF","seeAlso":["CNC_DYN_DISB"]},"INI_DYN_DISE":{"kind":"procedure","purpose":"Initiates the dynamic display of an INTEGER variable. This procedure displays elements of a STRING ARRAY depending of the current value of the INTEGER variable.","params":[{"name":"e_var","dir":"in","type":"INTEGER","text":"The dynamic display is initiated based on the value of e_var. If e_var has a value of n, strings[n+1] is displayed; if e_var has a negative value, or a value greater than or equal to the length of the array of strings, a string of '?'s is displayed. Both e_var and string s must be static (not local) variables."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"field_width","dir":"in","type":"INTEGER","text":"If field_width is non-zero, the display is extended with blanks if the element of strings[n] is shorter than this specified width. The area is cleared when the dynamic display is canceled."},{"name":"attr_mask","dir":"in","type":"INTEGER","text":"attr_mask is a bit-wise mask that indicates character display attributes. This should be one of the following constants: 0:Normal 1:Bold (Supported only on the CRT) 2:Blink (Supported only on the CRT) 4:Underline 8:Reverse video"},{"name":"char_size","dir":"in","type":"INTEGER","text":"char_size specifies whether data is to be displayed in normal, double-wide, or double-high, double-wide sizes. This should be one of the following constants: 0:Normal 1:Double-wide (Supported only on the CRT) 2:Double-high, double-wide"},{"name":"row","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"col","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"interval","dir":"in","type":"INTEGER","text":"interval indicates the minimum time interval, in milliseconds, between updates of the display. This must be greater then zero. The actual time might be greater since the task that formats the display runs at a low priority."},{"name":"strings","dir":"in","type":"ARRAY OF STRING","text":"The dynamic display is initiated based on the value of e_var. If e_var has a value of n, strings[n+1] is displayed; if e_var has a negative value, or a value greater than or equal to the length of the array of strings, a string of '?'s is displayed. Both e_var and string s must be static (not local) variables."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Refer to the INI_DYN_DISB built-in procedure for a description of the other parameters listed above."],"env":"UIF","seeAlso":["CNC_DYN_DISE"]},"INI_DYN_DISI":{"kind":"procedure","purpose":"Initiate the dynamic display of an INTEGER variable in a specified window.","params":[{"name":"i_var","dir":"in","type":"INTEGER","text":"i_var is the integer whose dynamic display is to be initiated."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"field_width","dir":"in","type":"INTEGER","text":"If field_width is non-zero, the display is extended with blanks if i_var is shorter than this specified width. The area is cleared when the dynamic display is canceled."},{"name":"attr_mask","dir":"in","type":"INTEGER","text":"attr_mask is a bit-wise mask that indicates character display attributes. This should be one of the following constants: 0:Normal 1:Bold (Supported only on the CRT) 2:Blink (Supported only on the CRT) 4:Underline 8:Reverse video"},{"name":"char_size","dir":"in","type":"INTEGER","text":"char_size specifies whether data is to be displayed in normal, double-wide, or double-high, double-wide sizes. This should be one of the following constants: 0:Normal 1:Double-wide (Supported only on the CRT) 2:Double-high, double-wide"},{"name":"row","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"col","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"interval","dir":"in","type":"INTEGER","text":"interval indicates the minimum time interval, in milliseconds, between updates of the display. This must be greater then zero. The actual time might be greater since the task that formats the display runs at a low priority."},{"name":"buffer_size","dir":"in","type":"INTEGER","text":"buffer_size is not implemented."},{"name":"format","dir":"in","type":"STRING","text":"format is used to print out the variable. This can be passed as a literal enclosed in single quotes. The format string begins with a % and ends with a conversion character. Between the % and the conversion character there can be, in order: — Flags (in any order), which modify the specification: -: specifies left adjustment of this field. +: specifies that the number will always be printed with a sign. 0 specifies padding a numeric field width with leading zeroes. — A number that specifies the minimum field width. The converted argument will be printed in a field at least this wide. If necessary it will be padded on the left (or right, if left adjustment is called for) to make up the field width. — A period, which separates the field width from the precision. — A number, the precision, that specifies the maximum number of characters to be printed from a string, or the number of digits after the decimal point of a floating-point value, or the minimum number of digits for an integer. The format specifier must contain one of the conversion characters below. Conversion Characters Character Argument Type; Printed As d INTEGER; decimal number o INTEGER; unsigned octal notation (without a leading zero). x,X INTEGER; unsigned hexadecimal notation (without a leading 0x or 0X), using abcdef or ABCDEF for 10,..., 15. u INTEGER; unsigned decimal notation. s STRING; print characters from the string until end of string or the number of characters given by the precision. f REAL; decimal notation of the form [-]mmm.dddddd, where the number of d's is given by the precision. The default precision is 6; a precision of 0 suppresses the decimal point. e,E REAL; decimal notation of the form [-]m.dddddde+-xx or [-]m.ddddddE+-xx, where the number of d's is given by the precision. The default precision is 6; a precision of 0 suppresses the decimal point. g,G REAL; %e or %E is used if the exponent is less than -4 or greater than or equal to the precision; otherwise %f is used. Trailing zeros and a trailing decimal pointer are not printed. % no argument is converted; print a %."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Refer to the INI_DYN_DISB built-in procedure for a description of the other parameters listed above."],"env":"UIF","seeAlso":["DEF_WINDOW"]},"INI_DYN_DISP":{"kind":"procedure","purpose":"Initiates the dynamic display of a value of a port in a specified window, based on the port type and port number.","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the type of port to be displayed. Codes are defined in FROM: KLIOTYPS.KL. — If the port_type is a BOOLEAN port (e.g., DIN), If the is FALSE, strings[1] is displayed; If variable is TRUE, strings[2] is displayed. — If the port_type is an INTEGER port (e.g., GIN), if the value of the port is n, strings[n+1 ] will be displayed. If the value of the port is greater than or equal to the length of the array of strings, a string of '?'s is displayed."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number to be displayed."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"field_width","dir":"in","type":"INTEGER","text":"If field_width is non-zero, the display is extended with blanks if the element of strings[n] is shorter than this specified width. The area is cleared when the dynamic display is canceled."},{"name":"attr_mask","dir":"in","type":"INTEGER","text":"attr_mask is a bit-wise mask that indicates character display attributes. This should be one of the following constants: 0:Normal 1:Bold (Supported only on the CRT) 2:Blink (Supported only on the CRT) 4:Underline 8:Reverse video"},{"name":"char_size","dir":"in","type":"INTEGER","text":"char_size specifies whether data is to be displayed in normal, double-wide, or double-high, double-wide sizes. This should be one of the following constants: 0:Normal 1:Double-wide (Supported only on the CRT) 2:Double-high, double-wide"},{"name":"row","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"col","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"interval","dir":"in","type":"INTEGER","text":"interval indicates the minimum time interval, in milliseconds, between updates of the display. This must be greater then zero. The actual time might be greater since the task that formats the display runs at a low priority."},{"name":"strings","dir":"in","type":"ARRAY OF STRING","text":"port_type specifies the type of port to be displayed. Codes are defined in FROM: KLIOTYPS.KL. — If the port_type is a BOOLEAN port (e.g., DIN), If the is FALSE, strings[1] is displayed; If variable is TRUE, strings[2] is displayed. — If the port_type is an INTEGER port (e.g., GIN), if the value of the port is n, strings[n+1 ] will be displayed. If the value of the port is greater than or equal to the length of the array of strings, a string of '?'s is displayed."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Refer to the INI_DYN_DISB built-in procedure for a description of other parameters listed above."],"seeAlso":["CNC_DYN_DISP"]},"INI_DYN_DISR":{"kind":"procedure","purpose":"Initiates the dynamic display of a REAL variable in a specified window.","params":[{"name":"r_var","dir":"in","type":"REAL","text":"r_var is the REAL variable whose dynamic display is to be initiated."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"field_width","dir":"in","type":"INTEGER","text":"If field_width is non-zero, the display is extended with blanks if r_var is shorter than this specified width. The area is cleared when the dynamic display is canceled."},{"name":"char_size","dir":"in","type":"INTEGER","text":"char_size specifies whether data is to be displayed in normal, double-wide, or double-high, double-wide sizes. This should be one of the following constants: 0:Normal 1:Double-wide (Supported only on the CRT) 2:Double-high, double-wide"},{"name":"row","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"col","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"interval","dir":"in","type":"INTEGER","text":"interval indicates the minimum time interval, in milliseconds, between updates of the display. This must be greater then zero. The actual time might be greater since the task that formats the display runs at a low priority."},{"name":"buffer_size","dir":"in","type":"INTEGER","text":"buffer_size is not implemented."},{"name":"format","dir":"in","type":"STRING","text":"format is used to print out the variable. This can be passed as a literal enclosed in single quotes. The format string begins with a % and ends with a conversion character. Between the % and the conversion character there can be, in order: — Flags (in any order), which modify the specification: -: specifies left adjustment of this field. +: specifies that the number will always be printed with a sign. 0 specifies padding a numeric field width with leading zeroes. — A number that specifies the minimum field width. The converted argument will be printed in a field at least this wide. If necessary it will be padded on the left (or right, if left adjustment is called for) to make up the field width. — A period, which separates the field width from the precision. — A number, the precision, that specifies the maximum number of characters to be printed from a string, or the number of digits after the decimal point of a floating-point value, or the minimum number of digits for an integer. The format specifier must contain one of the conversion characters below. Conversion Characters Character Argument Type; Printed As d INTEGER; decimal number o INTEGER; unsigned octal notation (without a leading zero). x,X INTEGER; unsigned hexadecimal notation (without a leading 0x or 0X), using abcdef or ABCDEF for 10,..., 15. u INTEGER; unsigned decimal notation. s STRING; print characters from the string until end of string or the number of characters given by the precision. f REAL; decimal notation of the form [-]mmm.dddddd, where the number of d's is given by the precision. The default precision is 6; a precision of 0 suppresses the decimal point. e,E REAL; decimal notation of the form [-]m.dddddde+-xx or [-]m.ddddddE+-xx, where the number of d's is given by the precision. The default precision is 6; a precision of 0 suppresses the decimal point. g,G REAL; %e or %E is used if the exponent is less than -4 or greater than or equal to the precision; otherwise %f is used. Trailing zeros and a trailing decimal pointer are not printed. % no argument is converted; print a %."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Refer to the INI_DYN_DISI built-in procedure for a description of other parameters listed above."],"env":"UIF","seeAlso":["CNC_DYN_DISR"]},"INI_DYN_DISS":{"kind":"procedure","purpose":"Initiates the dynamic display of a STRING variable in a specified window.","params":[{"name":"s_var","dir":"in","type":"STRING","text":"s_var is the STRING variable whose dynamic display is to be initiated."},{"name":"window_name","dir":"in","type":"STRING","text":"window_name must be a previously defined window name."},{"name":"field_width","dir":"in","type":"INTEGER","text":"If field_width is non-zero, the display is extended with blanks if s_var is shorter than this specified width. The area is cleared when the dynamic display is canceled."},{"name":"char_size","dir":"in","type":"INTEGER","text":"char_size specifies whether data is to be displayed in normal, double-wide, or double-high, double-wide sizes. This should be one of the following constants: 0:Normal 1:Double-wide (Supported only on the CRT) 2:Double-high, double-wide"},{"name":"row","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"col","dir":"in","type":"INTEGER","text":"row and col specify the location in the window in which the data is to be displayed."},{"name":"interval","dir":"in","type":"INTEGER","text":"interval indicates the minimum time interval, in milliseconds, between updates of the display. This must be greater then zero. The actual time might be greater since the task that formats the display runs at a low priority."},{"name":"buffer_size","dir":"in","type":"INTEGER","text":"buffer_size is not implemented."},{"name":"format","dir":"in","type":"STRING","text":"format is used to print out the variable. This can be passed as a literal enclosed in single quotes. The format string begins with a % and ends with a conversion character. Between the % and the conversion character there can be, in order: — Flags (in any order), which modify the specification: -: specifies left adjustment of this field. +: specifies that the number will always be printed with a sign. 0 specifies padding a numeric field width with leading zeroes. — A number that specifies the minimum field width. The converted argument will be printed in a field at least this wide. If necessary it will be padded on the left (or right, if left adjustment is called for) to make up the field width. — A period, which separates the field width from the precision. — A number, the precision, that specifies the maximum number of characters to be printed from a string, or the number of digits after the decimal point of a floating-point value, or the minimum number of digits for an integer. The format specifier must contain one of the conversion characters below. Conversion Characters Character Argument Type; Printed As d INTEGER; decimal number o INTEGER; unsigned octal notation (without a leading zero). x,X INTEGER; unsigned hexadecimal notation (without a leading 0x or 0X), using abcdef or ABCDEF for 10,..., 15. u INTEGER; unsigned decimal notation. s STRING; print characters from the string until end of string or the number of characters given by the precision. f REAL; decimal notation of the form [-]mmm.dddddd, where the number of d's is given by the precision. The default precision is 6; a precision of 0 suppresses the decimal point. e,E REAL; decimal notation of the form [-]m.dddddde+-xx or [-]m.ddddddE+-xx, where the number of d's is given by the precision. The default precision is 6; a precision of 0 suppresses the decimal point. g,G REAL; %e or %E is used if the exponent is less than -4 or greater than or equal to the precision; otherwise %f is used. Trailing zeros and a trailing decimal pointer are not printed. % no argument is converted; print a %."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Refer to the INI_DYN_DISI built-in procedure for a description of other parameters listed above."],"env":"UIF","seeAlso":["INI_DYN_DISI"]},"INSERT_NODE":{"kind":"procedure","purpose":"Inserts an uninitialized node in the specified PATH argument preceding the specified path node number","params":[{"name":"path_var","dir":"in","type":"PATH","text":""},{"name":"node_num","dir":"in","type":"INTEGER","text":"node_num specifies the index number of the path node before which the new uninitialized node is to be inserted."},{"name":"status","dir":"out","type":"INTEGER","text":"If node_num is not a valid node number, status is returned with an error."}],"notes":["The new node can be assigned values by directly referencing its NODEDATA structure.","All nodes following the inserted node are renumbered.","Valid node_num values are in the range node_num => 1 and node_num <= PATH_LEN(path_va r).","If the program does not have enough RAM for an INSERT_NODE request, an error will occur.","If the program is paused, the INSERT_NODE request is NOT retried."],"env":"PATHOP","seeAlso":["APPEND_NODE"]},"INSERT_QUEUE":{"kind":"procedure","purpose":"Inserts an entry into a queue if the queue is not full","params":[{"name":"value","dir":"in","type":"INTEGER","text":"value specifies the value to be inserted into the queue, queue_t."},{"name":"sequence_no","dir":"in","type":"INTEGER","text":"sequence_no specifies the sequence number of the entry before which the new entry is to be inserted."},{"name":"queue_t","dir":"in,out","type":"QUEUE_TYPE","text":"queue_t specifies the queue variable for the queue."},{"name":"queue_data","dir":"in,out","type":"ARRAY OF INTEGER","text":"queue_data specifies the array used to hold the data in the queue. The length of this array determines the maximum number of entries in the queue."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with 61002, ``Queue is full,'' if there is no room for the entry in the queue, with 61003, ``Bad sequence no,'' if the specified sequence number is not in the queue."}],"env":"PBQMGR","seeAlso":["DELETE_QUEUE"]},"INV":{"kind":"function","purpose":"Used in coordinate frame transformations with the relative position operator (:) to determine the coordinate values of a POSITION in a frame that differs from the frame in which that POSITION was recorded","params":[{"name":"pos","dir":"in","type":"POSITION","text":"The returned value is the inverse of the pos argument."}],"notes":["The configuration of the returned POSITION will be that of the pos argument."],"env":"SYSTEM"},"IN_RANGE":{"kind":"function","purpose":"Returns a BOOLEAN value indicating whether or not the specified position argument can be reached by a group of axes","returns":"BOOLEAN","params":[{"name":"posn","dir":"in","type":"XYZWPREXT","text":"The returned value is TRUE if posn is within the work envelope of the group of axes; otherwise, FALSE is returned."}],"notes":["The current $UFRAME and $UTOOL are applied to posn."],"env":"SYSTEM","seeAlso":["CHECK_EPROS"]},"IO_MOD_TYPE":{"kind":"procedure","purpose":"Allows a KAREL program to determine the type of module in a specified rack/slot","params":[{"name":"rack_no","dir":"in","type":"INTEGER","text":"rack_no is the rack containing the port module. For process I/O boards, this is zero; for Allen-Bradley and Genius ports, this is 16."},{"name":"slot_no","dir":"in","type":"INTEGER","text":"slot_no is the slot containing the port module. For process I/O boards, this is the position of the board in the SLC-2 chain."},{"name":"mod_type","dir":"out","type":"INTEGER","text":"mod_type is the module type. 6 A16B-2202-470 7 A16B-2202-472 8 A16B-2202-480"},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid and there is a module or board with the specified rack/slot number as follows:"}],"env":"IOSETUP"},"IO_STATUS":{"kind":"function","purpose":"Returns an INTEGER value indicating the success or type of failure of the last operation on the file argument","returns":"INTEGER","params":[{"name":"file_id","dir":"in","type":"FILE","text":"Use READ file_id(cr) to clear any IO_STATUS error."}],"notes":["IO_STATUS can be used after an OPEN FILE, READ, WRITE, CANCEL FILE, or CLOSE FILE statement. Some of the common errors are shown below. IO_STATUS Errors 0 Last operation on specified file was successful 2021 End of file for RAM disk device 10006 End of file for floppy device 12311 Uninitialized variable 12324 Illegal open mode string 12325 Illegal file string 12326 File var is already used 12327 Open file failed 12328 File is not opened 12329 Cannot write the variable 12330 Write file failed 12331 Cannot read the variable 12332 Read data is too short 12333 Illegal ASCII string for read 12334 Read file failed 12335 Cannot open pre_defined file 12336 Cannot close pre_defined file 12338 Close file failed 12347 Read I/O value failed 12348 Write I/O value failed 12358 Timeout at read request 12359 Read request is nested 12367 Bad base in format","If file_id does not correspond to an opened file or one of the pre-defined ``files'' opened to the respective CRT/KB, teach pendant, and vision windows, the program is aborted with an error."],"env":"PBCORE"},"JOINT2POS":{"kind":"function","purpose":"This routine is used to convert joint angles (in_jnt) to a Cartesian position (out_pos) by calling the forward kinematics routine.","params":[{"name":"in_jnt","dir":"in","type":"JOINTPOS","text":"The input in_jnt is defined as the joint angles to be converted to the Cartesian position."},{"name":"uframe","dir":"in","type":"POSITION","text":"The input uframe is the user frame for the Cartesian position."},{"name":"utool","dir":"in","type":"POSITION","text":"The input utool is defined as the corresponding tool frame."},{"name":"config_ref","dir":"in","type":"INTEGER","text":"The input config_ref is an integer representing the type of solution desired. The values listed below are valid. Also, the pre-defined constants in the parentheses can be used and the values can be added as required. One example includes: config_ref = HALF_SOLN + CONFIG_TCP. — 0:(FULL_SOLN) = Default — 1: (HALF_SOLN) = Wrist joint (xyz456). This value does not calculate/use wpr. — 2:(CONFIG_TCP) = The Wrist Joint Config (up/down) is based on the fixed wrist. — 4:(APPROX_SOLN) = Approximate solution. This value reduce calculation time for some robots. — 8:(NO_TURNS) = Ignore wrist turn numbers. Use the closest path for joints 4, 5 and 6 (uses ref_jnt). — 16:(NO_M_TURNS) = Ignore major axis (J1 only) turn number. Use the closest path."},{"name":"out_pos","dir":"out","type":"POSITION","text":"The output out_pos is the Cartesian position corresponding to the input joint angles."},{"name":"wjnt_cfg","dir":"out","type":"CONFIG","text":"The output wjnt_cfg is the wrist joint configuration. The value will be output when config_ref corresponds to HALF_SOLN."},{"name":"ext_ang","dir":"out","type":"ARRAY OF REAL","text":"The output ext_ang contains the values of the joint angles for the extended axes if they exist."},{"name":"status","dir":"out","type":"INTEGER","text":"The output status explains the status of the attempted operation. If it is not equal to 0, then an error has occurred."}],"env":"MOTN"},"J_IN_RANGE":{"kind":"function","purpose":"Returns a BOOLEAN value indicating whether or not the specified joint position argument can be reached by a group of axes","returns":"BOOLEAN","params":[{"name":"posn","dir":"in","type":"JOINTPOS","text":"The returned value is TRUE if posn is within the work envelope; otherwise, FALSE is returned."}],"env":"SYSTEM","seeAlso":["IN_RANGE","CHECK_EPROS"]},"KCL":{"kind":"procedure","purpose":"Sends the KCL command specified by the STRING argument to KCL for execution.","params":[{"name":"command","dir":"in","type":"STRING","text":"command must contain a valid KCL command. command cannot exceed 126 characters."},{"name":"status","dir":"out","type":"INTEGER","text":"status indicates whether the command was executed successfully."}],"notes":["Program execution waits until execution of the KCL command is completed or until an error is detected.","All KCL commands are performed as if they were entered at the command level, with the exception of destructive commands, such as CLEAR ALL, for which no confirmation is required.","If a KCL command file is being executed and $STOP_ON_ERR is FALSE, the KCL built-in will continue to run to completion. The first error detected will be returned or a 0 if no errors occurred."],"env":"KCLOP","seeAlso":["KCL_STATUS"]},"KCL_NO_WAIT":{"kind":"procedure","purpose":"Sends the KCL command specified by the STRING argument to KCL for execution, but does not wait for completion of the command before continuing program execution.","params":[{"name":"command","dir":"in","type":"STRING","text":"command must contain a valid KCL command."},{"name":"status","dir":"out","type":"INTEGER","text":"status indicates whether KCL accepted the command."}],"notes":["Program execution waits until KCL accepts the command or an error is detected."],"env":"KCLOP","seeAlso":["KCL_STATUS"]},"KCL_STATUS":{"kind":"procedure","purpose":"Returns the status of the last executed command from either KCL or KCL_NO_WAIT built-in procedures.","returns":"INTEGER","notes":["Returns the status of the last executed command from the KCL or KCL_NO_WAIT built-ins.","Program execution waits until KCL can return the status."],"env":"KCLOP","seeAlso":["KCL"]},"LN":{"kind":"function","purpose":"Returns the natural logarithm of a specified REAL argument","returns":"REAL","params":[{"name":"x","dir":"in","type":"REAL","text":"x must be greater than zero. Otherwise, the program will be aborted with an error."}],"notes":["The returned value is the natural logarithm of x."],"env":"SYSTEM"},"LOAD":{"kind":"procedure","purpose":"Loads the specified file","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the device, name, and type of the file to load. The following types are valid:.TP Teach pendant program.PC KAREL program.VR KAREL variables.SV KAREL system variables.IO I/O configuration data no ext KAREL program and variables"},{"name":"option_sw","dir":"in","type":"INTEGER","text":"option_sw specifies the type of options to be done during loading. The following value is valid for.TP files: — 1 If the program already exists, then it overwrites the program. If option_sw is not 1 and the program exists, an error will be returned. The following value is valid for.SV files: — 1 Converts system variables. option_sw is ignored for all other types."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred. Note For R-30iB Plus, R-30iB, and R-30iB Mate controllers, the KAREL option must be installed on the robot controller in order to load KAREL programs."}],"env":"PBCORE"},"LOAD_STATUS":{"kind":"procedure","purpose":"Determines whether the specified KAREL program and its variables are loaded into memory","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name must be a program and cannot be a routine."},{"name":"loaded","dir":"out","type":"BOOLEAN","text":"loaded returns a value of TRUE if prog_name is currently loaded into memory. FALSE is returned if prog_name is not loaded."},{"name":"initialized","dir":"out","type":"BOOLEAN","text":"initialized returns a value of TRUE if any variable within prog_name has been initialized. FALSE is returned if all variables within prog_name are uninitialized."}],"notes":["If either loaded or initialized is FALSE, use the LOAD built-in procedure to load prog_name and its variables."],"env":"PBCORE"},"LOCK_GROUP":{"kind":"procedure","purpose":"Locks motion control for the specified group of axes","params":[{"name":"group_mask","dir":"in","type":"INTEGER","text":"group_mask specifies the group of axes to lock for the running task. The group numbers must be in the range of 1 to the total number of groups defined on the controller. The group_mask is specified by setting the bit(s) for the desired group(s). Group_mask Setting GROUP DECIMAL BIT Group 1 1 1 Group 2 2 2 Group 3 4 3 To specify multiple groups select the decimal values which correspond to the desired groups. Then connect them together using the OR operator. For example to specify groups 1, 3, enter \"1 OR 4\"."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, an error occurred."}],"notes":["Motion control is gained for the specified motion groups.","If one or more of the groups cannot be locked, then an error is returned, and any available groups will be locked.","Moving a group automatically locks the group if it has not been previously locked by another task.","If a task tries to move a group that is already locked by another task, it will be paused."],"env":"MULTI"},"MIRROR":{"kind":"function","purpose":"Determines the mirror image of a specified position variable.","returns":"XYZWPREXT","params":[{"name":"old_pos","dir":"in","type":"POSITION","text":"old_pos and mirror_frame must both be defined relative to the same user frame. old_pos specifies the value whose mirror image is to be generated."},{"name":"mirror_frame","dir":"in","type":"POSITION","text":"mirror_frame specifies the value across whose xz_plane the image is to be generated."},{"name":"orient_flag","dir":"in","type":"BOOLEAN","text":"If orient_flag is TRUE, both the orientation and location component of old_pos will be mirrored. If FALSE, only the location is mirrored and the orientation of the new mirror-image position is the same as that of old_pos."}],"notes":["The returned mirrored position is not guaranteed to be a reachable position, since the mirrored position can be outside of the robot's work envelope."],"env":"MIR"},"MODIFY_QUEUE":{"kind":"procedure","purpose":"Replaces the value of an entry of a queue.","params":[{"name":"value","dir":"in","type":"INTEGER","text":"value specifies the value to be inserted into the queue."},{"name":"sequence_no","dir":"in","type":"INTEGER","text":"sequence_no specifies the sequence number of the entry whose value is to be modified"},{"name":"queue_t","dir":"in,out","type":"QUEUE_TYPE","text":"queue_t specifies the queue variable for the queue"},{"name":"queue_data","dir":"in,out","type":"ARRAY OF INTEGER","text":"queue_data specifies the array used to hold the data in the queue. The length of this array determines the maximum number of entries in the queue."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with 61003, ``Bad sequence no,'' if the specified sequence number is not in the queue."}],"env":"PBQMGR","seeAlso":["DELETE_QUEUE"]},"MOTION_CTL":{"kind":"function","purpose":"Determines whether the KAREL program has motion control for the specified group of axes","returns":"BOOLEAN","params":[{"name":"group_mask","dir":"in","type":"INTEGER","text":"The group_mask is specified by setting the bit(s) for the desired group(s). Group_mask Setting GROUP DECIMAL BIT Group 1 1 1 Group 2 2 2 Group 3 4 3 To specify multiple groups select the decimal values which correspond to the desired groups. Then connect them together using the OR operator. For example to specify groups 1, 3, enter \"1 OR 4\"."}],"notes":["If group_mask is omitted, the default group mask for the program is assumed.","The default group_mask is determined by the %LOCKGROUP and %NOLOCKGROUP directives.","Returns TRUE if the KAREL program has motion control for the specified group of axes."],"env":"MOTN"},"MOUNT_DEV":{"kind":"procedure","purpose":"Mounts the specified device","params":[{"name":"device","dir":"in","type":"STRING","text":"device specifies the device to be mounted."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If it is not equal to 0, then an error occurred."}],"env":"FDEV"},"MOVE_FILE":{"kind":"procedure","purpose":"Moves the specified file from one memory file device to another","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the device, name, and type of the file to be moved. The file should exist on the FROM or RAM disks."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If file_spec is a file on the FROM disk, the file is moved to the RAM disk, and vice versa.","The wildcard character (*) can be used to replace the entire file name, the first part of the file name, the last part of the file name, or both the first and last parts of the file name. The file type can also use the wildcard in the same manner. If file_spec specifies multiple files, then they are all moved to the other disk."],"env":"FDEV"},"MSG_CONNECT":{"kind":"procedure","purpose":"Connect a client or server port to another computer for use in Socket Messaging.","params":[{"name":"tag","dir":"in","type":"STRING","text":"Tag is the name of a client port (C1:-C8) or server port (S1:S8)."},{"name":"status","dir":"out","type":"INTEGER","text":"Status explains the status of the attempted operation. If it is not equal to 0, then an error occurred."}],"env":"FLBT"},"MSG_DISCO":{"kind":"procedure","purpose":"Disconnect a client or server port from another computer.","params":[{"name":"tag","dir":"in","type":"STRING","text":"Tag is the name of a client port (C1:-C8) or server port (S1:S8)."},{"name":"status","dir":"out","type":"INTEGER","text":"Status explains the status of the attempted operation. If it is not equal to 0, then an error occurred. Status explains the status of the attempted operation. If it is not equal to 0, then an error occurred."},{"name":"status","dir":"out","type":"INTEGER","text":"Status explains the status of the attempted operation. If it is not equal to 0, then an error occurred. Status explains the status of the attempted operation. If it is not equal to 0, then an error occurred."}],"notes":["Host name is the name of the host to perform the check on. An entry for the host has to be present in the host entry tables (or the DNS option loaded and configured on the robot)."],"env":"FLBT"},"NODE_SIZE":{"kind":"function","purpose":"Returns the size (in bytes) of a PATH node","returns":"INTEGER","params":[{"name":"path_var","dir":"in","type":"PATH","text":""}],"notes":["The returned value is the size of an individual PATH node, including the positional data type size and any associated data.","The returned value can be used to calculate file positions for random access to nodes in files."],"env":"PATHOP"},"OPEN_TPE":{"kind":"procedure","purpose":"Opens the specified teach pendant program","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the teach pendant program to be opened. prog_name must be in all capital letters. prog_name must be closed, using CLOSE_TPE, before prog_name can be executed."},{"name":"open_mode","dir":"in","type":"INTEGER","text":"open_mode determines the access code to the program. The access codes are defined as follows: 0: none TPE_RDACC: Read Access TPE_RWACC: Read/Write Access"},{"name":"reject_mode","dir":"in","type":"INTEGER","text":"reject_mode determines the reject code to the program. The program that has been with a reject code cannot be opened by another program. The reject codes are defined as follows: TPE_NOREJ: none TPE_RDREJ: Read Reject TPE_WRTREJ: Write Reject TPE_RWREJ: Read/Write Reject TPE_ALLREJ: All Reject"},{"name":"open_id","dir":"out","type":"INTEGER","text":"open_id indicates the id number of the opened program."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."}],"notes":["All open teach pendant programs are closed automatically when the KAREL program is aborted or exits normally."],"env":"PBCORE","seeAlso":["CREATE_TPE","COPY_TPE","AVL_POS_NUM"]},"ORD":{"kind":"function","purpose":"Returns the numeric ASCII code corresponding to the character in the STRING argument that is referenced by the index argument","returns":"INTEGER","params":[{"name":"str","dir":"in","type":"STRING","text":"str_index specifies the indexed position of a character in the argument str. A value of 1 indicates the first character."},{"name":"str_index","dir":"in","type":"INTEGER","text":"str_index specifies the indexed position of a character in the argument str. A value of 1 indicates the first character."}],"notes":["The returned value represents the ASCII numeric code of the specified character.","If str_index is less than one or greater than the current length of str, the program is paused with an error."],"env":"SYSTEM"},"ORIENT":{"kind":"function","purpose":"Returns a unit VECTOR representing the y-axis (orient vector) of the specified POSITION argument","returns":"VECTOR","params":[{"name":"posn","dir":"in","type":"POSITION","text":"The returned value is the orient vector of posn."}],"notes":["Instead of using this built-in, you can directly access the Orient Vector of a POSITION.","The orient vector is the positive y-direction in the tool coordinate frame."],"env":"VECTR"},"PATH_LEN":{"kind":"function","purpose":"Returns the number of nodes in the PATH argument","returns":"INTEGER","params":[{"name":"path_nam","dir":"in","type":"PATH","text":""}],"notes":["The returned value corresponds to the number of nodes in the PATH variable argument.","Calling PATH_LEN with an uninitialized PATH returns a value of zero."],"env":"PBCORE","seeAlso":["COPY_PATH"]},"PAUSE_TASK":{"kind":"procedure","purpose":"Pauses the specified executing task","params":[{"name":"task_name","dir":"in","type":"STRING","text":"task_name is the name of the task to be paused. If task name is '*ALL*', all executing tasks are paused except the tasks that have the ``ignore pause request'' attribute set."},{"name":"force_sw","dir":"in","type":"BOOLEAN","text":"force_sw specifies whether a task should be paused even if the task has the ``ignore pause request'' attribute set. This parameter is ignored if task_name is '*ALL*'."},{"name":"stop_mtn_sw","dir":"in","type":"BOOLEAN","text":"stop_mtn_sw specifies whether all motion groups belonging to the specified task are stopped."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"MULTI","seeAlso":["ABORT_TASK"]},"PEND_SEMA":{"kind":"procedure","purpose":"Suspends execution of the task until either the value of the semaphore is greater than zero or max_time expires","params":[{"name":"semaphore_no","dir":"in","type":"INTEGER","text":"semaphore_no specifies the semaphore number to use. semaphore_no must be in the range of 1 to the number of semaphores defined on the controller."},{"name":"max_time","dir":"in","type":"INTEGER","text":"max_time specifies the expiration time, in milliseconds. A max_time value of -1 indicates to wait forever, if necessary."},{"name":"time_out","dir":"out","type":"BOOLEAN","text":"On continuation, time_out is set TRUE if max_time expired without the semaphore becoming nonzero, otherwise it is set FALSE."}],"notes":["PEND_SEMA decrements the value of the semaphore."],"env":"MULTI","seeAlso":["CLEAR_SEMA","SEMA_COUNT"]},"PIPE_CONFIG":{"kind":"procedure","purpose":"Configure a pipe for special use.","params":[{"name":"pipe_name","dir":"in","type":"STRING","text":"pipe_name is the name of the pipe file. If the file does not exist it will be created with this operation."},{"name":"cmos_flag","dir":"in","type":"BOOLEAN","text":"CMOS_flag if set to TRUE will put the pipe data in CMOS. By default pipe data is in DRAM."},{"name":"n_sectors","dir":"in","type":"INTEGER","text":"n_sectors number of 1024 byte sectors to allocate to the pipe. The default is 8."},{"name":"record_size","dir":"in","type":"INTEGER","text":"record_size the size of a binary record in a pipe. If set to 0 the pipe is treated as ASCII. If a pipe is binary and will be printed as a formatted data then this must be set to the record length."},{"name":"form_dict","dir":"in","type":"STRING","text":"form_dict is the name of the dictionary containing formatting information."},{"name":"form_ele","dir":"in","type":"INTEGER","text":"form_ele is the element number in form_dict containing the formatting information."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If it is not equal to 0, then an error occurred."}],"env":"FLBT"},"POP_KEY_RD":{"kind":"procedure","purpose":"Resumes key input from a keyboard device","params":[{"name":"key_dev_name","dir":"in","type":"STRING","text":"key_dev_name must be one of the keyboard devices already defined: 'TPKB':Teach Pendant Keyboard Device 'CRKB':CRT Keyboard Device"},{"name":"pop_index","dir":"in","type":"INTEGER","text":""},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Resumes all suspended read requests on the specified keyboard device.","If there were no read requests active when suspended, this operation will not resume any inputs. This is not an error.","pop_id is returned from PUSH_KEY_RD and should be used to re-activate the read requests."],"env":"PBCORE","seeAlso":["READ_KB"]},"POS":{"kind":"function","purpose":"Returns an XYZWPR composed of the specified location arguments (x,y,z), orientation arguments (w,p,r), and configuration argument (c)","returns":"XYZWPR","params":[{"name":"c","dir":"in","type":"CONFIG","text":"c must be a valid configuration for the robot attached to the controller. CNV_STR_CONF can be used to convert a string to a CONFIG variable."}],"notes":["x, y, and z are the Cartesian values of the location (in millimeters). Each argument must be in the range±10000000 mm (±10 km). Otherwise, the program is paused with an error.","w, p, and r are the yaw, pitch, and roll values of the orientation (in degrees). Each argument must be in the range ±180 degrees. Otherwise, the program is paused with an error."],"env":"SYSTEM"},"POS2JOINT":{"kind":"function","purpose":"This routine is used to convert Cartesian positions (in_pos) to joint angles (out_jnt) by calling the inverse kinematics routine.","params":[{"name":"ref_jnt","dir":"in","type":"JOINTPOS","text":"The input ref_jnt are the reference joint angles that represent the robot's position just before moving to the current position."},{"name":"in_pos","dir":"in","type":"POSITION","text":"The input in_pos is the robot Cartesian position to be converted to joint angles."},{"name":"uframe","dir":"in","type":"POSITION","text":"The input uframe is the user frame for the Cartesian position."},{"name":"utool","dir":"in","type":"POSITION","text":"The input utool is the corresponding tool frame."},{"name":"config_ref","dir":"in","type":"INTEGER","text":"The input config_ref is an integer representing the type of solution desired. The values listed below are valid. Also, the pre-defined constants in the parentheses can be used and the values can be added as required. One example includes: config_ref = HALF_SOLN + CONFIG_TCP. — 0:(FULL_SOLN) = Default — 1: (HALF_SOLN) = Wrist joint (XYZ456). This does not calculate/use WPR. — 2:(CONFIG_TCP) = The Wrist Joint Config (up/down) is based on the fixed wrist. — 4:(APPROX_SOLN) = Approximate solution. Reduce calculation time for some robots. — 8:(NO_TURNS) = Ignore wrist turn numbers. Use the closest path for joints 4, 5 and 6 (uses ref_jnt). — 16:(NO_M_TURNS) = Ignore major axis (J1 only) turn number. Use the closest path."},{"name":"wjnt_cfg","dir":"in","type":"CONFIG","text":"The input wjnt_cfg is the wrist joint configuration. This value must be input when config_ref corresponds to HALF_SOLN."},{"name":"ext_ang","dir":"in","type":"ARRAY OF REAL","text":"The input ext_ang contains the values of the joint angles for the extended axes if they exist."},{"name":"out_jnt","dir":"out","type":"JOINTPOS","text":"The output out_jnt are the joint angles that correspond to the Cartesian position"},{"name":"status","dir":"out","type":"INTEGER","text":"The output status explains the status of the attempted operation. If it is not equal to 0, then an error has occurred."}],"env":"MOTN"},"POST_ERR":{"kind":"procedure","purpose":"Posts the error code and reason code to the error reporting system to display and keep history of the errors","params":[{"name":"error_code","dir":"in","type":"INTEGER","text":"error_code is the error to be posted. error_code and cause_code are in the following format: ffccc (decimal) where ff represents the facility code of the error. ccc represents the error code within the specified facility."},{"name":"parameter","dir":"in","type":"STRING","text":"parameter will be included in error_code's message if %s is specified in the dictionary text. If not necessary, then enter the null string."},{"name":"cause_code","dir":"in","type":"INTEGER","text":"cause_code is the reason for the error. 0 can be used if no cause is applicable."},{"name":"severity","dir":"in","type":"INTEGER","text":"severity is defined as follows: 0: WARNING, no change in task execution 1: PAUSE, all tasks and stop all motion 2: ABORT, all tasks and cancel"}],"env":"PBCORE","seeAlso":["ERR_DATA"]},"POST_ERR_L":{"kind":"procedure","purpose":"Posts the error code with local severity to the error reporting system to display and keep history of the errors","params":[{"name":"error_code","dir":"in","type":"INTEGER","text":"error_code is the error to be posted. error_code and cause_code are in the following format: ffccc (decimal) where ff represents the facility code of the error. ccc represents the error code within the specified facility."},{"name":"parameter","dir":"in","type":"STRING","text":"parameter will be included in error_code's message if %s is specified in the dictionary text. If not necessary, then enter the null string."},{"name":"cause_code","dir":"in","type":"INTEGER","text":"cause_code is the reason for the error. 0 can be used if no cause is applicable."},{"name":"severity","dir":"in","type":"INTEGER","text":"severity is defined as follows: ERSEV_NONE: No severity ERSEV_WARN: WARNING, no change in task execution ERSEV_PAUSE: PAUSE Global, pause all tasks and stop all motion after current motion segment ERSEV_PAUSEL: PAUSE Local, pause local task and stop all motion for local task after current motion segment ERSEV_STOP: STOP Global, pause all tasks and stop all motion ERSEV_STOPL: STOP Local, pause local task and stop all motion for local task ERSEV_SERVO: SERVO Global, turn off all servo power and pause all tasks ERSEV_SERVOL: SERVO Local, turn off servo power for local task motion groups and pause local tasks ERSEV_ABORT: ABORT Global, abort all tasks and cancel all motion ERSEV_ABORTL: ABORT Local, abort local task and cancel all motion for local task ERSEV_SYSTEM: SYSTEM Global, system problem exist and prevent any further operation"}],"env":"PBCORE","seeAlso":["POST_ERR"]},"POST_SEMA":{"kind":"procedure","purpose":"Add one to the value of the indicated semaphore","notes":["The semaphore indicated by semaphore_no is incremented by one.","semaphore_no must be in the range of 1 to the number of semaphores defined on the controller."],"env":"MULTI","seeAlso":["CLEAR_SEMA","SEMA_COUNT"]},"POS_REG_TYPE":{"kind":"procedure","purpose":"Returns the position representation of the specified position register","params":[{"name":"register","dir":"in","type":"INTEGER","text":"register_no specifies the position register."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed."},{"name":"posn_type","dir":"out","type":"INTEGER","text":"posn_type returns the position type. posn_type is defined as follows: — 1:POSITION — 2:XYZWPR — 6:XYZWPREXT — 9:JOINTPOS"},{"name":"num_axes","dir":"out","type":"INTEGER","text":"num_axes returns number of axes in the representation if the position type is a JOINTPOS. If the position type is an XYZWPREXT, only the number of extended axes is returned by num_axes."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"REGOPE","seeAlso":["SET_JPOS_REG"]},"PRINT_FILE":{"kind":"procedure","purpose":"Prints the contents of an ASCII file to the default device","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the device, name, and type of the file to print."},{"name":"nowait_sw","dir":"in","type":"BOOLEAN","text":"If nowait_sw is TRUE, execution of the program continues while the command is executing. If it is FALSE, the program stops, including condition handlers, until the operation has completed. If you have time critical condition handlers in your program, put them in another program that executes as a separate task. Note nowait_sw is not available in this release and should be set to FALSE."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"FDEV"},"PROG_BACKUP":{"kind":"procedure","purpose":"Saves the specified program and all called programs from execution memory to a storage device. If the called programs call other programs they will be saved recursively. You can specify that any associated program variables be saved.","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the device and program to save. If a file type is specified, it is ignored."},{"name":"prog_type","dir":"in","type":"INTEGER","text":"prog_type specifies the type of programs to be saved. The valid types are: PBR_VRTYPE:VR - programs which contain variables PBR_MNTYPE:JB, PR, MR, TP PBR_JBTYPE:JB - job programs only PBR_PRTYPE:PR - process programs only PBR_MRTYPE:MR - macro programs only PBR_PCTYPE: VR - saves VR files not PC files PBR_ALLTYPE:all programs VR, JB, PR, MR, TP PBR_NVRTYPE:all programs except VR PBR_NMRTYPE:JB, PR, TP (all TPs except Macros)"},{"name":"max_size","dir":"in","type":"INTEGER","text":"max_size specifies the maximum size of disk space in kilobytes required to backup the programs. If not enough memory is available on the storage device, no programs will be backed up and status will equal 2002, “FILE-002 Device is Full”."},{"name":"write_prot","dir":"in","type":"BOOLEAN","text":"write_prot, if true, specifies that write protected programs should be saved. If false, specifies that write protected programs should not be saved."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If the required disk space to backup the programs exceeds max_size the backup will continue. The backup might still fail if there is not enough space to save all the programs. The return status will equal 2002, will exist. To prevent this case be sure that max_size is large enough to prevent this error.","The system will stay in the loop and handle as many programs as it can even when it gets an error. For example, if there is one missing program out of eight, the remaining seven programs are saved. In this case the error \"Program does not exist\" is returned to the user in status. An error is posted in this case with the program name in the error for each program. The cause code is whatever is returned from the save routine.","If a subdirectory is specified on the storage device, it will be created if it does not already exist. All programs will be saved into the subdirectory.","If a file already exists but the no changes have occurred, the file is not overwritten.","If a file already exists but the program has been changed, it will be overwritten and no error is returned.","A KAREL or teach pendant program of the same name with variables must exist in memory as a called program or else the system will not save the VR.","The PROG_BACKUP, PROG_CLEAR and PROG_RESTORE built-ins consider all references to programs except for macros. This includes any programs referenced in the following statements: CALL, RUN, ERROR_PROG, RESUME_PROG, and MONITOR."],"env":"CORE"},"PROG_CLEAR":{"kind":"procedure","purpose":"Clear the specified program and all called programs from execution memory. If the called programs call other programs they will be cleared recursively. You can specify that any associated program variables also be cleared. Variables which are referenced from other programs will not be cleared.","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the root program which is to be cleared."},{"name":"prog_type","dir":"in","type":"INTEGER","text":"prog_type specifies the type of programs to be cleared. The valid types are: PBR_VRTYPE:VR - programs which contain variables PBR_MNTYPE:JB, PR, MR, TP PBR_JBTYPE:JB - job programs only PBR_PRTYPE:PR - process programs only PBR_MRTYPE:MR - macro programs only PBR_PCTYPE: VR - saves VR files not PC files PBR_ALLTYPE:all programs VR, JB, PR, MR, TP PBR_NVRTYPE:all programs except VR PBR_NMRTYPE:JB, PR, TP (all TPs except Macros)"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["The system will stay in the loop and clear as many programs as it can. If one of the called programs is missing, this is not an error. However, if that missing program calls other programs those other programs will not be found and will not be cleared. Errors are posted with the program name in the error for each program which is not cleared. The cause code is whatever is returned from the clear routine.","Clearing of any VR data is subject to being referenced by another program. This error will be ignored for any variable clear operation.","If a programs which is identified for clearing is the selected program it will not be cleared. The error “Program is in use” is returned in this case. As a countermeasure the use must use SELECT_TPE() built-in to select a program which is not in the clear set.","The PROG_BACKUP, PROG_CLEAR and PROG_RESTORE built-ins consider all references to programs except for macros. This includes any programs referenced in the following statements: CALL, RUN, ERROR_PROG, RESUME_PROG, and MONITOR."],"env":"CORE"},"PROG_LIST":{"kind":"procedure","purpose":"Returns a list of program names.","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the program(s) to be returned in ary_name. prog_name may use the wildcard (*) character, to indicate that all programs matching the prog_type should be returned in ary_name. prog_name = 12 or 36 characters followed by a space"},{"name":"prog_type","dir":"in","type":"INTEGER","text":"prog_type specifies the type of programs to be retrieved. The valid types are: 1:VR - programs which contain only variables 2:JB, PR, MR, TP3:JB - job programs only 4:PR - process programs only 5:MR - macro programs only 6:PC - KAREL programs only 7:all programs VR, JB, PR, MR, TP, PC 8:all programs except VR prog_type = 2 characters"},{"name":"n_skip","dir":"in","type":"INTEGER","text":"n_skip This parameter can only be used when using * for the program name and 7 for the program type. Otherwise used the f_index parameter for multiple calls when more programs exist than the declared length of ary_name. Set n_skip to 0 the first time you use PROG_LIST. If ary_name is completely filled with program names, copy the array to another ARRAY of STRINGS and execute PROG_LIST again with n_skip equal to n_skip + n_progs. The call to PROG_LIST will then skip the programs found in the previous passes and locate only the remaining programs."},{"name":"format","dir":"in","type":"INTEGER","text":"format specifies the format of the program name. The following values are valid for format: 1:program name only, no blanks 2:'program name program type' total length = 15 or 39 characters"},{"name":"ary_name","dir":"out","type":"ARRAY OF STRING","text":"ary_name is an ARRAY of STRING used to store the program names."},{"name":"n_progs","dir":"out","type":"INTEGER","text":"n_progs is the number of variables stored in the ary_name."},{"name":"status","dir":"out","type":"INTEGER","text":"status will return zero if successful."},{"name":"f_index","dir":"in,out","type":"INTEGER","text":"f_index is an optional parameter for fast indexing. If you specify prog_name as a complex wildcard (anything other than the straight *), then you should use this parameter. The first call to PROG_LIST set f_index and n_skip both to zero. f_index will then be used internally to quickly find the next prog_name. DO NOT change f_index once a listing for a particular prog_name has begun.","optional":true}],"env":"BYNAM","seeAlso":["VAR_LIST"]},"PROG_RESTORE":{"kind":"procedure","purpose":"Restores (loads) the specified program and all called programs into execution memory. If the called programs call other programs they will be loaded recursively. Any associated program variables will also be loaded if the VR files exist.","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the storage device and program to restore. If a file type is specified, it is ignored."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["The system will stay in the loop and handles as many programs as it can even when it gets an error. For example, if there is one missing program out of eight, the remaining seven programs are loaded. In this case the error \"File does not exist\" is returned to the user in status. An error is posted in this case with the program name in the error for each program. The cause code is whatever is returned from the load routine.","If a subdirectory is specified, the called programs are loaded from that subdirectory. Any extra files in that subdirectory will not automatically be loaded.","If the program already exists, it will not be restored and no error is returned.","A KAREL or TP program of the same name must already exist in memory as a called program or else the system will not load the VR.","VR types will be restored even if the variables already exist. That is the system will overwrite any existing variable values with the values saved in the VR file.","ASCII programs (.LS) cannot be restored.","If not enough memory is available, then an error is returned and the restore is incomplete.","The PROG_BACKUP, PROG_CLEAR and PROG_RESTORE built-ins consider all references to programs except for macros. This includes any programs referenced in the following statements: CALL, RUN, ERROR_PROG, RESUME_PROG, and MONITOR."],"env":"CORE"},"PURGE_DEV":{"kind":"procedure","purpose":"Purges the specified memory file device by freeing any used blocks that are no longer needed","params":[{"name":"device","dir":"in","type":"STRING","text":"device specifies the memory file device to purge. device should be set to 'FR:' for FROM disk, 'RD:' for RAM disk, or 'MF:' for both disks. The device must be mounted and no files can be open on the device or an error will be returned."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0 then an error occurred. 85023 is returned if no errors occurred, but no blocks were purged."}],"notes":["The purge operation is only necessary when the device does not have enough memory to perform an operation. The 'FR:' device will return 85001 if the FROM disk is full. The 'RD:' device will return 85020 if the RAM disk is full.","The purge operation will erase file blocks that were previously used, but no longer needed. These are called garbage blocks. The FROM disk may contain many garbage blocks if files are deleted or overwritten. The RAM disk does not normally contain garbage blocks, but they can occur when power is removed during a file copy.","The VOL_SPACE built-in can be used to determine the number of garbage blocks on the FROM disk. Hardware limitations may reduce the number of blocks actually freed."],"env":"FDEV"},"PUSH_KEY_RD":{"kind":"procedure","purpose":"Suspend key input from a keyboard device","params":[{"name":"key_dev_name","dir":"in","type":"STRING","text":"key_dev_name must be one of the keyboard devices already defined: 'TPKB':Teach Pendant Keyboard Device 'CRKB':CRT Keyboard Device"},{"name":"key_mask","dir":"in","type":"INTEGER","text":"key_mask is a bit-wise mask indicating the classes of characters that will be suspended. This should be an OR of the constants defined in the include file klevkmsk.kl. kc_display:Displayable keys kc_func_key:Function keys kc_keypad:Keypad and Edit keys kc_enter_key:Enter and Return keys kc_delete:Delete and Backspace keys kc_lr_arw:Left and Right Arrow keys kc_ud_arw:Up and Down Arrow keys kc_other:Other keys (such as Prev)"},{"name":"pop_index","dir":"out","type":"INTEGER","text":""},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Suspends all read requests on the specified keyboard device that uses (either as accept_mask or term_mask) any of the specified key classes.","If there are no read requests active, a null set of inputs is recorded as suspended. This is not an error.","pop_id is returned and should be used in a call to POP_KEY_RD to re-activate the read requests."],"env":"PBCORE","seeAlso":["POP_KEY_RD"]},"READ_DICT":{"kind":"procedure","purpose":"Reads information from a dictionary.","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the name of the dictionary from which to read."},{"name":"element_no","dir":"in","type":"INTEGER","text":"element_no specifies the element number to read. This element number is designated with a $ in the dictionary file."},{"name":"ksta","dir":"out","type":"ARRAY OF STRING","text":"ksta is a KAREL STRING ARRAY used to store the information being read from the dictionary text file."},{"name":"first_line","dir":"in","type":"INTEGER","text":"first_line indicates the array element of ksta, at which to begin storing the information."},{"name":"last_line","dir":"out","type":"INTEGER","text":"last_line returns a value indicating the last element used in the ksta array."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred reading the element from the dictionary file."}],"notes":["If ksta is too small to store all the data, then the data is truncated and status is set to 33008, \"Dictionary Element Truncated.\"","&new_line is the only reserved attribute code that can be read from dictionary text files using READ_DICT. The READ_DICT Built-In ignores all other reserved attribute codes."],"env":"PBCORE","seeAlso":["REMOVE_DICT"]},"READ_DICT_V":{"kind":"procedure","purpose":"Reads information from a dictionary with formatted variables.","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the name of the dictionary from which to read."},{"name":"element_no","dir":"in","type":"INTEGER","text":"element_no specifies the element number to read. This number is designated with a $ in the dictionary file."},{"name":"value_array","dir":"in","type":"ARRAY OF STRING","text":"value_array is an array of variable names that corresponds to each formatted data item in the dictionary text. Each variable name can be specified as '[prog_name]var_name'. — [prog_name] specifies the name of the program that contains the specified variable. If not specified, then the current program being executed is used. — var_name must refer to a static variable. — var_name may contain node numbers, field names, and/or subscripts."},{"name":"ksta","dir":"out","type":"ARRAY OF STRING","text":"ksta is a KAREL STRING ARRAY used to store the information that is being read from the dictionary text file."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred reading the element from the dictionary file."}],"notes":["If ksta is too small to store all the data, then the data is truncated and status is set to 33008, \"Dictionary Element Truncated.\"","&new_line is the only reserved attribute code that can be read from dictionary text files using READ_DICT_V. The READ_DICT_V Built-In ignores all other reserved attribute codes."],"env":"UIF","seeAlso":["WRITE_DICT_V"]},"READ_KB":{"kind":"procedure","purpose":"Read from a keyboard device and wait for completion.","params":[{"name":"file_var","dir":"in","type":"FILE","text":"file_var must be open to a keyboard-device. If file_var is also associated with a window, the characters are echoed to the window."},{"name":"buffer","dir":"out","type":"STRING","text":"n_chars_got is set to the number of characters in the input buffer when the read is terminated."},{"name":"buffer_size","dir":"in","type":"INTEGER","text":"The characters are stored in buffer, up to a maximum of buffer_size or the size of the string, whichever is smaller."},{"name":"accept_mask","dir":"in","type":"INTEGER","text":"accept_mask is a bit-wise mask indicating the classes of characters that will be accepted as input. This should be an OR of the constants defined in the include file klevkmsk.kl. kc_display:Displayable keys kc_func_key:Function keys kc_keypad:Key-pad and Edit keys kc_enter_key:Enter and Return keys kc_delete:Delete and Backspace keys kc_lr_arw:Left and Right Arrow keys kc_ud_arw:Up and Down Arrow keys kc_other:Other keys (such as Prev)"},{"name":"time_out","dir":"in","type":"INTEGER","text":"time_out specifies the time, in milliseconds, after which the input operation will be automatically canceled. A value of -1 implies no timeout."},{"name":"term_mask","dir":"in","type":"INTEGER","text":"term_mask is a bit-wise mask indicating conditions which will terminate the request. This should be an OR of the constants defined in the include file klevkmsk.kl. kc_display:Displayable keys kc_func_key:Function keys kc_keypad:Key-pad and Edit keys kc_enter_key:Enter and Return keys kc_delete:Delete and Backspace keys kc_lr_arw:Left and Right Arrow keys kc_ud_arw:Up and Down Arrow keys kc_other:Other keys (such as Prev)"},{"name":"init_data","dir":"in","type":"STRING","text":""},{"name":"n_chars_got","dir":"out","type":"INTEGER","text":"n_chars_got is set to the number of characters in the input buffer when the read is terminated."}],"notes":["Causes data from specified classes of characters to be stored in a user-supplied buffer until a termination condition is met or the buffer is full. Returns to the caller when the read is terminated.","If you use READ_KB for the CRT/KB, you will get \"raw\" CRT characters returned. To get teach pendant equivalent key codes, you must perform the following function: tp_key = $CRT_KEY_TBL[crt_key + 1] This mapping allows you to use common software between the CRT/KB and teach pendant devices.","READ_KB and some other utilities use a variable in your KAREL program called device_stat to establish the association between the KAREL program and user interface display. For example, if you have a task [MAINUIF] which calls READ_KB, the variable which is used to make the association is [MAINUIF]device_stat. If you do not set device_stat, then you can only read characters in single screen mode, or in the left pane.","device_stat must be set to the paneID in which your application is running. For the standard single mode/monochrome pendant, device_stat =1. To interact in the right pane, set device_stat=2. To interact in the lower right pane, set device_stat=3. External Internet Explorer connections use panes 4-9. For the CRT/KB, set device_stat=255.","[MAINUIF]device_stat must be set to the correct pane ID before you open the keyboard file that is assoicated with READ_KB. The pane ID for the iPendant can be either 1, 2 or 3.","The application running in Pane ID 1 is stored in $TP_CURSCRN. Pane ID 2 is stored in $UI_CURSCRN[1], or in general $UI_CURSCRN[device_stat-1]. The CRT applicaton uses $CT_CURSCRN.","It is reasonable for accept_mask to be zero; this means that no characters are accepted as input. This is used when waiting for a single key that will be returned as the term_char. In this case, buffer_size would be zero.","If accept_mask includes displayable characters, the following characters, if accepted, have the following meanings: — Delete characters - If the cursor is not in the first position of the field, the character to the left of the cursor is deleted. — Left and right arrows - Position the cursor one character to the left or right from its present position, assuming it is not already in the first or last position already. — Up and down arrows - Fetch input previously entered in reads to the same file.","init_data_p points to a string which is displayed as the initial value of the input field. This must not be longer than buffer_size.","term_char receives a code indicating the character or other condition that terminated the form. The codes for key terminating conditions are defined in the include file klevkeys.kl. Keys normally returned are pre-defined constants as follows: ky_up_arw ky_dn_arw ky_rt_arw ky_lf_arw ky_enter ky_prev ky_f1 ky_f2 ky_f3 ky_f4 ky_f5 ky_next","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"PBCORE"},"REMOVE_DICT":{"kind":"procedure","purpose":"Removes the specified dictionary from the specified language or from all existing languages.","params":[{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the name of the dictionary to remove."},{"name":"lang_name","dir":"in","type":"STRING","text":"lang_name specifies which language the dictionary should be removed from. One of the following pre-defined constants should be used: dp_default dp_english dp_japanese dp_french dp_german dp_spanish If lang_name is '', it will be removed from all languages in which it exists."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred removing the dictionary file."}],"env":"UIF","seeAlso":["ADD_DICT"]},"RENAME_FILE":{"kind":"procedure","purpose":"Renames the specified file name.","params":[{"name":"old_file","dir":"in","type":"STRING","text":"old_file specifies the device, name, and type of the file to rename."},{"name":"new_file","dir":"in","type":"STRING","text":"new_file specifies the name and type of the file to rename to."},{"name":"nowait_sw","dir":"in","type":"BOOLEAN","text":"If nowait_sw is TRUE, execution of the program continues while the command is executing. If it is FALSE, the program stops, including condition handlers, until the operation has completed. If you have time critical condition handlers in your program, put them in another program that executes as a separate task. Note nowait_sw is not available in this release and should be set to FALSE."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"FDEV","seeAlso":["DELETE_FILE"]},"RENAME_VAR":{"kind":"procedure","purpose":"Renames a specified variable in a specified program to a new variable name.","params":[{"name":"prog_nam","dir":"in","type":"STRING","text":"prog_nam is the name of the program that contains the variable to be renamed."},{"name":"old_nam","dir":"in","type":"STRING","text":"old_nam is the current name of the variable."},{"name":"new_nam","dir":"in","type":"STRING","text":"new_nam is the new name of the variable."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"MEMO","seeAlso":["SET_VAR"]},"RENAME_VARS":{"kind":"procedure","purpose":"Renames all of the variables in a specified program to a new program name.","params":[{"name":"old_nam","dir":"in","type":"STRING","text":"old_nam is the current name of the program."},{"name":"new_nam","dir":"in","type":"STRING","text":"new_nam is the new name of the program."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"MEMO"},"RESET":{"kind":"procedure","purpose":"Resets the controller.","params":[{"name":"successful","dir":"out","type":"BOOLEAN","text":"successful will be TRUE even if conditions exist which prevent resetting the controller."}],"notes":["To determine whether the reset operation was successful, delay 1 second and check OPOUT[3] (FAULT LED). If this is FALSE, the reset operation was successful.","The statement following the RESET Built-In is not executed until the reset fails or has completed. The status display on the CRT or teach pendant will indicate PAUSED during the reset.","The controller appears to be in a PAUSED state while a reset is in progress but, during this time, PAUSE condition handlers will not be triggered."],"env":"MOTN"},"RGET_PORTCMT":{"kind":"procedure","purpose":"In V7.70 and later, to allow a KAREL program to determine a comment that is set for a specified logical port of a remote host.","params":[{"name":"host_port","dir":"in","type":"STRING","text":"host_port is an IP address or host name of remote robot controller."},{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port whose comment is returned. Codes are defined in kliotyps.kl."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number whose comment is being returned."},{"name":"comment_str","dir":"out","type":"INTEGER","text":"comment_str is returned with the comment for the specified port. This should be declared as a STRING with a length of at least 16 characters. Only 16 characters are returned even if the server’s comment is longer."},{"name":"status","dir":"out","type":"INTEGER","text":""}],"env":"RPCC"},"RGET_PORTSIM":{"kind":"procedure","purpose":"In V7.70 and later, to get port simulation status from the remote controller.","notes":["host_port is an IP address or host name of the remote robot controller.","port_type specifies the code for the type of port whose simulation status is returned. Codes are defined in kliotyps.kl.","port_no specifies the port number whose simulation status is being returned.","simulated returns TRUE if the port is being simulated, FALSE otherwise.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RGET_PORTVAL":{"kind":"procedure","purpose":"In V7.70 and later, to allow a KAREL program to determine the current value of a specified logical port of a remote host.","notes":["host_port is an IP address or host name of a remote robot controller.","port_type specifies the code of a port whose value is being returned. Codes are defined in kliotyps.kl.","port_no specifies the port number whose value is returned.","value is returned with the current value (status) of the specified port. For BOOLEAN port types (DIN for example), this will be 0 = OFF, or 1 = ON.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RGET_PREGCMT":{"kind":"procedure","purpose":"In V7.70 and later, to retrieve a comment of a position register of remote host.","notes":["host_port is an IP address or host name of a remote robot controller.","register_no specifies from which position register to retrieve the comment. The comment of the given position register is returned in parameter comment_str.","comment_str should be declared as a STRING with a length of at least 16 characters.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RGET_REG":{"kind":"procedure","purpose":"In V7.70 and later, to get an INTEGER or REAL value from the specified register of remote host.","notes":["host_port is the IP address or host name of remote robot controller.","register_no specifies which position register to retrieve the comment from. The comment of the given position register is returned in parametercomment_str.","real_flag is set to TRUE and real_value is set to the register content if the specified register has a real value. Otherwise, real_flag is set to FALSE and int_value is set to the contents of the register.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RGET_REG_CMT":{"kind":"procedure","purpose":"In V7.70 and later, to get comment from the specified register of a remote host.","notes":["host_port is an IP address or host name of a remote robot controller.","register_no specifies from which register to retrieve the comment. The comment of the given register is returned in comment_str.","comment_str should be declared as a STRING with a length of at least 16 characters.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RGET_SREGCMT":{"kind":"procedure","purpose":"In V7.70 and later, to get comment from the specified string register of a remote host.","notes":["host_port isan IP address or host name of a remote robot controller.","register_no specifies from which string register to retrieve the comment.","comment_str contains the comment of the specified string register.","comment_str should be declared as a STRING with a length of at least 16 characters.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RGET_STR_REG":{"kind":"procedure","purpose":"In V7.70 and later, to get a value from the specified string register of a remote host.","notes":["host_port is an IP address or host name of a remote robot controller.","register_no specifies the string register to get.","value contains the value of the specified string register.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RMCN_ALERT":{"kind":"procedure","purpose":"Sends an alert to the phone so that the user is immediately notified without requiring the iRConnect mobile application to be active. (available in v8.20 and later).","notes":["alertaddr is an SMS gateway E-mail address which arrives as a text message on a phone. It can carry multiple Email addresses separated by semicolon (;). If '', then the alert address shown in the iRConnect Emails screen will be used.","subject is the subject for the alert. If '', then 'iRConnect Alert' is used.","message is a short message to show in the text message. If '', then only the link is shown.","alerturl is the link that shows in the text message. When clicked, it will activate the iRConnect mobile application on the phone. If '', then the default link is shown."],"env":"PBCORE"},"RMCN_SEND":{"kind":"procedure","purpose":"Sends user defined message as an email via iRConnect (available in v8.10 and v830P/14 or earlier).","notes":["xml_file is a message file in XML format. This file is read and deleted when the message is queued so the same filename can be reused if RMCN_SEND is called multiple times.","attachments is an array of attachment files. Attachment files are optional. These files are read and deleted when the email is sent. Therefore, they may remain in the queue for quite some time. Unique filenames should be used if RMCN_SEND is called multiple times during a queue period, or you can check if the file has been deleted to know when it was sent. Attachment files using the MD: device are not deleted. They will always contain the most current information when they are sent.","priority is a flag (0 or 1) that enables email to be sent now or at the next update.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"PBCORE"},"RNUMREG_RECV":{"kind":"procedure","purpose":"In V7.70 and later, to transfer a server’s register to a client’s register.","notes":["host_port is an IP address or host name of a remote robot controller.","src_idx specifies an index of a register of server.","dest_idx specifies an index of register of client. Acquired data is stored in this register.","option specifies function of this built-in. Parameter Values Value Description 0 Value and comment are received. 1 Value is received. 2 Comment is received.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RNUMREG_SEND":{"kind":"procedure","purpose":"In V7.70 and later, to transfer a client’s register to a server’s register.","notes":["host_port is an IP address or host name of a remote robot controller.","dest_idx specifies an index of register of server.","src_idx specifies an index of register of client. Data of this register is sent to client’s server.","option specifies function of this built-in. Parameter Values Value Description 0 Value and comment is set. 1 Value is set. 2 Comment is set.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"ROUND":{"kind":"function","purpose":"Returns the INTEGER value closest to the specified REAL argument.","returns":"INTEGER","params":[{"name":"x","dir":"in","type":"REAL","text":"x must be in the range of -2147483648 to +2147483646. Otherwise, the program will be aborted with an error."}],"notes":["The returned value is the INTEGER value closest to the REAL value x, as demonstrated by the following rules: — If x >= 0, let n be a positive INTEGER such that n <= x <= n + 1 — If x >= n + 0.5, then n + 1 is returned; otherwise, n is returned. — If x <= 0, let n be a negative INTEGER such that n >= x >= n - 1 — If x <= n - 0.5, then n - 1 is returned; otherwise, n is returned."],"env":"SYSTEM","seeAlso":["TRUNC"]},"RPREG_RECV":{"kind":"procedure","purpose":"In V7.70 and later, to transfer position register of specified group of server to position register of specified group of client.","notes":["host_port is IP address or host name of remote robot controller.","src_idx specifies index of position register or server.","src_grp specifies group number of server. Position data of specified group is transferred.","dest_idx specifies index of position register of client. The specified position register stores acquired data.","dest_grp specifies group number of client. Position data of specified group of PR [“dest_idx”] is changed to received data.","option explains the status of the attempted operation. If not equal to 0, then an error occurred. Parameter Values Value Description 0 Position data and comment are got. 1 Position data is got.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RPREG_SEND":{"kind":"procedure","purpose":"In V7.70 and later, to transfer position register of specified group of client to position register of specified group of server.","notes":["host_port is IP address or host name of remote robot controller.","dest_idx specifies index of position register of server.","dest_grp specifies group number of server. Position data of specified group is changed by sent data from client.","src_idx specifies index of position register of client. Position data of src_grp of PR [src_idx] is sent to server.","src_grp specifies group number of client.","option specifies function of this built-in. Parameter Values VALUE DESCRIPTION 0 Position data and comment are set. 1 Position data is set.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_INT_REG":{"kind":"procedure","purpose":"In V7.70 and later, to store an in INTEGER value in the specified register of remote host.","notes":["host_port is IP address or host name of remote robot controller.","register_no specifies the register into which “int_value” will be stored.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_PORTCMT":{"kind":"procedure","purpose":"In V7.70 and later, to allow a KAREL program to set comment of specified logical port of remote host.","notes":["host_port is IP address or host name of remote robot controller.","port_type specifies the code of port whose comment is being set. Codes are defined in kliotyps.kl.","port_no specifies the port number whose comment is being set.","comment_str is a string whose value is the comment for the specified port. This must not be over 16 characters long.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_PORTSIM":{"kind":"procedure","purpose":"In V7.70 and later, to set port simulated on remote host.","notes":["host_port is IP address or host name of remote robot controller.","port_type specifies the code for the type of port to be simulated. Codes are defined in kliotyps.kl","port_no specifies port number to be simulated.","value specifies the initial value to set.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_PORTVAL":{"kind":"procedure","purpose":"In V7.70 and later, to allow KAREL program to set a specified output (or simulated input) for a specified logical port.","notes":["host_port is IP address or host name of remote robot controller.","port_type specifies the code of port whose value is being set. Codes are defined in kliotyps.kl","port_no specifies the port number whose value is being set.","value indicates the value to be assigned to a specified port. If the port_type is BOOLEAN (DOUT for example), this should be 0 = OFF, or 1 = ON. This field can be used to set input ports if the port is simulated. -","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_PREGCMT":{"kind":"procedure","purpose":"In V7.70 and later, to set comment of a position register of remote host.","notes":["host_port is IP address or host name of remote robot controller.","register_no specifies position register of remote robot controller.","comment_str is comment to be set. If “comment_str” exceeds 16 characters, it is truncated.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_REALREG":{"kind":"procedure","purpose":"In V7.70 and later, to store a REAL value in the specified register of remote host.","notes":["host_port is IP address or host name of remote robot controller.","register_no specifies the register into which real_value will be stored.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_REG_CMT":{"kind":"procedure","purpose":"In V7.70 and later, to set comment of numeric register of remote host.","notes":["host_port is IP address or host name of remote robot controller.","register_no specifies which register to set the comments to.","comment_str represents the data which is to be used to set the comment of the given register. If “comment_str” exceeds more than 16 characters, the built-in will truncate the string.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_SREGCMT":{"kind":"procedure","purpose":"In V7.70 and later, sets the comment for the specified string register of the remote robot controller.","notes":["host_port is IP address or host name of remote robot controller.","register_no specifies string register to set","comment_str contains the comment to set to the specified string register. If the comment_str exceeds more than 16 characters, the built-in will truncate the string","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RSET_STR_REG":{"kind":"procedure","purpose":"In V7.70 and later, to set the specified value for the specified string register of the remote host.","notes":["host_port is IP address or host name of remote robot controller.","register_no specifies string register to set","value contains the value to set to the specified string register.","status explains the status of the attempted operation. If not equal to 0, then an error occurred."],"env":"RPCC"},"RUN_TASK":{"kind":"procedure","purpose":"Runs the specified program as a child task.","params":[{"name":"task_name","dir":"in","type":"STRING","text":"task_name is the name of the task to be run. This creates a child task. The task that executes this built-in is called the parent task."},{"name":"line_number","dir":"in","type":"INTEGER","text":"line_number specifies the line from which execution starts. Use 0 to start from the beginning of the program. This is only valid for teach pendant programs."},{"name":"pause_on_sft","dir":"in","type":"BOOLEAN","text":"If pause_on_sft is TRUE, the task is paused when the teach pendant shift key is released."},{"name":"tp_motion","dir":"in","type":"BOOLEAN","text":"If tp_motion is TRUE, the task can execute motion while the teach pendant is enabled. The TP must be enabled if tp_motion is TRUE."},{"name":"lock_mask","dir":"in","type":"INTEGER","text":"The control of the motion groups specified in lock_mask will be transferred from parent task to child task, if tp_motion is TRUE and the teach pendant is enabled. The group numbers must be in the range of 1 to the total number of groups defined on the controller. Bit 1 specifies group 1, bit 2 specifies group 2, and so forth. Group_mask setting GROUP DECIMAL BIT Group 1 1 1 Group 2 2 2 Group 3 4 3 To specify multiple groups select the decimal values which correspond to the desired groups. Then connect them together using the OR operator. For example to specify groups 1 and 3, enter \"1 OR 4\"."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If the task already exists and is paused, it will be continued. A new task is not created."],"env":"MULTI","seeAlso":["ABORT_TASK"]},"SAVE":{"kind":"procedure","purpose":"Saves the program or variables into the specified file","params":[{"name":"prog_nam","dir":"in","type":"STRING","text":"prog_nam specifies the program name. If program name is '*', all programs or variables of the specified type are saved. prog_name must be set to \"*SYSTEM*\" in order to save all system variables."},{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the device, name, and type of the file being saved to. The type also implies whether programs or variables are being saved. The following types are valid:.TP: Teach pendant program.VR: KAREL variables.SV: KAREL system variables.IO: I/O configuration data"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["If file_spec already exists on the specified device, then an error is returned the save does not occur."],"env":"MEMO","seeAlso":["LOAD"]},"SAVE_DRAM":{"kind":"procedure","purpose":"Saves the RAM variable content to FlashROM.","params":[{"name":"prog_nam","dir":"in","type":"STRING","text":"prog_nam specifies the program name. This operation will save the current values of any variables in DRAM to FlashROM for the specified program. At power up these saved values will automatically be loaded into DRAM."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"MEMO"},"SELECT_TPE":{"kind":"procedure","purpose":"Selects the program of the specified name","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the program to be selected as the teach pendant default. This is the program that is \"in use\" by the teach pendant. It is also the program that will be executed if the CYCLE START button is pressed or the teach pendant FWD key is pressed."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If it is not equal to 0, then an error has occurred."}],"env":"TPE","seeAlso":["OPEN_TPE"]},"SEMA_COUNT":{"kind":"function","purpose":"Returns the current value of the specified semaphore","returns":"INTEGER","params":[{"name":"semaphore_no","dir":"in","type":"INTEGER","text":"The value of the semaphore indicated by semaphore_no is returned."}],"notes":["This value is incremented by every POST_SEMA call and SIGNAL SEMAPHORE Action specifying the same semaphore_no. It is decremented by every PEND_SEMA call.","If SEMA_COUNT is greater than zero, a PEND_SEMA call will \"fall through\" immediately. If it is -n (minus n), then there are n tasks pending on this semaphore."],"env":"MULTI","seeAlso":["CLEAR_SEMA"]},"SEND_DATAPC":{"kind":"procedure","purpose":"To send an event message and other data to the PC.","params":[{"name":"event_no","dir":"in","type":"INTEGER","text":"event_no - a GEMM event number. Valid values are 0 to 255."},{"name":"dat_buffer","dir":"in","type":"ARRAY OF BYTE","text":"dat_buffer - an array of up to 244 bytes. The KAREL built-ins ADD_BYNAMEPC, ADD_INTPC, ADD_REALPC, and ADD_STRINGPC can be used to format a KAREL byte buffer. The actual data buffer format depends on the needs of the PC. There is no error checking of the dat_buffer format on the controller."},{"name":"status","dir":"out","type":"INTEGER","text":"status - the status of the attempted operation. If not 0, then an error occurred and the event request was not sent to the PC."}],"env":"PC"},"SEND_EVENTPC":{"kind":"procedure","purpose":"To send an event message to the PC.","params":[{"name":"event_no","dir":"in","type":"INTEGER","text":"event_no - a GEMM event number. Valid values are 0 through 255."},{"name":"status","dir":"out","type":"INTEGER","text":"status - the status of the attempted operation. If not 0, then an error occurred and the event request was not sent to the PC."}],"env":"PC"},"SET_ATTR_PRG":{"kind":"procedure","purpose":"Sets attribute data of the specified teach pendant or KAREL program","params":[{"name":"program_name","dir":"in","type":"STRING","text":"program_name specifies the program to which attribute data is set."},{"name":"attr_number","dir":"in","type":"INTEGER","text":"attr_number is the attribute whose value is to be set. The following attributes are valid: AT_PROG_TYPE: (#) Program type AT_PROG_NAME: Program name (String[12]) AT_OWNER: Owner (String[8]) AT_COMMENT: Comment (String[16]) AT_PROG_SIZE: (#) Size of program AT_ALLC_SIZE: (#) Size of allocated memory AT_NUM_LINE: (#) Number of lines AT_CRE_TIME: (#) Created (loaded) time AT_MDFY_TIME: (#) Modified time AT_SRC_NAME: Source file (or original file) name (String[128]) AT_SRC_VRSN: Source file version AT_DEF_GROUP: Default motion groups (for task attribute) AT_PROTECT: Protection code; 1:protection OFF; 2: protection ON AT_STORAGE: Storage type; TPSTOR_CMOS; TPSTOR_SHADOW; TPSTOR_FILE; TPSTOR_SHOD AT_STK_SIZE: Stack size (for task attribute) AT_TASK_PRI: Task priority (for task attribute) AT_DURATION: Time slice duration (for task attribute) AT_BUSY_OFF: Busy lamp off (for task attribute) AT_IGNR_ABRT: Ignore abort request (for task attribute) AT_IGNR_PAUS: Ignore pause request (for task attribute) AT_CONTROL: Control code (for task attribute) (#) — Cannot be set."},{"name":"int_value","dir":"in","type":"INTEGER","text":"If the attribute data is a number, it is set to int_value and string_value is ignored."},{"name":"string_value","dir":"in","type":"STRING","text":"If the attribute data is a number, it is set to int_value and string_value is ignored."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If it is not equal to 0, then an error has occurred. Some of the errors which could occur are: 7073 The program specified in program_name does not exist 7093 The attribute of a program cannot be set while it is running 17033 attr_number has an illegal value or cannot be set"}],"notes":["If the attribute data is a string, it is set to string_value and int_value is ignored."],"env":"TPE"},"SET_CURSOR":{"kind":"procedure","purpose":"Set the cursor position in the window","params":[{"name":"file_var","dir":"in","type":"FILE","text":"file_var must be open to a window."},{"name":"row","dir":"in","type":"INTEGER","text":"A row value of 1 indicates the top row of the window. A col value of 1 indicates the left-most column of the window."},{"name":"col","dir":"in","type":"INTEGER","text":"A row value of 1 indicates the top row of the window. A col value of 1 indicates the left-most column of the window."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Sets the current cursor of the specified file that is open to a window so subsequent writes will start in the specified position."],"env":"PBCORE","seeAlso":["DEF_WINDOW"]},"SET_EPOS_REG":{"kind":"procedure","purpose":"Stores an XYZWPREXT value in the specified register","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the position register in which to store the value."},{"name":"posn","dir":"in","type":"XYZWPREXT","text":""},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If it is not equal to 0, then an error occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed. Data for other groups is not changed.","optional":true}],"notes":["The position data is set in XYZWPREXT representation.","If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"REGOPE","seeAlso":["SET_JPOS_REG","GET_JPOS_REG"]},"SET_EPOS_TPE":{"kind":"procedure","purpose":"Stores an XYZWPREXT value in the specified position in the specified teach pendant program","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. A program must be opened before calling this built-in."},{"name":"position_no","dir":"in","type":"INTEGER","text":"position_no specifies the position in the program in which to store the value."},{"name":"posn","dir":"in","type":"XYZWPREXT","text":""},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed. Data for other groups is not changed.","optional":true}],"notes":["A motion instruction must already exist that uses the position_no or the position will not be used by the teach pendant program.","The position data is set in XYZWPREXT representation with no conversion.","If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"PBCORE"},"SET_FILE_ATR":{"kind":"procedure","purpose":"Sets the attributes of a file before it is opened","params":[{"name":"file_id","dir":"in","type":"FILE","text":"file_id is the file variable that will be used in the OPEN FILE, WRITE, READ, and/or CLOSE FILE statements."},{"name":"atr_type","dir":"in","type":"INTEGER","text":"atr_type specifies the attribute type to set. The predefined constants as specified should be used."},{"name":"atr_value","dir":"in","type":"INTEGER","text":"atr_value is optional depending on the attribute type being set.","optional":true}],"env":"PBCORE"},"SET_FILE_POS":{"kind":"procedure","purpose":"Sets the file position for the next READ or WRITE operation to take place in the specified file to the value of the new specified file position","params":[{"name":"file_id","dir":"in","type":"FILE","text":"The file associated with file_id must be opened and uncompressed on either the FROM or RAM disks. Otherwise, the program is aborted with an error."},{"name":"new_file_pos","dir":"in","type":"INTEGER","text":"new_file_pos must be in the range of -1 to the number of bytes in the file.at_eof: specifies that the file position is to be set at the end of the file. at_sof: specifies that the file position is to be set at the start of the file. — Any other value causes the file to be set the specified number of bytes from the beginning of the file."},{"name":"status","dir":"out","type":"INTEGER","text":"status is set to 0 if the new_file_pos is between -1 and the number of bytes in the file, indicating the file position was successfully set. If not equal to 0, then an error occurred."}],"env":"FLBT"},"SET_INT_REG":{"kind":"procedure","purpose":"Stores an integer value in the specified register","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the register into which int_value will be stored."},{"name":"int_value","dir":"in","type":"INTEGER","text":"register_no specifies the register into which int_value will be stored."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"REGOPE","seeAlso":["SET_REAL_REG"]},"SET_JPOS_REG":{"kind":"procedure","purpose":"Stores a JOINTPOS value in the specified register","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the position register in which to store the position, jpos."},{"name":"jpos","dir":"in","type":"JOINTPOS","text":"register_no specifies the position register in which to store the position, jpos."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed. Data for other groups is not changed.","optional":true}],"notes":["The position data is set in JOINTPOS representation with no conversion.","If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"REGOPE","seeAlso":["POS_REG_TYPE"]},"SET_JPOS_TPE":{"kind":"procedure","purpose":"Stores a JOINTPOS value in the specified position in the specified teach pendant program","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. Before calling this built-in, a program must be opened using the OPEN_TPE Built-In, and have read/write access."},{"name":"position_no","dir":"in","type":"INTEGER","text":"position_no specifies the position in the program in which to store the value."},{"name":"posn","dir":"in","type":"JOINTPOS","text":""},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed. Data for other groups is not changed.","optional":true}],"notes":["The position data is set in JOINTPOS representation with no conversion.","If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"PBCORE","seeAlso":["GET_POS_TYP"]},"SET_LANG":{"kind":"procedure","purpose":"Changes the current language","params":[{"name":"lang_name","dir":"in","type":"STRING","text":"lang_name specifies which language from which the dictionaries should be read/written. Use one of the following pre-defined constants: dp_default dp_english dp_japanese dp_french dp_german dp_spanish"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred setting the language."}],"notes":["The read-only system variable $LANGUAGE indicates which language is currently in use.","The error, 33003, \"No dict found for language,\" will be returned if no dictionaries are loaded into the specified language. The KCL command \"SHOW LANGS\" can be used to view which languages are created in the system."],"env":"PBCORE"},"SET_PERCH":{"kind":"procedure","purpose":"Sets the perch position and tolerance for a group of axes","params":[{"name":"jpos","dir":"in","type":"JOINTPOS","text":"The values of jpos are converted to radians and stored in the system variable $REFPOS1[ indx ].$perch_pos."},{"name":"tolerance","dir":"in","type":"ARRAY[6] OF REAL","text":"The tolerance array is converted to degrees and stored in the system variable $REFPOS1[ indx ].$perchtol. If the tolerance array is uninitialized, an error is generated."},{"name":"indx","dir":"in","type":"INTEGER","text":"indx specifies the element number to be set in the $REFPOS1 array."}],"notes":["The group of axes is implied from the specified position, jpos. If JOINTPOS is not in group 1, then the system variable $REFPOSn is used where n corresponds to the group number of jpos and indx must beset to 1."],"env":"SYSTEM"},"SET_PORT_ASG":{"kind":"procedure","purpose":"Allows a KAREL program to assign one or more logical ports to specified physical port(s)","params":[{"name":"log_port_type","dir":"in","type":"INTEGER","text":"log_port_type specifies the code for the type of port to be assigned. Codes are defined in KLIOTYPS.KL."},{"name":"log_port_no","dir":"in","type":"INTEGER","text":"log_port_no specifies the number of the port to be assigned."},{"name":"rack_no","dir":"in","type":"INTEGER","text":"rack_no is the rack containing the port module. For process I/O boards, memory-image, and dummy ports, this is zero; for Allen-Bradley and Genius ports, this is 16."},{"name":"slot_no","dir":"in","type":"INTEGER","text":"slot_no is the slot containing the port module. For process I/O boards, this is the sequence in the SLC-2 chain. For memory-image and dummy ports, this is zero; for Allen-Bradley and Genius ports, this is 1."},{"name":"phy_port_type","dir":"in","type":"INTEGER","text":"phy_port_type is the type of port to be assigned to. Often this will be the same as log_port_type. Exceptions are if log_port_type is a group type (io_gpin or io_gpout) or a port is assigned to memory-image or dummy ports."},{"name":"phy_port_no","dir":"in","type":"INTEGER","text":"phy_port_no is the number of the port to be assigned to. If log_port_type is a group, this is the port number for the least-significant bit of the group."},{"name":"n_ports","dir":"in","type":"INTEGER","text":"n_ports is the number of physical ports to be assigned to the logical port. If log_port_type is a group type, n_ports indicates the number of bits in the group. When setting digital I/O, n_ports is the number of points you are configuring. In most cases this will be 8, but may be 1 through 8."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid. Otherwise, it is returned with an error code. The assignment is invalid if the specified port(s) do not exist or if the assignment of log_port_type to phy_port_type is not permitted. For example, GINs cannot be assigned to DOUTs. Neither log_port_type nor phy_port_type can be a system port type (SOPIN, for example). Note The assignment does not take effect until the next power-up."}],"env":"IOSETUP"},"SET_PORT_ATR":{"kind":"function","purpose":"Sets the attributes of a port","returns":"INTEGER","params":[{"name":"port_id","dir":"in","type":"INTEGER","text":"port_id is one of the predefined constants as follows: port_1 port_2 port_3 port_4"},{"name":"atr_type","dir":"in","type":"INTEGER","text":"atr_type specifies the attribute type to set. One of the following predefined constants should be used: atr_readahd:Read ahead buffer atr_baud:Baud rate atr_parity:Parity atr_sbits:Stop bits atr_dbits:Data length atr_xonoff:XON/XOFF atr_eol:End of line atr_modem:Modem line"},{"name":"atr_value","dir":"in","type":"INTEGER","text":"atr_value specifies the value for the attribute type. Attribute Values ATR_TYPE ATR_VALUE atr_readahd any integer, represents multiples of 128 bytes (for example: atr_value=1 means the buffer length is 128 bytes. atr_baud baud_9600 baud_4800 baud_2400 baud_1200 atr_parity parity_none parity_even parity_odd Attribute Values (Cont'd) ATR_TYPE ATR_VALUE atr_sbits sbits_1 sbits_15 sbits_2 atr_dbits dbits_5 dbits_6 dbits_7 dbits_8 atr_xonoff xf_not_used xf_used atr_eol an ASCII code value,"}],"notes":["A returned integer is the status of this action to port."],"env":"FLBT","seeAlso":["SET_FILE_ATR"]},"SET_PORT_CMT":{"kind":"procedure","purpose":"Allows a KAREL program to set the comment displayed on the teach pendant, for a specified logical port","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port whose mode is being set. Codes are defined in KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number whose mode is being set."},{"name":"comment_str","dir":"in","type":"STRING","text":"comment_str is a string whose value is the comment for the specified port. This must not be over 16 characters long."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid and the specified mode can be set for the specified port."}],"env":"IOSETUP","seeAlso":["GET_PORT_MOD"]},"SET_PORT_MOD":{"kind":"procedure","purpose":"Allows a KAREL program to set (or reset) special port modes for a specified logical port","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port whose mode is being set. Codes are defined in KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number whose mode is being set."},{"name":"mode_mask","dir":"in","type":"INTEGER","text":"mode_mask is a mask specifying which modes are turned on. The following modes are defined: 1:reverse mode - sense of the port is reversed; if the port is set to TRUE, the physical output is set toFALSE. If the port is set to FALSE, the physical output is set to TRUE. If a physical input is TRUE when the port is read, FALSE is returned. If a physical input is FALSE when the port is read, TRUE is returned.ports. 2:complementary mode - the logical port is assigned to two physical ports whose values are complementary. In this case, port_no must be an odd number. If port n is set to TRUE, port n is set to TRUE, and port n + 1 is set to FALSE. If port n is set to FALSE, port n is set to FALSE and port n + 1 is set to TRUE. This is effective only for output Note The mode setting does not take effect until the next power-up."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid and the specified mode can be set for the specified port."}],"env":"IOSETUP"},"SET_PORT_SIM":{"kind":"procedure","purpose":"Sets port simulated","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port to simulate. Codes are defined in KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the number of the port to simulate."},{"name":"value","dir":"in","type":"INTEGER","text":"value specifies the initial value to set."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the port is simulated."}],"env":"IOSETUP","seeAlso":["GET_PORT_SIM"]},"SET_PORT_VAL":{"kind":"procedure","purpose":"Allows a KAREL program to set a specified output (or simulated input) for a specified logical port","params":[{"name":"port_type","dir":"in","type":"INTEGER","text":"port_type specifies the code for the type of port whose mode is being set. Codes are defined in KLIOTYPS.KL."},{"name":"port_no","dir":"in","type":"INTEGER","text":"port_no specifies the port number whose mode is being set."},{"name":"value","dir":"in","type":"INTEGER","text":"value indicates the value to be assigned to a specified port. If the port_type is BOOLEAN (i.e. DOUT), this should be 0 = OFF, or 1 = ON. This field can be used to set input ports if the port is simulated."},{"name":"status","dir":"out","type":"INTEGER","text":"status is returned with zero if the parameters are valid and the specified mode can be set for the specified port."}],"env":"IOSETUP","seeAlso":["GET_PORT_MOD"]},"SET_POS_REG":{"kind":"procedure","purpose":"Stores an XYZWPR value in the specified position register","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the position register in which to store the value."},{"name":"posn","dir":"in","type":"XYZWPR","text":""},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed. Data for other groups is not changed.","optional":true}],"notes":["The position data is set in XYZWPR representation with no conversion.","If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"REGOPE"},"SET_POS_TPE":{"kind":"procedure","purpose":"Stores an XYZWPR value in the specified position in the specified teach pendant program","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. Before calling this built-in, a program must be opened using the OPEN_TPE Built-In, and have read/write access."},{"name":"position_no","dir":"in","type":"INTEGER","text":"position_no specifies the position in the program in which to store the value."},{"name":"posn","dir":"in","type":"XYZWPR","text":""},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."},{"name":"group_no","dir":"in","type":"INTEGER","text":"If group_no is omitted, the default group for the program is assumed. Data for other groups is not changed.","optional":true}],"notes":["A motion instruction must already exist that uses the position_no or the position will not be used by the teach pendant program.","The position data is set in XYZWPR representation with no conversion.","If group_no is specified, it must be in the range of 1 to the total number of groups defined on the controller."],"env":"PBCORE"},"SET_PREG_CMT":{"kind":"procedure","purpose":"To set the comment information of a KAREL position register based on a given register number and a given comment.","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":""},{"name":"comment_string","dir":"in","type":"STRING","text":""},{"name":"status","dir":"out","type":"INTEGER","text":""}],"env":"REGOPE"},"SET_REAL_REG":{"kind":"procedure","purpose":"Stores a REAL value in the specified register","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the register into which real_value will be stored."},{"name":"real_value","dir":"in","type":"REAL","text":"register_no specifies the register into which real_value will be stored."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"REGOPE","seeAlso":["GET_INT_REG"]},"SET_REG_CMT":{"kind":"procedure","purpose":"To set the comment information of a KAREL register based on a given register number and a given comment.","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"Register_no specifies which register to retrieve the comments from. The comment_string represents the data which is to be used to set the comment of the given register. If the comment_string exceeds more than 16 characters, the built-in will truncate the string."},{"name":"comment_string","dir":"in","type":"STRING","text":"Register_no specifies which register to retrieve the comments from. The comment_string represents the data which is to be used to set the comment of the given register. If the comment_string exceeds more than 16 characters, the built-in will truncate the string."},{"name":"status","dir":"out","type":"INTEGER","text":""}],"env":"REGOPE"},"SET_SREG_CMT":{"kind":"procedure","purpose":"Sets the comment for the specified string register.","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the string register to get."},{"name":"comment","dir":"in","type":"STRING[254]","text":"comment contains the comment to set to the specified string register."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"REGOPE","seeAlso":["SET_STR_REG"]},"SET_STR_REG":{"kind":"procedure","purpose":"Sets the value for the specified string register.","params":[{"name":"register_no","dir":"in","type":"INTEGER","text":"register_no specifies the string register to get."},{"name":"value","dir":"in","type":"STRING[254]","text":"value contains the value to set to the specified string register."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"REGOPE","seeAlso":["SET_SREG_CMT"]},"SET_TIME":{"kind":"procedure","purpose":"Set the current time within the KAREL system","params":[{"name":"i","dir":"in","type":"INTEGER","text":"i holds the INTEGER representation of time within the KAREL system. This value is represented in 32-bit INTEGER format as follows: 32–Bit INTEGER Format of Time 31–25 24–21 20–16 year month day 32–Bit INTEGER Format of Time (Cont'd) 15–11 10–5 4–0 hour minute second"}],"notes":["The contents of the individual fields are as follows: — DATE: Bits 15-9 — Year since 1980 Bits 8-5 — Month (1-12) Bits 4-0 — Day of the month — TIME: Bits 31-25 — Number of hours (0-23) Bits 24-21 — Number of minutes (0-59) Bits 20-16 — Number of 2-second increments (0-29)","This value can be determined using the GET_TIME and CNV_STR_TIME Built-In procedures.","If i is 0, the time on the system will not be changed.","INTEGER values can be compared to determine if one time is more recent than another."],"env":"TIM","seeAlso":["GET_TIME"]},"SET_TPE_CMT":{"kind":"procedure","purpose":"Provides the ability for a KAREL program to set the comment associated with a specified position in a teach pendant program.","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the open_id returned from a previous call to OPEN_TPE. An open mode of TPE_RWACC must be used in the OPEN_TPE call."},{"name":"pos_no","dir":"in","type":"INTEGER","text":""},{"name":"comment","dir":"in","type":"STRING","text":"comment is the comment to be associated with the specified position. A zero length string can be used to ensure that a position has no comment. If the string is over 16 characters, it is truncated and used and a warning error is returned."},{"name":"status","dir":"out","type":"INTEGER","text":"status indicates zero if the operation was successful, otherwise an error code will be displayed."}],"notes":["pos_id specifies the number of the position in the teach pendant program to get a comment from. The specified position must have been recorded."],"env":"TPE","seeAlso":["OPEN_TPE FOR MORE"]},"SET_TRNS_TPE":{"kind":"procedure","purpose":"Stores a POSITION value within the specified position in the specified teach pendant program","params":[{"name":"open_id","dir":"in","type":"INTEGER","text":"open_id specifies the opened teach pendant program. A program must be opened before calling this built-in."},{"name":"position_no","dir":"in","type":"INTEGER","text":"position_no specifies the position in the program in which to store the value specified by posn. Data for other groups is not changed."},{"name":"posn","dir":"in","type":"POSITION","text":"posn is the group number of position_no."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error has occurred."}],"notes":["The position data is set in POSITION representation with no conversion."],"env":"PBCORE"},"SET_TSK_ATTR":{"kind":"procedure","purpose":"Set the value of the specified running task attribute","params":[{"name":"task_name","dir":"in","type":"STRING","text":"task_name is the name of the specified running task. A blank task_name will indicate the calling task."},{"name":"attribute","dir":"in","type":"INTEGER","text":"attribute is the task attribute whose value is to be set. The following attributes are valid: TSK_PRIORITY:Priority, see %PRIORITY for value information TSK_TIMESLIC:Time slice duration, see %TIMESLICE for value information TSK_NOBUSY:Busy lamp off, see %NOBUSYLAMP TSK_NOABORT:Ignore abort request Pg_np_error:no abort on error Pg_np_cmd:no abort on command TSK_NOPAUSE:Ignore pause request pg_np_error:no pause on error pg_np_end:no pause on command when TP is enabled pg_np_tpenb:no pause TSK_TRACE:Trace enable TSK_TRACELEN:Maximum number of lines to store when tracing TSK_TPMOTION:TP motion enable, see %TPMOTION for value information TSK_PAUSESFT:Pause on shift, reverse of %NOPAUSESHFT"},{"name":"value","dir":"in","type":"INTEGER","text":"value depends on the task attribute being set."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"env":"PBCORE","seeAlso":["GET_TSK_INFO"]},"SET_TSK_NAME":{"kind":"procedure","purpose":"Set the name of the specified task","params":[{"name":"old_name","dir":"in","type":"STRING","text":""},{"name":"new_name","dir":"in","type":"STRING","text":"new_name will become the new task name."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["task_name is the name of the task of interest. A blank task_name will indicate the calling task."],"env":"MULTI","seeAlso":["GET_ATTR_PRG"]},"SET_VAR":{"kind":"procedure","purpose":"Allows a KAREL program to set the value of a specified variable","params":[{"name":"entry","dir":"in,out","type":"INTEGER","text":"entry returns the entry number in the variable data table of var_name in the device directory where var_name is located. This variable should not be modified."},{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the program that contains the specified variable. If prog_name is '', then it defaults to the current task name being executed. prog_name can also access a system variable on a robot in a ring."},{"name":"var_name","dir":"in","type":"STRING","text":"var_name must refer to a static variable. var_name can contain node numbers, field names, and/or subscripts. var_name will be set to value."},{"name":"value","dir":"in","type":"ANY","text":"var_name must refer to a static variable. var_name can contain node numbers, field names, and/or subscripts. var_name will be set to value."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred. Caution Using SET_VAR to modify system variables could cause unexpected results."}],"notes":["Use prog_name of '*SYSTEM*' to set a system variable.","If both var_name and value are ARRAYs, the number of elements copied will equal the size of the smaller of the two arrays.","If both var_name and value are STRINGs, the number of characters copied will equal the size of the smaller of the two strings.","If both var_name and value are STRUCTUREs of the same type, value will be an exact copy of var_name.","If value is uninitialized, the value of var_name will be set to uninitialized and status will be set to 12311. value must be a static variable within the calling program.","The designated names of all the robots can be found in the system variable $PH_MEMBERS[]. This also include information about the state of the robot. The ring index is the array index for this system variable. KAREL users can write general purpose programs by referring to the names and other information in this system variable rather than explicit names."],"env":"SYSTEM","seeAlso":["RENAME_VAR"]},"SIN":{"kind":"function","purpose":"Returns a REAL value that is the sine of the specified angle argument","returns":"REAL","params":[{"name":"angle","dir":"in","type":"REAL","text":"angle specifies an angle in degrees. angle must be in the range of ± 18000 degrees. Otherwise, the program will be aborted with an error."}],"env":"SYSTEM"},"SQRT":{"kind":"function","purpose":"Returns a REAL value that is the positive square root of the specified REAL argument","returns":"REAL","params":[{"name":"x","dir":"in","type":"REAL","text":"x must not be negative. Otherwise, the program will be aborted with an error."}],"env":"SYSTEM"},"STR_LEN":{"kind":"function","purpose":"Returns the current length of the specified STRING argument","returns":"INTEGER","params":[{"name":"str","dir":"in","type":"STRING","text":"The returned value is the length of the STRING currently stored in the str argument, not the maximum length of the STRING specified in its declaration."}],"env":"SYSTEM"},"SUB_STR":{"kind":"function","purpose":"Returns a copy of part of a specified STRING argument","returns":"STRING","params":[{"name":"src","dir":"in","type":"STRING","text":"strt must be positive. Otherwise, the program is aborted with an error. If strt is greater than the length of src, then an empty string is returned."},{"name":"strt","dir":"in","type":"INTEGER","text":"strt must be positive. Otherwise, the program is aborted with an error. If strt is greater than the length of src, then an empty string is returned."},{"name":"len","dir":"in","type":"INTEGER","text":"len must be positive. Otherwise, the program is aborted with an error. If len is greater than the declared length of the return STRING, then the returned STRING is truncated to fit."}],"notes":["A substring of src is returned by the function.","The length of substring is the number of characters, specified by len, that starts at the indexed position specified by strt."],"env":"SYSTEM"},"TAN":{"kind":"function","purpose":"Returns a REAL value that is the tangent of the specified REAL argument","returns":"REAL","params":[{"name":"angle","dir":"in","type":"REAL","text":"The value of angle must be in the range of ± 18000 degrees. Otherwise, the program will be aborted with an error."}],"env":"SYSTEM"},"TRANSLATE":{"kind":"procedure","purpose":"Translates a KAREL source file (.KL file type) into p-code (.PC file type), which can be loaded into memory and executed.","params":[{"name":"file_spec","dir":"in","type":"STRING","text":"file_spec specifies the device, name and type of the file to translate. If no device is specified, the default device will be used. The type, if specified, is ignored and.KL is used instead."},{"name":"listing_sw","dir":"in","type":"BOOLEAN","text":"listing_sw specifies whether a.LS file should be created. The.LS file contains a listing of the source lines and any errors which may have occurred. The.LS file will be created on the default device."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If the number 0 is returned, the translation was successful. If not, an error occurred. Some of the status codes are shown below: 0 Translation was successful 268 Translator option is not installed 35084 File cannot be opened or created.KL file cannot be found or default device is not the RAM disk -1 Translation was not successful (Please see.LS file for details)"}],"notes":["The p-code file will be created on the default device. The default device should be set to the ram disk.","The KAREL program will wait while the TRANSLATE Built-In executes. If the KAREL program is paused, translation will continue until completed. If the KAREL program is aborted, translation will also be aborted and the.PC file will not be created.","If the KAREL program must continue to execute during translation, use the KCL_NO_WAIT Built-In instead."],"env":"TRANS"},"TRUNC":{"kind":"function","purpose":"Converts the specified REAL argument to an INTEGER value by removing the fractional part of the REAL argument","returns":"INTEGER","params":[{"name":"x","dir":"in","type":"REAL","text":"x must be in the range of -2147483648 to +2147483583. Otherwise, the program is aborted with an error."}],"notes":["The returned value is the value of x after any fractional part has been removed. For example, if x = 2.3, the.3 is removed and a value of 2 is returned.","ROUND and TRUNC can both be used to convert a REAL expression to an INTEGER expression."],"env":"SYSTEM","seeAlso":["ROUND"]},"UNINIT":{"kind":"function","purpose":"Returns a BOOLEAN value indicating whether or not the specified argument is uninitialized","returns":"BOOLEAN","params":[{"name":"variable","dir":"in","type":"ANY","text":"variable can be of any data type except an unsubscripted ARRAY, PATH, or structure."}],"notes":["A value of TRUE is returned if variable is uninitialized. Otherwise, FALSE is returned."],"env":"SYSTEM"},"UNLOCK_GROUP":{"kind":"procedure","purpose":"Unlocks motion control for the specified group of axes","params":[{"name":"group_mask","dir":"in","type":"INTEGER","text":"group_mask specifies the group of axes to unlock for the running task. The group numbers must be in the range of 1 to the total number of groups defined on the controller. Group_mask Settings GROUP DECIMAL BIT Group 1 1 1 Group 2 2 2 Group 3 4 3 To specify multiple groups select the decimal values which correspond to the desired groups. Then connect them together using the OR operator. For example to specify groups 1, 3, enter \"1 OR 4\"."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."}],"notes":["Unlocking a group indicates that the task is done with the motion group.","When a task completes execution (or is aborted), all motion groups that are locked by the program will be unlocked automatically.","If motion is executing or pending when the UNLOCK_GROUP Built-In is called, then status is set to 17039, \"Executing motion exists.\"","If motion is stopped when the UNLOCK_GROUP Built-In is called, then status is set to 17040, \"Stopped motion exists.\"","If a motion statement is encountered in a program that has the %NOLOCKGROUP Directive, the task will attempt to get motion control for all the required groups if it does not already have it. The task will pause if it cannot get motion control."],"env":"MULTI","seeAlso":["LOCK_GROUP"]},"UNPOS":{"kind":"procedure","purpose":"Sets the specified REAL variables to the location (x,y,z) and orientation (w,p,r) components of the specified XYZWPR variable and sets the specified CONFIG variable to the configuration component of the XYZWPR","params":[{"name":"posn","dir":"in","type":"XYZWPR","text":"c returns the configuration of posn."},{"name":"c","dir":"out","type":"CONFIG","text":"c returns the configuration of posn."}],"notes":["x, y, z, w, p, and r arguments are set to the x, y, and z location coordinates and yaw, pitch, and roll orientation angles of posn."],"env":"SYSTEM"},"VAR_INFO":{"kind":"procedure","purpose":"Allows a KAREL program to determine data type and numerical information regarding internal or external program variables","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the program that contains the specified variable. If prog_name is blank, then it defaults to the current program being executed."},{"name":"var_name","dir":"in","type":"STRING","text":"var_name must refer to a static program variable. var_name can contain node numbers, field names, and/or subscripts."},{"name":"uninit_b","dir":"out","type":"BOOLEAN","text":"uninit_b will return a value of TRUE if the variable specified by var_name is uninitialized and FALSE if the variable specified by var_name is initialized."},{"name":"type_nam","dir":"out","type":"STRING","text":"type_nam returns a STRING specifying the type name of var_name"},{"name":"dims","dir":"out","type":"ARRAY[3] OF INTEGER","text":"dims returns the dimensions of the array, if any. The size of the dims array should be 3. — dims[1] = 0 if not an array — dims[2] = 0 if not a two-dimensional array — dims[3] = 0 if not a three-dimensional array"},{"name":"type_value","dir":"out","type":"INTEGER","text":"type_value returns an INTEGER corresponding to the data type of var_name. The following table lists valid data types and their representative INTEGER values. Valid Data Types Data Type Value POSITION 1 XYZWPR 2 XYZWPREXT 6 INTEGER 16 REAL 17 BOOLEAN 18 VECTOR 19 VIS_PROCESS 21 MODEL 22 SHORT 23 BYTE 24 JOINTPOS1 25 CONFIG 28 FILE 29 Valid Data Types (Cont'd) Data Type Value PATH 31 CAM_SETUP 32 JOINTPOS2 41 JOINTPOS3 57 JOINTPOS4 73 JOINTPOS5 89 JOINTPOS6 105 JOINTPOS7 121 JOINTPOS8 137 JOINTPOS9 153 JOINTPOS 153 STRING 209 user-defined type 210"},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred."},{"name":"slen","dir":"out","type":"INTEGER","text":"slen returns the declared length of the variable specified by var_name if it is a STRING variable."}],"env":"BYNAM"},"VAR_LIST":{"kind":"procedure","purpose":"Locates variables in the specified KAREL program with the specified name and data type","params":[{"name":"prog_name","dir":"in","type":"STRING","text":"prog_name specifies the name of the program that contains the specified variables. prog_name can be specified using the wildcard (*) character, which specifies all loaded programs."},{"name":"var_name","dir":"in","type":"STRING","text":"var_name is the name of the variable to be found. var_name can be specified using the wildcard (*) character, which specifies that all variables for prog_name be found."},{"name":"var_type","dir":"in","type":"INTEGER","text":"var_type represents the data type of the variables to be found. The following is a list of valid data types: Valid Data Types Data Type Value All variable types 0 POSITION 1 XYZWPR 2 INTEGER 16 REAL 17 BOOLEAN 18 VECTOR 19 VIS_PROCESS 21 MODEL 22 SHORT 23 BYTE 24 JOINTPOS1 25 CONFIG 28 FILE 29 PATH 31 CAM_SETUP 32 JOINTPOS2 41 JOINTPOS3 57 JOINTPOS4 73 JOINTPOS5 89 JOINTPOS6 105 JOINTPOS7 121 JOINTPOS8 137 JOINTPOS9 153 JOINTPOS 153 STRING 209 user-defined type 210"},{"name":"n_skip","dir":"in","type":"INTEGER","text":"n_skip is used when more variables exist than the declared length of ary_nam. Set n_skip to 0 the first time you use VAR_LIST. If ary_nam is completely filled with variable names, copy the array to another ARRAY of STRINGs and execute the VAR_LIST again with n_skip equal to n_vars. The call to VAR_LIST will skip the variables found in the first pass and locate only the remaining variables."},{"name":"format","dir":"in","type":"INTEGER","text":"format specifies the format of the program name and variable name. The following values are valid for format: 1=prog_name only, no blanks 2 =var_name only, no blanks 3 =[prog_name]var_name, no blanks 4 ='prog_name var_name ', Total length = 27 characters, prog_name starts with character 1 and var_name starts with character 16."},{"name":"ary_nam","dir":"out","type":"ARRAY OF STRING","text":"ary_nam is an ARRAY of STRINGs to store the variable names. If the declared length of the STRING in ary_nam is not long enough to store the formatted data, then status is returned with an error."},{"name":"n_vars","dir":"out","type":"INTEGER","text":"n_vars is the number of variables stored in ary_name."},{"name":"status","dir":"out","type":"INTEGER","text":"status will return zero if successful."}],"env":"BYNAM","seeAlso":["PROG_LIST"]},"VOL_SPACE":{"kind":"procedure","purpose":"Returns the total bytes, free bytes, and volume name for the specified device","params":[{"name":"device","dir":"in","type":"STRING","text":"device can be: RD: The RAM disk returns all three parameters, but the volume name is '' since it is not supported. The RAM disk must be mounted in order to query it. FR: The FROM disk returns all three parameters, but the volume name is '' since it is not supported. The FROM disk must be mounted in order to query it. FR: Size of the Flash ROM. This only sets the total parameter. DRAM: Size of the DRAM. This only sets the total parameter. CMOS: Size of the CMOS ROM. This only sets the total parameter. TPP: The area of system memory where teach pendant programs are stored. PERM: The area of permanent CMOS RAM memory where system variables and selected KAREL variables are stored. TEMP: The area of temporary DRAM memory used for loaded KAREL programs, KAREL variables, program execution information, and system operations. SYSTEM: The area of temporary DRAM memory where the system software and options are stored. This memory is saved to FROM and restored on power up. Note All device names must end with a colon (:)."},{"name":"total","dir":"out","type":"INTEGER","text":"total is the original size of the memory, in bytes."},{"name":"free","dir":"out","type":"INTEGER","text":"free is the amount of available memory, in bytes."},{"name":"volume","dir":"out","type":"STRING","text":"volume is the name of the storage device used."}],"env":"FLBT"},"VREG_FND_POS":{"kind":"procedure","purpose":"Populates the specified position register with the found position data in the specified vision register.","notes":["visreg_no is the vision register (VR) number that contains the offset data.","camera_view is the specified camera view for a multi view vision process.","posreg_no is the position register (PR) number that is to be populated with the offset data.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"VREG_OFFSET":{"kind":"procedure","purpose":"Populates the specified position register with the offset data in the specified vision register.","notes":["visreg_no is the vision register (VR) number that contains the offset data","posreg_no is the position register (PR) number that is to be populated with the offset data.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"VT_ACK_QUEUE":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It acknowledges how a workpiece allocated by VT_GET_QUEUE call was handled to a specified work area.","notes":["Specify a work area number as area_num. You can get the work area number from the work area name using VT_GET_AREID.","Specify the vision register number that stores information on an allocated workpiece as vreg_num.","Specify one of the following values as ack: — 1–Specified when the allocated workpiece has been handled correctly. This applies when, for example, the robot picks up a workpiece from a conveyor or places a workpiece on a conveyor. — 2–Specified when the allocated workpiece has not been handled according to plan. This applies when, for example, the position or model ID of the allocated workpiece is evaluated by the program of the robot and picking up the workpiece is canceled intentionally. In this case, the information of the allocated workpiece is returned to the queue so that this workpiece can be handled by a downstream robot. — 3–Specified when the handling of the allocated workpiece has been failed. This applies when, for example, the allocated workpiece is dropped down, and then vacuum confirmation of the gripper shows an unacceptable result. In this case, because the robot has moved the workpiece, a downstream robot cannot handle this workpiece. So, the information of the workpiece is not returned to the queue.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_CLR_QUEUE":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It clears information of workpieces present in a specified work area. When called, all the information of the workpieces in the work area is entirely erased. Usually, this built-in is called just once when the system is started.","notes":["Specify a work area number as area_num. You can get the work area number from the work area name using VT_GET_AREID.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_DELETE_PQ":{"kind":"procedure","purpose":"This is a built-in for visual tracking customization. This function deletes a part from a queue. The part is identified by a work ID. Caution This built-in cannot be used together with Load Balance function. This built-in cannot delete a cell of a tray by default. If you want to delete a cell of a tray, you set a flag to the system variable $VTLINE[n].$FLAG in all robots before you start the robot controller program. You will be able to delete a cell of a tray in V7.70P/30 and later. 1. Find the system variable $VTLINE[n] whose $NAME is identical to the name of the line where the work area belongs. 2. Divide $VTLINE[n].$FLAG by 128 and get the quotient of the division. 3. If the quotient is an even number, add 128 to $VTLINE[n].$FLAG to enable the function. If the quotient is an odd number, do nothing because the function has already been enabled. 4. This setting is required for all robots.","notes":["Specify a work area number as area_num in order to identify the queue of the work area. You can get the work area number from the work area name using VT_GET_AREID.","Specify the index number of a part of the queue as work_id. You can know the index number by reading the PATH variable’s nodes gotten by VT_READ_PQ. Sensor task assigns unique index numbers for each found part. The specified part is deleted.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher.","You need the Virtual Robot with V7.70P/23 or later in order to translate this built-in."],"env":"CVIS"},"VT_GET_AREID":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It returns the work area number got from a specified work area name.","returns":"INTEGER [in] area_name: STRING","notes":["Specify a work area name as area_name.","This built-in returns a work area number that is specified as an argument for the visual tracking built-ins such as VT_ACK_QUEUE.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_GET_FOUND":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It outputs the information of a workpiece that a vision program finds.","notes":["Specify a vision program name as vp_name.","The model ID of the found workpiece is returned to model_id.","The encoder value got at the moment that the image is acquired in order to find the workpiece is returned to enc_count.","The offset data of the found workpiece is returned to offset.","The found positions of camera view 1-4 are returned to found_pos[1-4].","The measurement values of the found workpiece are returned to meas_val[1-10]. The measurement values are specified in the measurement output tool of a vision program.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in is used after V_RUN_FIND built-in.","If vision program finds more than one workpiece, call this built-in repeatedly until status of this built-in is not equal to 0. When there is no more workpiece to get, the status becomes 117151.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_GET_LINID":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It returns the line number got from a specified line name.","returns":"INTEGER [in] line_name: STRING","notes":["Specify a line name as line name.","This built-in returns the line number that is specified as an argument for VT_PUT_QUEUE.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_GET_PFRT":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It returns the rate at which the workpieces flow through the work area in one minute (expected workpiece flow rate).","notes":["Specify a work area number as area_num. You can get the work area number from the work area name using VT_GET_AREID.","Usually, specify 1 as consecutive. If workpieces are to be allocated successively regardless of the load balance to each work area, which is specified in the Line setup page, and you need the expected workpiece flow rate based on such allocation, specify the order of the next workpiece among workpieces allocated successively at once.","Usually, specify 1 as num_consct. If workpieces are to be allocated successively regardless of the load balance to each work area, which is specified in the Line setup page, and you need the expected workpiece flow rate based on such allocation, specify the total number of workpieces to be allocated successively at once.","When the expected workpiece flow rate is to be gotten by specifying a particular model ID, specify the model ID as model_id. Usually, this argument is not specified. If no model ID is specified, set an uninitialized variable to this argument.","The expected workpiece flow rate is stored in pfrt and calculated as follows. — Expected workpiece flow rate (workpieces/min) = Expected number of workpieces (workpieces) * Conveyor speed (mm/sec) * 60 (sec/min) / Distance that corresponds to the work area (mm)","Where \"Expected number of workpieces\" and \"Distance that corresponds to the work area\" are calculated as follows. — For each work area, the region for calculation is defined. The expected number of workpieces is calculated by use of workpieces contained only in this region. The downstream boundary of this region is the discard line of the work area. The upstream boundary of this region is any one of the following three. 1- If the work area is the most upstream one, the upstream boundary is the most upstream detection position of the workpieces which have been held by the work area when this built-in is called for the first time with the work area holding at least one workpiece. 2- If the work area is not the most upstream one and the \"Y Sort\" is disabled, the upstream boundary is the discard line of the previous work area in the line. 3- If the work area is not the most upstream one and the \"Y Sort\" is enabled, the upstream boundary is the position more downstream by the \"X Tolerane\" of the \"Y Sort\" from the discard line of the previous work area in the line. — Expected number of workpieces: This is the number of workpieces which are contained in the region for calculation and expected to be handled at the work area on the basis of the settings of \"Load Balance\" of the line, \"Y Sort\" of the work area and \"Seq\" of the tray pattern and the current performance. For example, if the setting of \"Load Balance\" is 50% at the most upstream work area, and before now 4 workpieces out of 7 have been handled at this work area, and 3 workpieces are contained in the region for calculation, then the expected number of workpieces is 1 (=(7+3)/2–4). — Distance that corresponds to the work area: This is the distance between the upstream and downstream boundaries of the region for calculation of the expected number of workpieces.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_GET_QUEUE":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It gets the information of one workpiece from a specified work area. The information of the gotten workpiece is stored in a vision register. The value of the encoder for the gotten workpiece is set as the trigger of a tracking motion. When there is no workpiece to be handled in the work area, the robot waits by a specified time until a workpiece actually reaches the work area.","notes":["Specify a work area number as area_num. You can get the work area number from the work area name using VT_GET_AREID.","Specify the vision register number to store information on an allocated workpiece as vreg_num.","Specify time in milliseconds for which the robot waits for a workpiece as timeout. If no workpiece reaches the work area by timeout, the status becomes 117249. When a negative value is specified, the robot waits indefinitely.","Usually, specify 1 as consecutive. To allocate workpieces successively regardless of the load balance to each work area, which is specified in the Line setup page, specify 2 or greater value.","When workpiece information is to be allocated by specifying a particular model ID, specify the model ID as model_id. Usually, this argument is not specified. If no model ID is specified, set an uninitialized variable (which has been declared but not stored with a value) to this argument.","When the ID of the workpiece to be allocated is known, specify it as work_id. This ID is the unique identifier specified by VT_PUT_QUEUE. Usually, this argument is not specified. If no ID is specified, set an uninitialized variable to this argument.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_GET_TIME":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It returns the estimated time to take until the next workpiece that can be handled arrives at a specified work area.","notes":["Specify a work area number as area_num. You can get the work area number from the work area name using VT_GET_AREID.","Usually, specify 1 as consecutive. If workpieces are to be allocated successively regardless of the load balance to each work area, which is specified in the Line setup page, and if you need the estimated time based on such allocation, specify 2 or greater value.","When the estimated time of workpiece is to be gotten by specifying a particular model ID, specify the model ID as model_id. Usually, this argument is not specified. If no model ID is specified, set an uninitialized variable to this argument.","When the ID of the workpiece is known, specify it as work_id. This ID is the unique identifier specified by VT_PUT_QUEUE. Usually, this argument is not specified. If no work ID is specified, set an uninitialized variable to this argument.","The estimated time is stored in time. If the next workpiece that can be handled has not arrived at the work area, a positive value is stored in time. The unit is millisecond. For example, when 1000 is stored, the estimated time to take until the next workpiece arrives is about 1000 millisecond. If a workpiece that can be handled has already arrived at the work area, then a negative value is stored.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_GET_TRYID":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It returns the tray number got from a specified tray name.","returns":"INTEGER [in] tray_name: STRING","notes":["Specify a tray name as tray_name.","This built-in returns the tray number that is specified as an argument for VT_PUT_QUEUE.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_PUT_QUE2":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It pushes workpiece information into a tracking queue and outputs a duplication status that indicates whether the new part is pushed into the queue or not pushed because of double detection. The syntax of this built-in is almost the same as VT_PUT_QUEUE KAREL built-in except an argument to indicate the duplication status.","notes":["If a new pushed part already exists in a tracking queue, “duplicated” becomes TRUE and the part is not pushed into the queue. Otherwise, if the new pushed part does not exist in the queue, “duplicated” becomes FALSE and the part is pushed into the queue.","The specifications of the other arguments are the same as VT_PUT_QUEUE.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher. Caution This built-in cannot push a tray."],"env":"CVIS"},"VT_PUT_QUEUE":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It pushes workpiece information into a tracking queue.","notes":["Specify a line number as line_num. The workpiece information is pushed into the queue of the most upstream work area. You can get the line number from the line name using VT_GET_LINID.","Specify the unique identifier of the workpiece as work_id when needed. Please specify work_id so that all the workpieces that are pushed into the queue have different identifiers when you control handling with the workpieces’ IDs specified as the argument of VT_GET_QUEUE. Please specify 0 when you do not use the IDs.","Specify a tray number as tray_num. If tray is not used, specify 0. You can get the tray number from the tray name using VT_GET_TRYID.","Specify an encoder value as enc_count. It is the encoder value got at the moment when the image is acquired in order to find the workpiece or when the sensor such as photo eye detects the workpiece.","Specify the model id for the workpiece as model_id.","Specify the offset data of the workpiece as offset.","Specify the found positions as found_pos[1-4].","Specify the measurement values as meas_val[1-10].","Usually, just specify the values acquired by VT_GET_FOUND built-in from enc_count to meas_val.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_READ_PQ":{"kind":"procedure","purpose":"This is a built-in for visual tracking customization. It reads the information of parts in a queue and copies them to a KAREL PATH variable. Caution This built-in cannot be used together with Load Balance function. This built-in cannot read the information of a cell of a tray by default. If you want to read the information of a cell of a tray, you set a flag to the system variable $VTLINE[n].$FLAG in all robots before you start the robot controller program. You will be able to read the information of a cell of a tray in V7.70P/30 and later. 1. Find the system variable $VTLINE[n] whose $NAME is identical to the name of the line where the work area belongs. 2. Divide $VTLINE[n].$FLAG by 128 and get the quotient of the division. 3. If the quotient is an even number, add 128 to $VTLINE[n].$FLAG to enable the function. If the quotient is an odd number, do nothing because the function has already been enabled. 4. This setting is required for all robots.","notes":["Specify a work area number as area_num in order to identify the queue of the work area. You can get the work area number from the work area name using VT_GET_AREID.","Specify the KAREL PATH variable where the information of parts are copied from the queue.","The type of the KAREL PATH variable is defined in advance in VSTKTYPS.KL that exists in the “support” folder which is created in Robot folder of the ROBOGUIDE workcell by doing \"Build\" for a KAREL source. You cannot use another type for the PATH variable. %ENVIRONMENT vstkdef TYPE VTPARTQ_T = PATH NODEDATA = VT_PART_ND _T, PATHHEADER = VT_PART_HD_T","VTPARTQ_T is the type of the PATH variable where the information of parts are copied from the queue. When you make a KAREL program, please make it include VSTKTYPS.KL and define the PATH variable.","The header and node of the PATH variable are defined as follows. TYPE VT_PART_HD_T = STRUCTURE area_id: INTEGER num_parts: INTEGER ENDSTRUCTURE VT_PART_ND_T = STRUCTURE work_id: INTEGER model_id: INTEGER tray_id: INTEGER enc_count: INTEGER offset: VT_POS_T found_pos: VT_POS_T meas_value: ARRAY[10] OF REAL ENDSTRUCTURE VT_POS_T = STRUCTURE x: REAL y: REAL z: REAL w: REAL p: REAL r: REAL ENDSTRUCTURE Member of Header (VT_PART_HD_T) area_id area id. num_parts Number of parts that are copied from a queue to this PATH variable. Only the num_parts nodes make sense. For example, if the total number of node is 100 and num_parts is 10, the nodes from node 1 to node 10 make sense. Member of Node (VT_PART_ND_T) work_id Index number of the part. Sensor task assigns unique index numbers for each found part or tray. model_id Model ID. tray_id Index number of a tray. You can use this index number in order to identify tray information. The tray information are stored in $VTTRAY[n] if $TRAY_ID = n. If tray is not used, this ID is uninitialized. enc_count Encoder count. This shows the encoder value got at the moment when the image where the part has been found is snapped or when a sensor such as photo eye detects this part. offset Offset data represented based on tracking frame. found_pos Found position represented based on tracking frame. meas_value Measurement values set by the measurement output tool of the vision process which found the part.","The smaller index number of node is, the more downstream the part is. That is, node 1 indicates the most downstream part in a queue. Caution If you read the information of a cell of a tray which uses sequence numbers, then it is not always true that the smaller index number of node is, the more downstream the part is.","When a queue has parts more than the number of nodes, the information of excess parts is not indicated in these nodes. You can know the current total number of parts in a queue from $VTAREASTAT[n]. $NUM_PARTS.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher.","You need the Virtual Robot with V7.70P/23 or later in order to translate this built-in."],"env":"CVIS"},"VT_SET_FLAG":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It enables or disables the multiple functions for a specified line or specified work areas at the same time.","notes":["Specify a line number as line_num. You can get the line number from the line name using VT_GET_LINID.","Specify the value (flag) that represents functions to be enabled for the line as line_bit2enb. Correspondence between the specified values and the functions to be enabled is as below. 1: [Load Balance] is enabled. 2: [Allocated in ascending order] is enabled, and the workpieces are allocated in ascending order from the most downstream work area. The above multiple functions can be enabled at the same time. For example, if 3 (= 1 + 2) is specified, then [Load Balance] and [Allocated in ascending order] are enabled at the same time.","Specify the value (flag) that represents functions to be disabled for the line as line_bit2dab. Correspondence between the specified value and the function to be disabled is as below. 1: [Load Balance] is disabled. 2: [Allocated in ascending order] is disabled, and the workpieces are allocated in descending order from the most upstream work area. The above multiple functions can be disabled at the same time. For example, if 3 (= 1 + 2) is specified, then [Load Balance] and [Allocated in ascending order] are disabled at the same time.","Positive values can not be set both to line_bit2enb and line_bit2dab at the same time. Please set a positive value either to line_bit2enb or line_bit2dab, and set 0 to the other.","Specify the values (flags) that represent functions to be enabled for work areas as area_bit2enb. Use area_bit2enb[1] for the most upstream work area. Use area_bit2enb[2] for the second most upstream work area. Correspondence between the specified values as area_bit2enb[n] and the functions to be enabled is as below. 1: [Skip this work area] is enabled. 2: [Y SORT] is enabled. 4: [Y SORT] is descending order. 8: [Stop/start Conveyor] is enabled. 16: [DO = OFF to stop] is selected. The above multiple functions can be enabled at the same time. For example, if 3 (= 1 + 2) is specified, then [Skip this work area] and [Y SORT] are enabled at the same time.","Specify the values (flags) that represent functions to be disabled for work areas as area_bit2dab. Use area_bit2dab[1] for the most upstream work area. Use area_bit2dab[2] for the second most upstream work area. Correspondence between the specified values as area_bit2dab[n] and the functions to be disabled is as below. 1: [Skip this work area] is disabled. 2: [Y Sort] is disabled. 4: [Y Sort] is ascending order. 8: [Stop/start Conveyor] is to be disabled. 16: [DO = ON to stop] is selected. The above multiple functions can be disabled at the same time. For example, if 3 (= 1 + 2) is specified, then [Skip this work area] and [Y SORT] are disabled at the same time.","Positive values can not be set both to area_bit2enb[n] and area_bit2dab[n] at the same time. Please set a positive value either to area_bit2enb[n] or area_bit2dab[n], and set 0 to the other.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_SET_LDBAL":{"kind":"procedure","purpose":"This is a built-in for visual tracking. It changes the load balance data of each work area on a specified line.","notes":["Specify a line number as line_num. You can get the line number from the line name using VT_GET_LINID.","Specify a model ID of workpieces for which the load balance should be changed as model_id. When [Common for all model IDs] is selected, please specify 0.","Specify rate of workpieces handled in each work area as n2pick. Specify the rate of workpieces handled in the most upstream work area in the specified line as n2pick[1]. Specify the rate of workpieces handled in the second most upstream work area as n2pick[2].","Specify the rate of [Bypass] as n2pass.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher."],"env":"CVIS"},"VT_WRITE_PQ":{"kind":"procedure","purpose":"This is a built-in for visual tracking customization. It writes the information of a part in a queue. The part is identified by a work ID. Caution This built-in cannot be used together with Load Balance function. This built-in cannot write the information of a cell of a tray by default. If you want to write the information of a cell of a tray, you set a flag to the system variable $VTLINE[n].$FLAG in all robots before you start the robot controller program. You will be able to write the information of a cell of a tray in V7.70P/30 and later. 1. Find the system variable $VTLINE[n] whose $NAME is identical to the name of the line where the work area belongs. 2. Divide $VTLINE[n].$FLAG by 128 and get the quotient of the division. 3. If the quotient is an even number, add 128 to $VTLINE[n].$FLAG to enable the function. If the quotient is an odd number, do nothing because the function has already been enabled. 4. This setting is required for all robots.","notes":["Specify a work area number as area_num in order to identify the queue of the work area. You can get the work area number from the work area name using VT_GET_AREID.","Specify the index number of a part of the queue as work_id. You can know the index number by reading the PATH variable’s nodes gotten by VT_READ_PQ. Sensor task assigns unique index numbers for each found part.","Specify new values from model_id to meas_value. You can write the following information. When you do not want to change some of the existing values, you specify uninitialized values as them. — Model ID. For example, you can assign each robot to handle parts with different model IDs. — Encoder count. This shows the encoder value got at the moment when the image where the part has been found is snapped or when a sensor such as photo eye detects this part. — Offset data represented by tracking frame. — Found positions represented by tracking frame. — Measurement values set by the measurement output tool of the vision process which found the part. On the other hand, if you use a third-party sensor, you can add the result of that sensor to the measurement values.","The status of the process is returned to status. If the process is successful, then status is set to 0. If the process is not successful, then an alarm code that is not equal to 0 is returned.","This built-in needs the iRVision KAREL interface option (J870) and the iRVision Tracking Queue option (J874), or PickTool + iRVision (R662), or PickTool – iRVision (R718).","This built-in is not available in controller s/w versions v8.20 and higher.","You need the Virtual Robot with V7.70P/23 or later in order to translate this built-in."],"env":"CVIS"},"V_ACQ_VAMAP":{"kind":"procedure","purpose":"Acquires a 3D area map using the specified 3D area sensor tool.","notes":["sensor_name is the name of the 3D area sensor tool.","partial is an internal parameter. Always set to FALSE.","center_pos is an internal parameter. Declare a VECTOR variable and set x, y, and z to 0.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","The acquired 3D map is kept until a new 3D map for the same 3D area sensor is acquired, or V_CLR_VAMAP is explicitly called or the robot controller is turned off.","This built-in is available on R-30iB.","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."],"env":"CVIS"},"V_ADJ_2D":{"kind":"procedure","purpose":"Modifies the offset in a specified vision register by X and Y.","notes":["register_no is the number of the vision register where the vision offset is stored.","x is the amount in X to adjust the offset.","y is the amount in Y to adjust the offset.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_CAM_CALIB":{"kind":"procedure","purpose":"Finds the calibration grid for either a single plane or multiple plane calibration.","notes":["cal_name is the name of the calibration setup file created in setup mode.","func_code is the plane number to find. One (1) for first plane or single plane calibration and two (2) for second plane in multiplane calibration. Function Code Values Calibration Type Function Code Grid Pattern Calibration Specify the index of the calibration plane: 1 or 2. Robot-generated Grid Calibration Specify a different number for each calibration point. The robot-generated grid calibration function automatically generates a TP program that calls the instruction identical to this built-in. So this built-in will not be used for this calibration tool. 3DL Calibration Specify the index of the calibration plane: 1 or 2. Function Code Values (Cont'd) Calibration Type Function Code Visual Tracking Calibration Not supported Simple 2D Calibration Not supported","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","The calibration file must already exist and be set up. This built-in will recalibrate an already calibrated file.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."],"env":"CVIS"},"V_CLR_VAMAP":{"kind":"procedure","purpose":"Clears the 3D area map of a specified area sensor tool from memory.","notes":["sensor_name is the name of the 3D area sensor tool.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","This built-in is available on R-30iB.","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_DISPLAY4D":{"kind":"procedure","purpose":"Displays the 4D Graphics screen for the specified vision tool on the iPendant.","notes":["vistool_name is the name of the vision tool for which the 4D Graphics should be displayed.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","The vision tool specified by vistool_name can be a camera calibration, vision process, or 3D area sensor.","V_DISPLAY4D is available for V8.20 and later. This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_FIND_VIEW":{"kind":"procedure","purpose":"Runs vision find processing on the specified vision process, using a previously captured image. When the vision process has more than one camera view, processing is performed for the specified view.","notes":["vp_name is the name of the vision process to run.","camera_view is the number of the camera view, if the vision process is multi-view. A value of -1 will run all of the views.","image_reg is the number of the image register which contains the existing image.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","The robot controller must be configured to have one or more image registers. To do so, set $VISION_CFG.$NUM_IMREGS to a nonzero value. You may also need to modify the value of $VISION_CFG.$IMREG_SIZE depending on the type and resolution of the camera: — Grayscale cameras: 320 x 240: Set $VISION_CFG.$IMREG_SIZE minimum value = 75 640 x 480: 300 (default) 640 x 960: 600 1024 x 768: 768 1280 x 480: 600 1280 x 1024: 1280 — Color digital cameras: 640 x 480: 1200 1024 x 768: 2304 — 3D laser sensor: 1500","After modifying $VISION_CFG.$NUM_IMREGS and/or $VISION_CFG.$IMREG_SIZE, turn off the robot controller and then turn it back on for the changes to take effect.","Note that increasing these values will decrease the amount of memory available for other applications.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_GET_OFFSET":{"kind":"procedure","purpose":"Gets a vision offset from a vision process and stores it in a specified vision register.","notes":["vp_name is the name of the vision process created in setup mode","register_no is the register number in which the offset and vision data is placed.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","This command is used after a V_RUN_FIND built-in procedure. If image processing is not yet completed when V_GET_OFFSET is executed, it waits for the completion of the image processing. V_GET_OFFSET stores the vision offset for a workpiece in a vision register. When the vision process finds more than one workpiece, V_GET_OFFSET should be called repeatedly.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."],"env":"CVIS"},"V_GET_PASSFL":{"kind":"procedure","purpose":"Gets the status of the error proofing vision process. It then stores the result in a specified numeric register.","notes":["vp_name is the name of the error proofing or inspection vision process created in setup mode","register_no is the register number the command will set with the status of the error proofing/inspection operation. 0: operation failed 1: operation was successful 2: operation is undetermined because the parent tool failed","status explains the status of the attempted operation. If status is not equal to 0, then an error occurred.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."],"env":"CVIS"},"V_GET_QUEUE":{"kind":"procedure","purpose":"Gets a part from the specified queue and stores the information in a vision register.","notes":["Queue_num is the number of the queue from which to get the parts.","Vr_num is the number of the vision register (VR) in which to put the offsets.","Timeout is the time to wait until a timeout occurs.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","This command sets, as a tracking trigger, the value of the existing encoder when the picked up target is found.","This built-in is only available on R-30iA robot controllers.","This built-in requires the iRVision KAREL Interface Software Option (J870)."]},"V_GET_VPARAM":{"kind":"procedure","purpose":"Retrieves the value of a vision parameter from a specified vision process. When the vision process has more than one camera view, the value is retrieved for the specified view.","notes":["vp_name is the name of the vision process to run.","param_no is the number of the parameter to retrieve. The valid values of param_no are: — 0: Number of found results","camera_view is the number of the camera view, if the vision process is multi-view. A value of -1 will run all of the views.","reg_no is the number of the register in which to store the result. The result is stored as a REAL value.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_INIT_QUEUE":{"kind":"procedure","purpose":"Initializes the specified queue.","notes":["Queue_num is the number of the queue to be initialized.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","All workpiece information held in the queue when the command is executed is cleared.","When multiple robots are used to pick up workpieces on one conveyor, this command must be executed individually for all robots.","This built-in is only available on R-30iA robot controllers.","This built-in requires the iRVision KAREL Interface Software Option (J870)."]},"V_IRCONNECT":{"kind":"procedure","purpose":"Sends the most recent iRVision result to mobile devices using iRConnect.","notes":["desc_string is the description string to associate with the vision result data.","priority is the priority level of the vision result data. The valid values of priority are: 0: Data is informational only. Not highlighted in the mobile app. 1: Data is informational only. Highlighted in green. 2: Data indicates a potential problem or warning. Highlighted in yellow. 3: Data indicates a serious issue. Highlighted in red.","vis_reg_no is currently an unused parameter. Always set this parameter to 0.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","The vision result data sent to the mobile device contains the same information as the iRVision Runtime screen, including — Vision process name — Status — Number of found results — Found positions — Time to find — Result score, model ID, fit error, etc. — Result measurements","Runtime images may also be sent via iRConnect if enabled in the Vision Configuration screen.","V_IRCONNECT is available for V8.20 and later. This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_LED_OFF":{"kind":"procedure","purpose":"Turns off an attached LED light for vision. The LED light must be attached to a multiplexer for analog cameras.","notes":["status explains the status of the attempted operation. If not equal to 0, then an error occurred.","V_LED_OFF turns off the LED light that was most recently turned on by the V_LED_ON built-in procedure or IRVLEDON KAREL program call.","Only one LED light can be turned on at any time, even if multiple LED lights are connected to the multiplexer.","This built-in is available on R-30iB.","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_LED_ON":{"kind":"procedure","purpose":"Turns on an LED light attached for vision. The LED light must be connected to a multiplexer for analog cameras.","notes":["channel is the multiplexer channel of the attached LED light. Valid values are 1 to 8.","intensity is the desired intensity level to set the LED light to. Valid values are 1 to 16.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","Only one LED light can be turned on at any time, even if multiple LED lights are connected to the multiplexer. Turning on a second LED light will automatically turn off the first LED light. Some delay may occur between the first light turning off and the second light turning on.","This built-in is available on R-30iB.","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_OVERRIDE":{"kind":"procedure","purpose":"Sets the value of the specified Vision Override tool.","notes":["ovrd_name is the name of the Vision Override tool to set. The Vision Override tool is created and configured in iRVision Setup.","value is the value to change the Vision Override tool property to.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","V_OVERRIDE is used to temporarily modify a property that was saved with a vision process.","Generally, this command is used immediately before performing a V_RUN_FIND operation or other vision process execution.","Once the vision process find has been executed, the values that were set by V_OVERRIDE are reset to their saved values.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_RALC_QUEUE":{"kind":"procedure","purpose":"Places or reallocates a part received from the queue back onto the queue for a downstream robot.","notes":["queue_num is the number of the queue in which to reallocate the parts.","vr_num is the number of the vision register (VR) of the offset to reallocate.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","This built-in is only available on R-30iA robot controllers.","This built-in requires the iRVision KAREL Interface Software Option (J870)."]},"V_RUN_FIND":{"kind":"procedure","purpose":"Starts an iRVision process. When a specified vision process has more than one camera view, location is performed for the specified camera views.","notes":["vp_name is the name of the vision process created in setup mode","camera_view is the number of the camera view. Used for multi camera vision processes. A value of -1 will run all of the views.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."],"env":"CVIS"},"V_SAVE_IMREG":{"kind":"procedure","purpose":"Saves an image from an image register to a file.","notes":["image_reg is the number of the image register which contains the existing image.","output_path is the path (device, directory, and file name) where the image will be saved. The file name must end with \".PNG\" or \".BMP\".","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","The robot controller must be configured to have one or more image registers. To do so, set $VISION_CFG.$NUM_IMREGS to a nonzero value. You may also need to modify the value of $VISION_CFG.$IMREG_SIZE depending on the type and resolution of the camera: — Grayscale cameras: 320 x 240: Set $VISION_CFG.$IMREG_SIZE minimum value = 75 640 x 480: 300 (default) 640 x 960: 600 1024 x 768: 768 1280 x 480: 600 1280 x 1024: 1280 — Color digital cameras: 640 x 480: 1200 1024 x 768: 2304 — 3D laser sensor: 1500","After modifying $VISION_CFG.$NUM_IMREGS and/or $VISION_CFG.$IMREG_SIZE, turn off the robot controller and then turn it back on for the changes to take effect.","Note that increasing these values will decrease the amount of memory available for other applications.","V_SAVE_IMREG is typically used in conjunction with V_SNAP_VIEW, which captures an image and stores it in an image register.","V_SAVE_IMREG supports saving PNG or BMP image files. Specifying any other image format using output_path will result in a nonzero status.","V_SAVE_IMREG is available for V8.30 and later. This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_SET_REF":{"kind":"procedure","purpose":"Sets the reference position in the specified vision process after V_RUN_FIND has been run.","notes":["vp_name is the name of the vision process created in setup mode.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","If a vision process remains open on the setup PC when SET_REFERENCE is executed for the vision process, the reference position cannot be written to the vision process, which results in an alarm. Close the setup window, then re-execute the command.","When the vision process finds more than one workpiece, the position of the workpiece having the highest score is set as the reference position.","It is recommended that only one workpiece be placed within the camera view so that an incorrect position is not set as the reference position.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_SNAP_VIEW":{"kind":"procedure","purpose":"Acquires an image using the specified vision process and stores it in an image register. When the vision process has more than one camera view, the image is acquired using the specified view.","notes":["vp_name is the name of the vision process to use to acquire the image.","camera_view is the number of the camera view, if the vision process is multi-view.","image_reg is the number of the image register where the image is to be stored.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","The robot controller must be configured to have one or more image registers. To do so, set $VISION_CFG.$NUM_IMREGS to a nonzero value. You may also need to modify the value of $VISION_CFG.$IMREG_SIZE depending on the type and resolution of the camera: — Grayscale cameras: 320 x 240: Set $VISION_CFG.$IMREG_SIZE minimum value = 75 640 x 480: 300 (default) 640 x 960: 600 1024 x 768: 768 1280 x 480: 600 1280 x 1024: 1280 — Color digital cameras: 640 x 480: 1200 1024 x 768: 2304 — 3D laser sensor: 1500","After modifying $VISION_CFG.$NUM_IMREGS and/or $VISION_CFG.$IMREG_SIZE, turn off the robot controller and then turn it back on for the changes to take effect.","Note that increasing these values will decrease the amount of memory available for other applications.","(R-30iA) This built-in requires the iRVision KAREL Interface Software Option (J870).","(R-30iB, before V8.20) This built-in requires the iRVision Client Option (J917) or iRVision VisTrack Package Option (R687).","(R-30iB, V8.20 and later) This built-in requires an iRVision Package Option (R685, R686, R687, R688)."]},"V_START_VTRK":{"kind":"procedure","purpose":"Starts the specified visual tracking vision process.","notes":["vp_name is the name of the visual tracking vision process.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","After this command is executed, iRVision monitors a specified condition (such as a conveyor move distance). iRVision executes the specified vision process each time a specified condition is satisfied. When multiple robots are used with one conveyor, this command is executed only in the robots on which iRVision resides.","This built-in requires the iRVision KAREL Interface Software Option (J870)."]},"V_STOP_VTRK":{"kind":"procedure","purpose":"Stops the specified visual tracking vision process.","notes":["vp_name is the name of the visual tracking vision process.","status explains the status of the attempted operation. If not equal to 0, then an error occurred.","When multiple robots are used with one conveyor, this command is executed only in the robots on which iRVision resides.","This built-in requires the iRVision KAREL Interface Software Option (J870)."]},"WRITE_DICT":{"kind":"procedure","purpose":"Writes information from a dictionary","params":[{"name":"file_var","dir":"in","type":"FILE","text":"file_var must be opened to the window where the dictionary text is to appear."},{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the name of the dictionary from which to write."},{"name":"element_no","dir":"in","type":"INTEGER","text":"element_no specifies the element number to write. This number is designated with a ``$'' in the dictionary file."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred writing the element from the dictionary file."}],"env":"PBCORE","seeAlso":["REMOVE_DICT"]},"WRITE_DICT_V":{"kind":"procedure","purpose":"Writes information from a dictionary with formatted variables","params":[{"name":"file_var","dir":"in","type":"FILE","text":"file_var must be opened to the window where the dictionary text is to appear."},{"name":"dict_name","dir":"in","type":"STRING","text":"dict_name specifies the name of the dictionary from which to write."},{"name":"element_no","dir":"in","type":"INTEGER","text":"element_no specifies the element number to write. This number is designated with a $ in the dictionary file."},{"name":"value_array","dir":"in","type":"ARRAY OF STRING","text":"value_array is an array of variable names that corresponds to each formatted data item in the dictionary text. Each variable name may be specified as '[prog_name]var_name'. — [prog_name] specifies the name of the program that contains the specified variable. If not specified, then the current program being executed is used. — var_name must refer to a static, global program variable. — var_name may contain node numbers, field names, and/or subscripts."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred writing the element from the dictionary file."}],"env":"UIF","seeAlso":["READ_DICT_V"]},"XML_ADDTAG":{"kind":"procedure","purpose":"Associates the tag “tag_name” with the “xml_file”.","params":[{"name":"xml_file","dir":"in","type":"FILE","text":"xml_file specifies an open KAREL file with AR_XML attribute set"},{"name":"tag_name","dir":"in","type":"STRING","text":"tag_name Name of the tag you want to know about"},{"name":"numchar","dir":"in","type":"INTEGER","text":"numchar specifies the number of characters to use when looking for the tag"},{"name":"caseflag","dir":"in","type":"BOOLEAN","text":"caseflag If TRUE, specifies whether the tag_name is case sensitive"},{"name":"tag_ident","dir":"in","type":"INTEGER","text":"tag_ident Application identifier that user associates with tag There are some system tag idents that the user cannot use. This is used to allow you to switch on his tags and the user return codes. When the scanning encounters the registered tag it will return with the tag_ident. The file MUST be open before you can register a tag. tag_ident should be a unique number within the application. This allows the application to do a select based on the return identifier. NOTE: The system reserves some identifiers for error and scan limit status returns. This allows the application to easily include these constants in the select statement."},{"name":"status","dir":"out","type":"INTEGER","text":"status explains the status of the attempted operation. If not equal to 0, then an error occurred writing the element from the dictionary file. The return status will be bad if the user has not opened the file and set the XML attribute."}],"env":"PBCORE"},"XML_GETDATA":{"kind":"procedure","purpose":"Returns the attribute names and values associated with the tag causing the return.","params":[{"name":"xml_file","dir":"in","type":"FILE","text":"xml_file An open KAREL file with AR_XML attribute set"},{"name":"numattr","dir":"out","type":"INTEGER","text":"numattr indicates the number of attributes"},{"name":"attrnames","dir":"out","type":"ARRAY OF STRING","text":"attrnames indicates attribute names"},{"name":"attrvalues","dir":"out","type":"ARRAY OF STRING","text":"attrvalues indicates attribute values"},{"name":"textdata","dir":"out","type":"STRING","text":"textdata indicates the text that follows the tag"},{"name":"textdone","dir":"out","type":"BOOLEAN","text":"textdone If this is FALSE, more text is to be read"},{"name":"status","dir":"out","type":"INTEGER","text":"status indicates the result of the operation"}]},"XML_REMTAG":{"kind":"procedure","purpose":"Removes the tag name from the list.","params":[{"name":"xml_file","dir":"in","type":"FILE","text":"xml_file Open KAREL file with AR_XML attribute set"},{"name":"tag_name","dir":"in","type":"STRING","text":"tag_name Indicates the name of the tag to remove"},{"name":"status","dir":"out","type":"INTEGER","text":"status Indicates the result of the operation Caution Do not attempt to remove a tag while it is in use."}]},"XML_SCAN":{"kind":"procedure","purpose":"Scan through a previously opened XML file","params":[{"name":"xml_file","dir":"in","type":"FILE","text":"xml_file Open KAREL file with AR_XML attribute set"},{"name":"tag_name","dir":"out","type":"STRING","text":"tag_name Name of the tag system found"},{"name":"tag_ident","dir":"out","type":"INTEGER","text":"tag_ident Tag user associated in addtag call The tag_ident will be the tag_ident that the user registered for the registered tag return. If the system returns for other reasons then the tag_ident may contain system tag data."},{"name":"func_code","dir":"out","type":"INTEGER","text":"func_code Function code, start etc"},{"name":"status","dir":"out","type":"INTEGER","text":"status Result of operation"}],"notes":["When a registered tag is found — Func_code = XML_START or XML_END or XML_STEND — Tag_ident = The value associated with the tag when it was registered","When a text buffer is full — Func_code = XML_TXCONT — Tag_ident = The value associated with the tag when it was registered","After 50 lines are scanned — Status = XML_SCANLIM, just recall the built-in when the is encountered — Tag_ident = XML_SCANLIM — This is not an error and indicates that there is more to come","If it encounters a parsing error — Status = Some error — Tag_ident = XML_ERROR","At the end of file, Status = SUCCESS","Valid Parse Errors are: — XML_TAG_SIZE Too many characters in tag — XML_ATTR_SIZE Too many characters in attribute — XML_NOSLASH Invalid use of / character — XML_INVTAG Invalid character in tag — XML_UNMATCHATTR No value for attribute — XML_UNMATCHTAG End tag with no matching start — XML_INVATTR Invalid character in attribute — XML_NOFILE Cannot find file — XML_TAGNEST Tag nesting level too deep — XML_COMMENT Error in comment","The system will provide a separate return for the start of the tag and the end of the tag if the tag does not contain both starting and ending information. The attribute data is NOT valid when the call is made for the END tag."]},"XML_SETVAR":{"kind":"procedure","purpose":"Sets the variable [prog_name]var_name according to the attributes that were associated with the tag causing the return.","params":[{"name":"xml_file","dir":"in","type":"FILE","text":""},{"name":"prog_name","dir":"in","type":"STRING","text":""},{"name":"var_name","dir":"in","type":"STRING","text":""},{"name":"status","dir":"out","type":"INTEGER","text":""}],"notes":["In this case the text for the attribute will be matched with the text field name of the KAREL variable. So a variable of this type: xmlstrct_t = STRUCTURE first: integer second: real third: BOOLEAN fourth: string[20] ENDSTRUCTURE Can be set via the XML: <xmlstrct_t first=\"123456\" second=\"7.8910\" third=\"1\" fourth=\"A string\"\\>","The XML tag name does not need to match the TYPE name. The association of the field names and attribute names is based on the [program]variable in the call to xml_setvar."]}};
export const KAREL_LANGUAGE_DETAILS: Record<string, KLanguageDetail[]> = {"%ALPHABETIZE":[{"kind":"directive","purpose":"Specifies that static variables will be created in alphabetical order when p-code is loaded.","syntax":["%ALPHABETIZE"],"details":["Static variables can be declared in any order in a KAREL program and %ALPHABETIZE will cause them to be displayed in alphabetical order in the DATA menu or KCL> SHOW VARS listing."]}],"%CMOS2SHADOW":[{"kind":"directive","purpose":"Instructs the translator to put all CMOS variables in Shadow memory","syntax":["%CMOS2SHADOW"]}],"%CMOSVARS":[{"kind":"directive","purpose":"Specifies the default storage for KAREL variables is permanent memory","syntax":["%CMOSVARS"],"details":["If %CMOSVARS is specified in the program, then all static variables by default will be created in permanent memory.","If %CMOSVARS is not specified, then all static variables by default will be created in temporary memory.","If a program specifies %CMOSVARS, but not all static variables need to be created in permanent memory, the IN DRAM clause can be used on selected variables."]}],"%COMMENT":[{"kind":"directive","purpose":"Specifies a comment of up to 16 characters","syntax":["%COMMENT = 'ssssssssssssssss'","where ssssssssssssssss = space"],"details":["The comment can be up to 16 characters long.","During load time, the comment will be stored as a program attribute and can be displayed on the teach pendant or CRT/KB.","%COMMENT must be used after the PROGRAM statement, but before any CONST, TYPE, or VAR sections."],"seeAlso":["GET_ATTR_PRG"]}],"%DEFGROUP":[{"kind":"directive","purpose":"Specifies the default motion group to be used by the translator","syntax":["%DEFGROUP = n"],"details":["n is the number of the motion group.","The range is 1 to the number of groups on the controller.","If %DEFGROUP is not specified, group 1 is used."]}],"%DELAY":[{"kind":"directive","purpose":"Sets the amount of time program execution will be delayed every 250 milliseconds. Each program is delayed 8ms every 250ms by default. This allows the CPU to perform other functions such as servicing the CRT/KB and Teach Pendant user interfaces. %DELAY provides a way to change from the default and allow more CPU for system tasks such as user interface.","syntax":["%DELAY = n"],"details":["n is the delay time in milliseconds.","The default delay time is 8 ms, if no DELAY is specified","If n is set to 0, the program will attempt to use 100% of the available CPU time. This could result in the teach pendant and CRT/KB becoming inoperative since their priority is lower. A delay of 0 is acceptable if the program will be waiting for motion or I/O.","While one program is being displayed, other programs are prohibited from executing. Interrupt routines (routines called from condition handlers) will also be delayed.","Very large delay values will severely inhibit the running of all programs.","To delay one program in favor of another, use the DELAY Statement instead of %DELAY."]}],"%ENVIRONMENT":[{"kind":"directive","purpose":"Loads environment file.","syntax":["%ENVIRONMENT path_name"],"details":["Used by the off-line translator to specify that the binary file, path_name.ev, should be loaded. Environment files contain definitions for predefined constants, ports, types, system variables, and built-ins.","All.EV files are loaded upon installation of the controller software. Therefore, the controller's translator will ignore %ENVIRONMENT statements since it already has the.EV files loaded.","path_name can be one of the following: — BYNAM — CTDEF (allows program access to CRT/KB system variables) — ERRS — FDEV — FLBT — IOSETUP — KCLOP — MEMO — MIR — MOTN — MULTI — PATHOP — PBCORE — PBQMGR — REGOPE — STRNG — SYSDEF (allows program access to most system variables) — SYSTEM — TIM — TPE — TRANS — UIF — VECTR","If no %ENVIRONMENT statements are specified in your KAREL program, the off-line translator will load all the.EV files specified in TRMNEG.TX. The translator must be able to find these files in the current directory or in one of the PATH directories.","If at least one %ENVIRONMENT statement is specified, the off-line translator will only load the files you specify in your KAREL program. Specifying your own %ENVIRONMENT statements will reduce the amount of memory required to translate and will be faster, especially if you do not require system variables since SYSDEF.EV is the largest file.","SYSTEM.EV and PBCORE.EV are automatically loaded by the translator and should not be specified in your KAREL program. The off-line translator will print the message \"Continuing without system defined symbols\" if it cannot find SYSTEM.EV. Do not ignore this message. Make sure the SYSTEM.EV file is loaded."]}],"%INCLUDE":[{"kind":"directive","purpose":"Inserts other files in a program at translation time.","syntax":["%INCLUDE file_spec"],"details":["file_spec is the name of the file to include. It has the following details: — The file name specified must be no longer than 36 characters. — The file type defaults to.KL, and so it does not appear in the directive.","The %INCLUDE directive must appear on a line by itself.","The specified files usually contain declarations, such as CONST or VAR declarations. However, they can contain any portion of a program including executable statements and even other %INCLUDE directives.","Included files can themselves include other files up to a maximum depth of three nested included files. There is no limit on the total number of included files.","When the KAREL language translator encounters a %INCLUDE directive during translation of a file, it begins translating the included file just as though it were part of the original file. When the entire file has been included, the translator resumes with the original file.","FANUC supplies these include files: %INCLUDE FR:\\klevkmsk %INCLUDE FR:\\klevkeys %INCLUDE FR:\\klevccdf %INCLUDE FR:\\kliotyps These files contain constants that can be used in your KAREL programs. If you are translating on the controller, you can include them directly from the FROM disk. The include files are also installed with ROBOGUIDE into the support folder, and are copied to the hard disk as part of the installation process."]}],"%LOCKGROUP":[{"kind":"directive","purpose":"Specifies the motion group(s) to be locked when calling this program or a routine from this program.","syntax":["%LOCKGROUP = n, n,..."],"details":["n is the number of the motion group to be locked.","The range of n is 1 to the number of groups on the controller.","When the program or routine is called, the task will attempt to get motion control for all the specified groups if it does not have them locked already. The task will pause if it cannot get motion control.","If %LOCKGROUP is not specified, all groups will be locked.","The %NOLOCKGROUP directive can be specified if no groups should be locked."],"seeAlso":["UNLOCK_GROUP"]}],"%NOABORT":[{"kind":"directive","purpose":"Specifies a mask for aborting","syntax":["%NOABORT = ERROR + COMMAND"],"details":["ERROR and COMMAND are defined as follows: ERROR: ignore abort error severity COMMAND: ignore abort command","Any combination of ERROR and COMMAND can be specified.","If the program is aborted by itself (for example, executing an ABORT statement, run-time error), the %NOABORT directive will be ignored and program execution will be aborted.","This directive is only effective for programs with %NOLOCKGROUP. If the program has motion control, the %NOABORT directive will be ignored and program execution will be aborted."]}],"%NOBUSYLAMP":[{"kind":"directive","purpose":"Specifies that the busy lamp will be OFF during execution.","syntax":["%NOBUSYLAMP"],"details":["The busy lamp can be set during task execution by the SET_TSK_ATTR built-in."]}],"%NOLOCKGROUP":[{"kind":"directive","purpose":"Specifies that motion groups do not need to be locked when calling this program, or a routine defined in this program.","syntax":["%NOLOCKGROUP"],"details":["When the program or routine is called, the task will not attempt to get motion control.","If %NOLOCKGROUP is not specified, all groups will be locked when the program or routine is called, and the task will attempt to get motion control. The task will pause if it cannot get motion control.","The task will keep motion control while it is executing the program or routine. When it exits the program or routine, the task automatically unlocks all the motion groups.","If the task contains executing or stopped motion, then task execution is held until the motion is completed. Stopped motion must be resumed and completed or cancelled.","If a program that has motion control calls a program with the %NOLOCKGROUP Directive or a routine defined in such a program, the program will keep motion control even though it is not needed.","The UNLOCK_GROUP built-in routine can be used to release control.","If a motion statement is encountered in a program that has the %NOLOCKGROUP Directive, the task will attempt to get motion control for all the required groups if it does not already have it. The task will pause if it cannot get motion control."],"seeAlso":["%LOCKGROUP","UNLOCK_GROUP"]}],"%NOPAUSE":[{"kind":"directive","purpose":"Specifies a mask for pausing","syntax":["%NOPAUSE = ERROR + COMMAND + TPENABLE"],"details":["The bits for the mask are as follows: ERROR: ignore pause error severity COMMAND: ignore pause command TPENABLE: ignore paused request when TP enabled","Any combination of ERROR, COMMAND, and TPENABLE can be specified.","If the program is paused by itself, the %NOPAUSE directive will be ignored and program execution will be paused.","This directive is only effective for programs with %NOLOCKGROUP. If the program has motion control, the %NOPAUSE Directive will be ignored and program execution will be paused."]}],"%NOPAUSESHFT":[{"kind":"directive","purpose":"Specifies that the task is not paused if shift key is released.","syntax":["%NOPAUSESHFT"],"details":["This attribute can be set during task execution by the SET_TSK_ATTR built-in routine."]}],"%PRIORITY":[{"kind":"directive","purpose":"Specifies task priority","syntax":["%PRIORITY = n"],"details":["n is the priority and is defined as follows: 1 to 89: lower than motion, higher than user interface 90 to 99: lower than user interface","The lower the value, the higher the task priority.","The default priority is 50.","The priority can be set during task execution by the SET_TSK_ATTR Built-In routine."]}],"%SHADOWVARS":[{"kind":"directive","purpose":"This directive specifies that all variables by default are created in SHADOW.","syntax":["%SHADOWVARS"]}],"%STACKSIZE":[{"kind":"directive","purpose":"Specifies stack size in long words.","syntax":["%STACKSIZE = n"],"details":["n is the stack size.","The default value of n is 300 (1200 bytes)."]}],"%TIMESLICE":[{"kind":"directive","purpose":"Supports round-robin type time slicing for tasks with the same priority","syntax":["%TIMESLICE = n"],"details":["n specifies task execution time in msec for one slice. The default value is 256 msec.","The timeslice value must be greater than 0.","This value is the maximum duration for executing the task continuously if there are other tasks with the same priority that are ready to run.","This function is effective only when more than one KAREL task with the same priority is executing at the same time.","The timeslice duration can be set during task execution by the SET_TSK_ATTR Built-In routine."]}],"%TPMOTION":[{"kind":"directive","purpose":"Specifies that task motion is enabled when the teach pendant is on","syntax":["%TPMOTION"],"details":["This attribute can be set during task execution by the SET_TSK_ATTR Built-In routine."]}],"%UNINITVARS":[{"kind":"directive","purpose":"This directive specifies that all variables are by default uninitialized.","syntax":["%UNINITVARS"]}],"ABORT":[{"kind":"action","purpose":"Aborts execution of a running or paused task","syntax":["ABORT <PROGRAM[n]>"],"details":["If task execution is running or paused, the ABORT action will abort task execution.","The ABORT action can be followed by the clause PROGRAM[n], where n is the task number to be aborted. Use GET_TASK_INFO to get a task number.","If PROGRAM[n] is not specified, the current task execution is aborted."],"seeAlso":["GET_TSK_INFO"]},{"kind":"condition","purpose":"Monitors the aborting of task execution","syntax":["ABORT <PROGRAM[n]>"],"details":["The ABORT condition is satisfied when the task is aborted. The actions specified by the condition handler will be performed.","If PROGRAM [n] is not specified, the current task number is used.","Actions that are routine calls will not be executed if task execution is aborted.","The ABORT condition can be followed by the clause PROGRAM[n], where n is the task number to be monitored. Use GET_TSK_INFO to get a task number."],"seeAlso":["GET_TSK_INFO"]},{"kind":"statement","purpose":"Terminates task execution and cancels any motion in progress (or pending)","syntax":["ABORT <PROGRAM[n]>"],"details":["After an ABORT, the program cannot be resumed. It must be restarted.","The statement can be followed by the clause PROGRAM[n], where n is the task number to be aborted."]}],"ARRAY":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as ARRAY data type","syntax":["ARRAY<[size{,size}]> OF data_type","where:","size: an INTEGER literal or constant","data_type: any type except PATH"],"details":["size indicates the number of elements in an ARRAY variable.","size must be in the range 1 through 32767 and must be specified in a normal ARRAY variable declaration. The amount of available memory in your controller might restrict the maximum size of an ARRAY.","Individual elements are referenced by the ARRAY name and the subscript size. For example, table[1] refers to the first element in the ARRAY table.","An entire ARRAY can be used only in assignment statements or as an argument in routine calls. In an assignment statement, both ARRAY variables must be of the same size and data_type. If size is different, the program will be translated successfully but will be aborted during execution, with error 12304, \"Array Length Mismatch.\"","size is not specified when declaring ARRAY routine parameters; an ARRAY of any size can be passed as an ARRAY parameter to a routine.","size is not used when declaring an ARRAY return type for a function. However, the returned ARRAY must be of the same size as the ARRAY to which it is assigned in the function call.","Each element is of the same type designated by data_type.","Valid ARRAY operators correspond to the valid operators of the individual elements in the ARRAY.","Individual elements of an array can be read or written only in the format that corresponds to the data type of the ARRAY.","Arrays of multiple dimensions can be defined.","Variable-sized arrays can be defined."],"seeAlso":["ARRAY_LEN"]}],"ASSIGNMENT":[{"kind":"action","purpose":"Sets the value of a variable to the result of an evaluated expression","syntax":["variable {[subscript{,subscript}]|. field} = expn","where:","variable: any KAREL variable","subscript: an INTEGER expression","expn: a valid KAREL expression","field: any field from a structured variable"],"details":["variable can be any user-defined variable, system variable with write access, or output port array with write access.","subscript is used to access elements of an array.","field is used to access fields in a structure.","expn must be of the same type as the variable or element of variable.","An exception is that an INTEGER expression can be assigned to a REAL. Any positional types can be assigned to each other.","Only system variables with write access can be used on the left side of an assignment statement. System variables with read only (RO) or read write (RW) access can be used on the right side.","Input port arrays cannot be used on the left side of an assignment statement."],"seeAlso":["FOR MORE INFORMATION ABOUT USING ASSIGNMENT"]},{"kind":"statement","purpose":"Sets the value of a variable to the result of an evaluated expression","syntax":["variable {[subscript{,subscript}]|. field} = expn","where:","variable: any KAREL variable","subscript: an INTEGER expression","expn: a valid KAREL expression","field: any field from a structured variable"],"details":["variable can be any user-defined variable, system variable with write access, or output port array with write access.","subscript is used to access elements of an array.","field is used to access fields in a structure.","expn must be of the same type as the variable or element of variable.","An exception is that an INTEGER expression can be assigned to a REAL. Any positional types can be assigned to each other. INTEGER, SHORT, and BYTE can be assigned to each other.","If variable is of type ARRAY, and no subscript is supplied, the expression must be an ARRAY of the same type and size. A type mismatch will be detected during translation. A size mismatch will be detected during execution and causes the program to abort with error 12304, \"Array Length Mismatch.\"","If variable is a user-defined structure, and no field is supplied, the expression must be a structure of the same type.","Only system variables with write access can be used on the left side of an assignment statement. System variables with read only (RO) or read write (RW) access can be used on the right side. If read only system variables are passed as parameters to a routine, they are passed by value, so any attempt to modify them (with an assignment statement) through the parameter in the routine has no effect.","Input port arrays cannot be used on the left side of an assignment statement."]}],"ATTACH":[{"kind":"statement","purpose":"Gives the KAREL program control of motion for the robot arm and auxiliary and extended axes","syntax":["ATTACH"],"details":["Used with the RELEASE statement. If motion control is not currently released from program control, the ATTACH statement has no effect.","If the teach pendant is still enabled, execution of the KAREL program is delayed until the teach pendant is disabled. The task status will show a hold of \"attach done.\"","Stopped motions can only be resumed following execution of the ATTACH statement."],"seeAlso":["RELEASE"]}],"BOOLEAN":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as a BOOLEAN data type","syntax":["BOOLEAN"],"details":["The BOOLEAN data type represents the BOOLEAN predefined constants TRUE, FALSE, ON, and OFF. The following lists some examples of valid and invalid BOOLEAN values used to represent the Boolean predefined constants. Valid and Invalid BOOLEAN Values VALID INVALID REASON TRUE T Must use entire word ON 1 Cannot use INTEGER values","TRUE and FALSE typically represent logical flags, and ON and OFF typically represent signal states. TRUE and ON are equivalent, as are FALSE and OFF.","Valid BOOLEAN operators are — AND, OR, and NOT — Relational operators (>, >=, =, <>, <, and <=)","The following have BOOLEAN values: — BOOLEAN constants, whether predefined or user-defined (for example, ON is a predefined constant) — BOOLEAN variables and BOOLEAN fields in a structure — ARRAY OF BOOLEAN elements — Values returned by BOOLEAN functions, whether user-defined or built-in (for example, IN_RANGE(pos_var)) — Values resulting from expressions that use relational or BOOLEAN operators (for example, x > 5.0) — Values of digital ports (for example, DIN[2])","Only BOOLEAN expressions can be assigned to BOOLEAN variables, returned from BOOLEAN function routines, or passed as arguments to BOOLEAN parameters."]}],"BYTE":[{"kind":"data type","purpose":"Defines a variable as a BYTE data type","syntax":["BYTE"],"details":["BYTE has a range of (0 ≤n ≥255). No uninitialized checking is done on bytes.","BYTEs are allowed only within an array or within a structure.","BYTEs can be assigned to SHORTs and INTEGERs, and SHORTs and INTEGERs can be assigned to BYTEs. An assigned value outside the BYTE range will be detected during execution and cause the program to abort."]}],"CANCEL":[{"kind":"action","purpose":"Terminates any motion in progress","syntax":["CANCEL <GROUP[n{,n}]>"],"details":["Cancels a motion currently in progress or pending (but not stopped) for one or more groups.","CANCEL does not cancel motions that are already stopped. To cancel a motion that is already stopped, use the CNCL_STP_MTN built-in routine.","If the group clause is not present, all groups for which the task has control (when the condition is defined) will be canceled. In particular, if the program containing the condition handler definition contains the %NOLOCKGROUP directive, the CANCEL action will not cancel motion in any group.","If a motion that is canceled and is part of a SIMULTANEOUS or COORDINATED motion with other groups, the motions for all groups are canceled.","The robot and auxiliary or extended axes decelerate smoothly to a stop. The remainder of the motion is canceled.","Canceled motions are treated as completed and cannot be resumed.","The CANCEL action in a global condition handler cancels any pending motions."]},{"kind":"statement","purpose":"Terminates any motion in progress.","syntax":["CANCEL <GROUP[n{,n}]>"],"details":["Cancels a motion currently in progress or pending (but not stopped) for one or more groups.","CANCEL does not cancel motions that are already stopped. To cancel a motion that is already stopped, use the CNCL_STP_MTN built-in routine.","If the group clause is not present, all groups for which the task has control will be canceled. In particular, if the program using the CANCEL statement contains the %NOLOCKGROUP directive, the CANCEL statement will not cancel motion in any group.","If a motion that is canceled is part of a SIMULTANEOUS or COORDINATED motion with other groups, the motions for all groups are canceled.","The robot and auxiliary axes decelerate smoothly to a stop. The remainder of the motion is canceled.","Canceled motions are treated as completed and cannot be resumed.","CANCEL does not affect stopped motions. Stopped motions can be resumed.","If an interrupt routine executes a CANCEL statement and the interrupted statement was a motion statement, when the interrupted program resumes, execution normally resumes with the statement following the motion statement.","CANCEL might not work as expected if it is used in a routine called by a condition handler. The motion might already be put on the stopped motion queue before the routine is called. Use a CANCEL action directly in the condition handler to be sure the motion is canceled.","Motion cannot be cancelled for a different task."]}],"CANCEL FILE":[{"kind":"statement","purpose":"Cancels a READ or WRITE statement that is in progress.","syntax":["CANCEL FILE [file_var]","where:","file_var:a FILE variable"],"details":["Used to cancel input or output on a specified file","The built-in function IO_STATUS can be used to determine if a CANCEL FILE operation was successful or, if it failed to determine the reason for the failure."],"env":"FLBT","seeAlso":["IO_STATUS"]}],"CLOSE FILE":[{"kind":"statement","purpose":"Breaks the association between a FILE variable and a data file or communication port","syntax":["CLOSE FILE file_var","where:","file_var:a FILE variable"],"details":["file_var must be a static variable that was used in the OPEN FILE statement.","Any buffered data associated with the file_var is written to the file or port.","The built-in function IO_STATUS will always return zero."],"seeAlso":["IO_STATUS"]}],"CLOSE HAND":[{"kind":"statement","purpose":"Causes the specified hand to close","syntax":["CLOSE HAND hand_num","where:","hand_num:an INTEGER expression"],"details":["The actual effect of the statement depends on how the HAND signals are set up in I/O system.","The valid range of values for hand_num is 1-2. Otherwise, the program is aborted with an error.","The statement has no effect if the value of hand_num is in range but the hand is not connected.","The program is aborted with an error if the value of hand_num is in range but the HAND signal represented by that value has not been assigned."]}],"CONFIG":[{"kind":"data type","purpose":"Defines a variable or structure field as a CONFIG data type","syntax":["CONFIG"],"details":["CONFIG defines a variable or structure field as a highly compact structure consisting of fields defining a robot configuration.","CONFIG contains the following predefined fields: — CFG_TURN_NO1:INTEGER — CFG_TURN_NO2:INTEGER — CFG_TURN_NO3:INTEGER — CFG_FLIP:BOOLEAN — CFG_LEFT:BOOLEAN — CFG_UP:BOOLEAN — CFG_FRONT:BOOLEAN","Variables and fields of structures can be declared as CONFIG.","Subfields of CONFIG data type can be accessed and set using the usual structure field notation.","Variables and fields declared as CONFIG can be — Assigned to one another. — Passed as parameters. — Written to and read from unformatted files.","Each subfield of a CONFIG variable or structure field can be passed as a parameter to a routine, but is always passed by value.","A CONFIG field is part of every POSITION and XYZWPR variable and field.","An attempt to assign a value to a CONFIG subfield that is too large for the field results in an abort error."]}],"CONNECT TIMER":[{"kind":"statement","purpose":"Causes an INTEGER variable to start being updated as a millisecond clock","syntax":["CONNECT TIMER TO clock_var","where:","clock_var:a static, user-defined INTEGER variable"],"details":["clock_var is presently incremented by the value of the system variable $SCR.$COND_TIME every $SCR.$COND_TIME milliseconds as long as the program is running or paused and continues until the program disconnects the timer, ends, or aborts. For example, if $SCR.$COND_TIM E=32 then clock_var will be incremented by 32 every 32 milliseconds.","You should initialize clock_var before using the CONNECT TIMER statement to ensure a proper starting value.","If the variable is uninitialized, it will remain so for a short period of time (up to 32 milliseconds) and then it will be set to a very large negative value (-2.0E31 + 32 milliseconds) and incremented from that value.","The program can reset the clock_var to any value while it is connected.","A clock_var initialized at zero wraps around from approximately two billion to approximately minus two billion after about 23 days.","If clock_var is a system variable or a local variable in a routine, the program cannot be translated. Note If two CONNECT TIMER statements using the same variable, are executed in two different tasks, the timer will advance twice as fast. For example, the timer will be incremented by 2 * $SCR.$COND_TIME every $SCR.$COND_TIME ms. However, this does not occur if two or more CONNECT TIMER statements using the same variable, are executed in the same task."],"seeAlso":["DISCONNECT TIMER"]}],"CONTINUE":[{"kind":"action","purpose":"Continues execution of a paused task","syntax":["CONTINUE <PROGRAM[n]>"],"details":["The CONTINUE action will not resume stopped motions.","If program execution is paused, the CONTINUE action will continue program execution.","The CONTINUE action can be followed by the clause PROGRAM[n], where n is the task number to be continued. Use GET_TSK_INFO to get a task number for a specified task name.","A task can be in an interrupt routine when CONTINUE is executed. However, you should be aware of the following circumstances because CONTINUE only affects the current interrupt level, and interrupt levels of a task might be independently paused or running. — If the interrupt routine and the task are both paused, CONTINUE will continue the interrupt routine but the task will remain paused. — If the interrupt routine is running and the task is paused, CONTINUE will appear to have no effect because it will try to continue the running interrupt routine. — If the interrupt routine is paused and the task is running, CONTINUE will continue the interrupt routine."]},{"kind":"condition","purpose":"Condition that is satisfied when program execution is continued","syntax":["CONTINUE <PROGRAM[n]>"],"details":["The CONTINUE condition monitors program execution. If program execution is paused, the CONTINUE action, issuing CONTINUE from the CRT/KB or a CYCLE START from the operator panel, will continue program execution and satisfy the CONTINUE condition.","The CONTINUE condition can be followed by the clause PROGRAM[n], where n is the task number to be continued. Use GET_TSK_INFO to get the task number of a specified task name."]}],"DELAY":[{"kind":"statement","purpose":"Causes execution of the program to be suspended for a specified number of milliseconds","syntax":["DELAY time_in_ms","where:","time_in_ms:an INTEGER expression"],"details":["If motion is active at the time of the delay, the motion continues.","time_in_ms is the time in milliseconds. The actual delay will be from zero to $SCR.$cond_time milliseconds less than the rounded time.","A time specification of zero has no effect.","If a program is paused while a delay is in progress, the delay will continue to be timed.","If the delay time in a paused program expires while the program is still paused, the program, upon resuming and with no further delay, will continue execution with the statement following the delay. Otherwise, upon resumption, the program will finish the delay time before continuing execution.","Aborting a program, or issuing RUN from the CRT/KB when a program is paused, terminates any delays in progress.","While a program is awaiting expiration of a delay, the KCL> SHOW TASK command will show a hold of DELAY.","A time value greater than one day or less than zero will cause the program to be aborted with an error."]}],"DISABLE CONDITION":[{"kind":"action","purpose":"Used within a condition handler to disable the specified condition handler","syntax":["DISABLE CONDITION [cond_hand_no]","where:","cond_hand_no:an INTEGER expression"],"details":["If the condition handler is not defined, DISABLE CONDITION has no effect.","If the condition handler is defined but not currently enabled, DISABLE CONDITION has no effect.","When a condition handler is disabled, its conditions are not tested. Thus, if it is activated again, the conditions must be satisfied after the activation.","Use the ENABLE CONDITION statement or action to reactivate a condition handler that has been disabled.","cond_hand_no must be in the range of 1-1000. Otherwise, the program will be aborted with an error."]},{"kind":"statement","purpose":"Disables the specified condition handler","syntax":["DISABLE CONDITION [cond_hand_no]","where:","cond_hand_no:an INTEGER expression"],"details":["If the condition handler is not defined, DISABLE CONDITION has no effect.","If the condition handler is defined but not currently enabled, DISABLE CONDITION has no effect.","When a condition handler is disabled, its conditions are not tested. Thus, if it is activated again, the conditions must be satisfied after the activation.","Use the ENABLE CONDITION statement or action to reactivate a condition handler that has been disabled.","cond_hand_no must be in the range of 1-1000. Otherwise, the program will be aborted with an error."],"seeAlso":["FOR MORE INFORMATION ON USING DISABLE CONDITION IN"]}],"DISCONNECT TIMER":[{"kind":"statement","purpose":"Stops updating a clock variable previously connected as a timer","syntax":["DISCONNECT TIMER timer_var","where:","timer_var:a static, user-defined INTEGER variable"],"details":["If timer_var is not currently connected as a timer, the DISCONNECT TIMER statement has no effect.","If timer_var is a system or local variable, the program will not be translated."],"seeAlso":["CONNECT TIMER"]}],"DISP_DAT_T":[{"kind":"data type","purpose":"Defines data type for use in DISCTRL_LIST Built-In","syntax":["disp_dat_t = STRUCTURE","win_start: ARRAY [4] OF SHORT","win_end: ARRAY [4] OF SHORT","curr_win: SHORT","cursor_row: SHORT","lins_per_pg: SHORT","curs_st_col: ARRAY [10] OF SHORT","curs_en_col: ARRAY [10] OF SHORT","curr_field: SHORT","last_field: SHORT","curr_it_num: SHORT","sob_it_num: SHORT","eob_it_num: SHORT","last_it_num: SHORT","menu_id: SHORT","ENDSTRUCTURE"],"details":["disp_dat_t can be used to display a list in four different windows. The list can contain up to 10 fields. Left and right arrows move between fields. Up and down arrows move within a field.","win_start is the starting row for each window.","win_end is the ending row for each window.","curr_win defines the window to display. The count begins at zero (0 will display the first window).","cursor_row is the current cursor row.","lins_per_pg is the number of lines per page for paging up and down.","curs_st_col is the cursor starting column for each field. The range is 0-39 for the teach pendant.","curs_en_col is the cursor ending column for each field. The range is 0-39 for the teach pendant.","curr_field is the current field in which the cursor is located. The count begins at zero (0 will set the cursor to the first field).","last_field is the last field in the list.","curr_it_num is the item number the cursor is on.","sob_it_num is the item number of the first item in the array.","eob_it_num is the item number of the last item in the array.","last_it_num is the item number of the last item in the list.","menu_id is the current menu identifier. Not implemented. May be left uninitialized."]}],"ENABLE CONDITION":[{"kind":"action","purpose":"Enables the specified condition handler","syntax":["ENABLE CONDITION [cond_hand_no]","where:","cond_hand_no:an INTEGER expression"],"details":["ENABLE CONDITION has no effect when — The condition handler is not defined — The condition handler is defined but is already enabled","cond_hand_no must be in the range of 1-1000. Otherwise, the program will be aborted with an error.","When a condition handler is enabled, its conditions are tested each time the condition handler is scanned. If the conditions are satisfied, the corresponding actions are performed and the condition handler is deactivated. Issue an ENABLE CONDITION statement or action to reactivate it.","Use the DISABLE CONDITION statement or action to deactivate a condition handler that has been enabled.","Condition handlers are known only to the task which defines them. One task cannot enable another tasks condition."],"seeAlso":["DISABLE CONDITION"]},{"kind":"statement","purpose":"Enables the specified condition handler","syntax":["ENABLE CONDITION [cond_hand_no]","where:","cond_hand_no:an INTEGER expression"],"details":["ENABLE CONDITION has no effect when — The condition handler is not defined — The condition handler is defined but is already enabled","cond_hand_no must be in the range of 1-1000. Otherwise, the program will be aborted with an error.","When a condition handler is enabled, its conditions are tested each time the condition handler is scanned. If the conditions are satisfied, the corresponding actions are performed and the condition handler is deactivated. Issue an ENABLE CONDITION statement or action to reactivate it.","Use the DISABLE CONDITION statement or action to deactivate a condition handler that has been enabled.","Condition handlers are known only to the task which defines them. One task cannot enable another tasks condition."],"seeAlso":["DISABLE CONDITION"]}],"ERROR":[{"kind":"condition","purpose":"Specifies an error as a condition","syntax":["ERROR[n]","where:","n:an INTEGER expression or asterisk (*)"],"details":["If n is an INTEGER, it represents an error code number. The condition is satisfied when the specified error occurs.","If n is an asterisk (*), it represents a wildcard. The condition is satisfied when any error occurs.","The condition is an event condition, meaning it is satisfied only for the scan performed when the error was detected. The error is not remembered on subsequent scans."],"seeAlso":["FOR MORE INFORMATION ON USING"]}],"EVAL":[{"kind":"clause","purpose":"Allows expressions to be evaluated in a condition handler definition","syntax":["EVAL(expression)","where:","expression:a valid KAREL expression"],"details":["expression is evaluated when the condition handler is defined, rather than dynamically during scanning.","expression can be any valid expression that does not contain a function call."],"seeAlso":["FOR MORE INFORMATION ON USING"]}],"EVENT":[{"kind":"condition","purpose":"Specifies the number of an event that satisfies a condition when a SIGNAL EVENT statement or action with that event number is executed","syntax":["EVENT[event_no]","where:","event_no:is an INTEGER expression"],"details":["Events can be used as user-defined event codes that become TRUE when signaled.","The SIGNAL EVENT statement or action is used to signal that an event has occurred.","event_no must be in the range of -32768 to 32767."],"seeAlso":["SIGNAL EVENT","CONDITION OR SIGNAL EVENT"]}],"FILE":[{"kind":"data type","purpose":"Defines a variable as FILE data type","syntax":["file"],"details":["FILE allows you to declare a static variable as a file.","You must use a FILE variable in OPEN FILE, READ, WRITE, CANCEL FILE, and CLOSE FILE statements.","You can pass a FILE variable as a parameter to a routine.","Several built-in routines require a FILE variable as a parameter, such as BYTES_LEFT, CLR_IO_STAT, GET_FILE_POS, IO_STATUS, SET_FILE_POS.","FILE variables have these restrictions: — FILE variables must be a static variable. — FILE variables are never saved. — FILE variables cannot be function return values. — FILE types are not allowed in structures, but are allowed in arrays. — No other use of this variable data type, including assignment to one another, is permitted."]}],"FROM":[{"kind":"clause","purpose":"Indicates a variable or routine that is external to the program, allowing data and/or routines to be shared among programs","syntax":["FROM prog_name","where:","prog_name: any KAREL program identifier"],"details":["The FROM clause can be part of a type, variable, or routine declaration.","The type, variable, or routine belongs to the program specified by prog_name.","In a FROM clause, prog_name can be the name of any program, including the program in which the type, variable, or routine is declared.","If the FROM clause is used in a routine declaration and is called during program execution, the body of the declaration must appear in the specified program and that program must be loaded.","The FROM clause cannot be used when declaring variables in the declaration section of a routine."]}],"GO TO":[{"kind":"statement","purpose":"Transfers control to a specified statement","syntax":["|| GO TO | GOTO || stmnt_label","where:","stmnt_label: A valid KAREL identifier"],"details":["stmnt_label must be defined in the same routine or program body as the GO TO statement.","Label identifiers are followed by double colons (::). Executable statements may or may not follow on the same line.","GOTO should only be used in special circumstances where normal control structures such as WHILE, REPEAT, and FOR loops would be awkward or difficult to implement."]}],"HOLD":[{"kind":"action","purpose":"Causes the current motion to be held and prevents subsequent motions from starting","syntax":["HOLD <GROUP[n,{,n}]>"],"details":["Any motion in progress is held. Robot and auxiliary or extended axes decelerate to a stop.","An attempted motion after a HOLD is executed is also held. HOLD cannot be overridden by a condition handler which issues a motion.","HOLD is released using the UNHOLD statement or action.","If the group clause is not present, all groups for which the task has control (when the condition is defined) will be canceled.","If a motion that is held is part of a SIMULTANEOUS or COORDINATED motion with other groups, the motions for all groups are held.","Motion cannot be held for a different task."]},{"kind":"statement","purpose":"Causes the current motion to be held and prevents subsequent motions from starting","syntax":["HOLD <GROUP[n{,n}]>"],"details":["Any motion in progress is held. Robot and auxiliary or extended axes decelerate to a stop.","An attempted motion after a HOLD is executed is also held. HOLD cannot be overridden by a condition handler which issues a motion.","HOLD is released using the UNHOLD statement or action.","All held motions are canceled if a RELEASE statement is executed while motion is held.","If the group clause is not present, all groups for which the task has control will be canceled.","If a motion that is stopped, resumed, canceled, or held is part of a SIMULTANEOUS or COORDINATED motion with other groups, the motions for all groups are stopped, resumed, canceled, or held.","Motion cannot be held for a different task."]}],"IN":[{"kind":"clause","purpose":"Specifies where a variable will be created","syntax":["IN (CMOS | DRAM | SHADOW)"],"details":["The IN clause can be part of a variable declaration. It should be specified before the FROM clause.","IN CMOS specifies that the variable will be created in permanent memory.","IN DRAM specifies that the variable will be created in temporary memory.","IN SHADOW specifies that any changes made to the variable will be maintained in CMOS. Writes to this type of variable are slower but reads are much faster. This a good memory type to use for configuration parameters that are currently in CMOS.","IN UNINIT_DRAM specifies that a DRAM variable is UNINITIALIZED at startup.","If the IN clause is not specified all variables are created in temporary memory; unless the %CMOSVARS or %SHADOW directive is specified, in which case all variables will be created in permanent memory.","The IN clause cannot be used when declaring variables in the declaration section of a routine."],"seeAlso":["%CMOSVARS","%SHADOW","%SHADOWCMOS"]}],"INTEGER":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as INTEGER data type","syntax":["INTEGER"],"details":["An INTEGER variable or parameter can assume whole number values in the range -2147483648 through +2147483646.","INTEGER literals consist of a series of digits, optionally preceded by a plus or minus sign. They cannot contain decimal points, commas, spaces, dollar signs ($), or other punctuation characters. Valid and Invalid INTEGER Literals Valid Invalid Reason 1 1.5 Decimal point not allowed (must be a whole number) –2500450 –2,500,450 Commas not allowed +65 +6 5 Spaces not allowed","If an INTEGER argument is passed to a routine where a REAL parameter is expected, it is treated as a REAL and passed by value.","Only INTEGER expressions can be assigned to INTEGER variables, returned from INTEGER function routines, or passed as arguments to INTEGER parameters.","Valid INTEGER operators are: — Arithmetic operators (+, -, *, /, DIV, MOD) — Relational operators (>, >=, =, <>, <, <=) — Bitwise operations (AND, OR, NOT)"]}],"JOINTPOS":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as JOINTPOS data type.","syntax":["JOINTPOS<n> <IN GROUP[m]>"],"details":["A JOINTPOS consists of a REAL representation of the position of each axis of the group, expressed in degrees or millimeters (mm).","n specifies the number of axes, with 9 as the default. The size in bytes is 8 + 4 * n.","A JOINTPOS may be followed by IN GROUP[m], where m indicates the motion group with which the data is to be used. The default is the group specified by the %DEFGROUP directive or 1.","CNV_REL_JPOS and CNV_JPOS_REL Built-ins can be used to access the real values.","A JOINTPOS can be assigned to other positional types. Note that some motion groups, for example single axis positioners, have no XYZWPR representation. If you attempt to assign a JOINTPOS to a XYZWPR or POSITION type for such a group, a run-time error will result."]}],"NOABORT":[{"kind":"action","purpose":"Prevents program execution from aborting when an external error occurs","syntax":[],"details":["The NOABORT action usually corresponds to an ERROR[n].","If the program is aborted by itself (i.e., executing an ABORT statement, run time error), the NOABORT action will be ignored and program execution will be aborted."]}],"NOMESSAGE":[{"kind":"action","purpose":"Suppresses the display and logging of error messages","syntax":["NOMESSAGE"],"details":["Display and logging of the error messages are suppressed only for the error number specified in the corresponding condition.","Use a wildcard (*) to suppress all messages.","Abort error messages still will be displayed and logged even if NOMESSAGE is used."]}],"NOPAUSE":[{"kind":"action","purpose":"Resumes program execution if the program was paused, or prevents program execution from pausing","syntax":["NOPAUSE"],"details":["The NOPAUSE action usually corresponds to an ERROR[n] or PAUSE condition.","The program will be resumed, even if it was paused before the error.","If the program is paused by itself, the NOPAUSE action will be ignored and program execution will be paused."]}],"OPEN FILE":[{"kind":"statement","purpose":"Associates a data file or communication port with a file variable","syntax":["OPEN FILE file_var (usage_string, file_string)","where:","file_var: FILE","usage_string: a STRING","file_string: a STRING"],"details":["file_var must be a static variable not already in use by another OPEN FILE statement.","The usage_string is composed of the following: `RO':Read only `RW':Read write `AP':Append `UD':Update","The file_string identifies a data file name and type, a window or keyboard, or a communication port.","The SET_FILE_ATR built-in routine can be used to set a file's attributes.","When a program is aborted or exits normally, any opened files are closed. Files are not closed when a program is paused.","Use the IO_STATUS built-in function to verify if the open file operation was successful."],"seeAlso":["IO_STATUS","SET_FILE_ATR"]}],"OPEN HAND":[{"kind":"statement","purpose":"Opens a hand on the robot","syntax":["OPEN HAND hand_num","where:","hand_num: an INTEGER expression"],"details":["The actual effect of the statement depends on how the HAND signals are set up.","hand_num must be a value in the range 1-2. Otherwise, the program is aborted with an error.","The statement has no effect if the value of hand_num is in range but the hand is not connected.","If the value of hand_num is in range but the HAND signal represented by that value has not been assigned, the program is aborted with an error."]}],"PATH":[{"kind":"data type","purpose":"Defines a variable or routine parameter as PATH data type","syntax":["PATH"],"details":["A PATH is a varying length list of elements called path nodes, numbered from 1 to the number of nodes in the PATH.","No valid operators are defined for use with PATH variables.","A PATH variable is indexed (or subscripted) as if it were an ARRAY variable. For example, tool_track[1] refers to the first node of a PATH called tool_track.","An uninitialized PATH has a length of zero.","PATH variables cannot be declared local to routines and cannot be returned from functions.","Only PATH expressions can be assigned to PATH variables or passed as arguments to PATH parameters.","A PATH variable can specify a data structure constituting the data for each path node.","A PATH variable can specify a data structure constituting the path header. This can be used to specify the UFRAME and/or UTOOL to be used with recording the path. It can also specify an axis group whose current position defines a table-top coordinate frame with respect to which the robot data is recorded.","A PATH can be declared with either, neither, or both of the following clauses following the word PATH: — NODEDATA = node_struct_name, specifying the data structure constituting a path node. — PATHHEADER = header_struct_name, specifying the structure constituting the path header. If both fields are present, they can appear in either order and are separated by a comma and optionally a new line.","If NODEDATA is not specified, it defaults to the STD_PTH_NODE structure.","If PATHHEADER is not specified, there is no (user-accessible) path header.","An element of the PATHHEADER structure can be referenced with the syntax path_var_name.header_field_name.","An element of a NODEDATA structure can be referenced with the syntax path_var_name[node_no].node_field_name.","The path header structure can be copied from one path to another with the path_var1 = path_var2 statement.","The path node structure can be copied from one node to another with the path_var[2] = path_var[1] statement.","A path can be passed as an argument to a routine as long as the PATHHEADER and NODEDATA types match. A path that is passed as an argument to a built-in routine can be of any type.","A path node can be passed as an argument to a routine as long as the routine parameter is the same type as the NODEDATA structure.","A path can be declared with a NODEDATA structure having no position type elements. This can be a useful way of maintaining a list structure."],"seeAlso":["INSERT_NODE","NODE_SIZE"]}],"PAUSE":[{"kind":"action","purpose":"Suspends execution of a running task","syntax":["PAUSE <PROGRAM[n]>"],"details":["The PAUSE action pauses task execution in the following manner: — Any motion already initiated continues until completed. — Files are left open. — All connected timers continue being incremented. — All PULSE statements in execution continue execution. — Sensing of conditions specified in condition handlers continues. — Any Actions, except routine call actions, are completed. Routine call actions are performed when the program is resumed.","The PAUSE action can be followed by the clause PROGRAM[n], where n is the task number to be paused.","Use GET_TSK_INFO to find a task number."],"seeAlso":["UNPAUSE"]},{"kind":"condition","purpose":"Monitors the pausing of program execution","syntax":["PAUSE < PROGRAM [n] >"],"details":["The PAUSE condition is satisfied when a program is paused, for example, by an error, a PAUSE Statement, or the PAUSE Action.","If one of the actions corresponding to a PAUSE condition is a routine call, it is necessary to specify a NOPAUSE action to allow execution of the routine. Also, the routine being called needs to include a PAUSE statement so the system can handle completely the cause of the original pause.","The PAUSE condition can be followed by the clause PROGRAM[n], where n is the task number to be paused.","Use GET_TSK_INFO to find a task number."]},{"kind":"statement","purpose":"Suspends execution of a KAREL program","syntax":["PAUSE < PROGRAM [n] >"],"details":["The PAUSE statement pauses program execution in the following manner: — Any motion already initiated continues until completed. — Files are left open. — All connected timers continue being incremented. — All PULSE statements in execution continue execution. — Sensing of conditions specified in condition handlers continues. — Any actions, except routine call actions, are completed. Routine call actions are performed when the program is resumed.","The PAUSE statement can be followed by the clause PROGRAM[n], where n is the task number to be paused.","Use GET_TSK_INFO to find a task number."]}],"PORT_ID":[{"kind":"action","purpose":"Sets the value of a port array element to the result of an expression","syntax":["port_id[n] = expression","where:","port_id:an output port array","n:an INTEGER","expression:a variable, constant, or EVAL clause"],"details":["The value of expression is assigned to the port array element referenced by n.","The port array must be an output port array that can be written to by a KAREL program.","expression can be a user-defined, static variable, a system variable that can be read by a KAREL program, any constant, or an EVAL clause.","If expression is a variable, the value used is the current value of the variable at the time the action is taken, not when the condition handler is defined.","If expression is an EVAL clause, it is evaluated when the condition handler is defined and that value is assigned when the action is taken.","The expression must be of the same type as port_id.","You cannot assign a port array element to a port array element directly.","If the expression is a variable that is uninitialized when the condition handler is enabled, the program will be aborted with an error."],"seeAlso":["RELATIONAL"]},{"kind":"condition","purpose":"Monitors a digital port signal","syntax":["<NOT> port_id[n] < + | - >","where:","port_id:a port array","n:an INTEGER"],"details":["n specifies the port array signal to be monitored.","port_id must be one of the predefined BOOLEAN port array identifiers with read access.","For event conditions, only the + or - alternatives are used.","For state conditions, only the NOT alternative is used."],"seeAlso":["RELATIONAL"]}],"POSITION":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as POSITION data type","syntax":["POSITION <IN GROUP[n]>"],"details":["A POSITION consists of a matrix defining the normal, orient, approach, and location vectors and a component specifying a configuration string, for a total of 60 bytes.","The configuration string indicates the joint placements and multiple turns that describe the configuration of the robot when it is at a particular position.","A POSITION is always referenced with respect to a specific coordinate frame.","The POSITION data type can be used to represent a frame of reference in which case the configuration component is ignored.","Coordinate frame transformations can be done using the relative position operator (:).","A POSITION can be assigned to other positional types.","Valid POSITION operators are the — Relative position (:) operator — Approximately equal (>=<) operator","A POSITION can be followed by IN GROUP[n], where n indicates the motion group with which the data is to be used. The default is the group specified by the %DEFGROUP directive, or 1.","Components of POSITION variables can be accessed or set as if they were defined as follows: POSITION Data Type POSITION = STRUCTURE NORMAL: VECTOR -- read-only ORIENT: VECTOR -- read-only APPROACH: VECTOR -- read-only LOCATION: VECTOR -- read-write CONFIG_DATA: CONFIG -- read-write ENDSTRUCTURE"],"seeAlso":["UNPOS"]}],"PROGRAM":[{"kind":"statement","purpose":"Identifies the program name in a KAREL source program","syntax":["PROGRAM prog_name","where:","prog_name: a valid KAREL identifier"],"details":["It must be the first statement (other than comments) in a program.","The identifier used to name a program cannot be used in the program for any other purpose, such as to identify a variable or constant.","prog_name must also appear in the END statement that marks the end of the executable section of the program.","The program name can be used to call the program as a procedure routine from within a program in the same way routine names are used to call procedure routines."]}],"PULSE":[{"kind":"action","purpose":"Pulses a digital output port for a specified number of milliseconds","syntax":["PULSE DOUT[port_no] FOR time_in_ms","where:","port_no: an INTEGER variable or literal","time_in_ms: an INTEGER"],"details":["port_no must be a valid digital output port number.","time_in_ms specifies the duration of the pulse in milliseconds.","If time_in_ms duration is zero, no pulse will occur. Otherwise, the period is rounded up to the next multiple of 8 milliseconds.","A pulse always turns on the port at the start of the pulse and turns off the port at the end of the pulse.","If the port is ``normally on,'' negative pulses can be accomplished by setting the port to reversed polarity, or by executing the following sequence: DOUT[n] = FALSE DELAY x DOUT[n] = TRUE","NOWAIT is not allowed in a PULSE action.","If the program is paused while a pulse is in progress, the pulse will end at the correct time.","If the program is aborted while a pulse is in progress, the port stays in whatever state it was in when the abort occurred.","If time_in_ms is negative or greater than 86,400,000 (24 hours), the program is aborted with an error."]},{"kind":"statement","purpose":"Pulses a digital output port for a specified number of milliseconds.","syntax":["PULSE DOUT[port_no] FOR time_in_ms < NOWAIT >","where:","port_no: an INTEGER variable or literal","time_in_ms: an INTEGER"],"details":["port_no must be a valid digital output port number.","time_in_ms specifies the duration of the pulse in milliseconds.","If time_in_ms duration is zero, no pulse will occur. Otherwise, the period is rounded up to the next multiple of 8 milliseconds. The actual duration of the pulse will be from zero to 8 milliseconds less than the rounded value. For example, if 100 is specified, it is rounded up to 104 (the next multiple of 8) milliseconds. The actual duration will be from 96 to 104 milliseconds.","A pulse always turns on the port at the start of the pulse and turns off the port at the end of the pulse.","If the port is ``normally on,'' negative pulses can be accomplished by setting the port to reversed polarity, or by executing the following sequence: DOUT[n] = FALSE DELAY x DOUT[n] = TRUE","If NOWAIT is specified in a PULSE statement, the next KAREL statement will be executed concurrently with the pulse.","If NOWAIT is not specified in a PULSE statement, the next KAREL statement will not be executed until the pulse is completed."]}],"PURGE CONDITION":[{"kind":"statement","purpose":"Deletes the definition of a condition handler from the system","syntax":["PURGE CONDITION[cond_hand_no]","where:","cond_hand_no: an INTEGER expression"],"details":["The statement has no effect if there is no condition handler defined with the specified number.","The PURGE CONDITION Statement is used only to purge global condition handlers.","The PURGE CONDITION Statement will purge enabled conditions.","If a condition handler with the specified number was previously defined, it must be purged before it is replaced with a new one."],"seeAlso":["ENABLE CONDITION"]}],"QUEUE_TYPE":[{"kind":"data type","purpose":"Defines the data type for use in QUEUE built-in routines","syntax":["queue_type = STRUCTURE","n_entries: INTEGER","sequence_no: INTEGER","head: INTEGER","tail: INTEGER","ENDSTRUCTURE"],"details":["queue_type is used to initialize and maintain queue data for the QUEUE built-in routines. Do not change this data; it is used internally."],"seeAlso":["MODIFY_QUEUE"]}],"READ":[{"kind":"statement","purpose":"Reads data from a serial I/O device or file.","syntax":["READ < file_var > (data_item {,data_item})","where:","file_var: a FILE variable","data_item: a variable identifier and its optional format specifiers or the reserved word CR"],"details":["If file_var is not specified in a READ statement the default TPDISPLAY is used. %CRTDEVICE directive will change the default to INPUT.","If file_var is specified, it must be one of the input devices (INPUT, CRTPROMPT, TPDISPLAY, TPPROMPT) or a variable that was set in the OPEN FILE statement.","If file_var attribute was set with the UF option, data is transmitted into the specified variables in binary form. Otherwise, data is transmitted as ASCII text.","data_item can be a system variable that has RW access or a user-defined variable.","When the READ statement is executed, data is read beginning with the next nonblank input character and ending with the last character before the next blank, end of line, or end of file for all input types except STRING.","If data_item is of type ARRAY, a subscript must be provided.","If data_item is of type PATH, you can specify that the entire path be read, a specific node be read ([n]), or a range of nodes be read ([n.. m]).","Optional format specifiers can be used to control the amount of data read for each data_item. The effect of format specifiers depends on the data type of the item being read and on whether the data is in text (ASCII) or binary (unformatted) form.","The reserved word CR, which can be used as a data item, specifies that any remaining data in the current input line is to be ignored. The next data item will be read from the start of the next input line.","If reading from a file and any errors occur during input, the variable being read and all subsequent variables up to CR in the data list are set uninitialized.","If file_var is a window device and any errors occur during input, an error message is displayed indicating the bad data item and you are prompted to enter a replacement for the invalid data item and to reenter all subsequent items.","Use IO_STATUS (file_var) to determine if the read operation was successful. Note Read CR should never be used in unformatted mode."],"seeAlso":["IO_STATUS"]}],"REAL":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as a REAL data type with a numeric value that includes a decimal point and a fractional part, or numbers expressed in scientific notation.","syntax":["REAL"],"details":["REAL variables and expressions can have values in the range of -3.4028236E+38 through -1.175494E-38, 0.0, and from +1.175494E-38 through +3.4028236E+38, with approximately seven decimal digits of significance. Otherwise, the program will be aborted with the ``Real overflow'' error.","The decimal point is mandatory when defining a REAL constant or literal (except when using scientific notation). The decimal point is not mandatory when defining a REAL variable as long as it was declared as REAL.","Scientific notation is allowed and governed by the following rules: — The decimal point is shifted to the left so that only one digit remains in the INTEGER part. — The fractional part is followed by the letter E (upper or lower case) and ±an INTEGER. This part specifies the magnitude of the REAL number. For example, 123.5 is expressed as 1.235E2. — The fractional part and the decimal point can be omitted. For example, 100.0 can be expressed as 1.000E2, as 1.E2, or 1E2.","All REAL variables with magnitudes between -1.175494E- 38 and +1.175494E-38 are treated as 0.0.","Only REAL or INTEGER expressions can be assigned to REAL variables, returned from REAL function routines, or passed as arguments to REAL parameters.","If an INTEGER expression is used in any of these instances, it is treated as a REAL value. If an INTEGER variable is used as an argument to a REAL parameter, it is always passed by value, not by reference.","Valid REAL operators are: — Arithmetic operators (+, +, *, /) — Relational operators (>, >=, =, < >, <, <=) Valid and Invalid REAL operators VALID INVALID REASON 1.5 15 Decimal point is required (15 is an INTEGER not a REAL) 1.. Must include an INTEGER or a fractional part +2500.450 +2,500.450 Commas not allowed 1.25E-4 1.25E -4 Spaces not allowed"]}],"RELATIONAL":[{"kind":"condition","purpose":"Used to test the relationship between two operands.","syntax":["variable <[subscript]> rel_op expression","where:","variable: a static INTEGER or REAL variable or a BOOLEAN port array element","subscript: an INTEGER expression (only used with port arrays)","rel_op: a relational operator","expression: a static variable, constant, or EVAL clause"],"details":["Relational conditions are state conditions, meaning the relationship is tested during every scan.","The following relational operators can be used: =:equal <>:not equal <:less than =<:less than or equal >:greater than >=:greater than or equal","Both operands must be of the same data type and can only be of type INTEGER, REAL, or BOOLEAN. INTEGER values can be used where REAL values are required, and will be treated as REAL values.","variable can be any of the port array signals, a user-defined static variable, or a system variable that can be read by a KAREL program.","expression can be a user-defined static variable, a system variable that can be read by a KAREL program, any constant, or an EVAL clause.","Variables used in relational conditions must be initialized before the condition handler is enabled."]}],"RELAX HAND":[{"kind":"statement","purpose":"Turns off open signal for a tool controlled by one signal or turns off both open and close signals for a tool controlled by a pair of signals.","syntax":["RELAX HAND hand_num","where:","hand_num: an INTEGER expression"],"details":["The actual effect of the statement depends on how the HAND signals are set up.","hand_num must be a value in the range 1-2. Otherwise, the program is aborted with an error.","The statement has no effect if the value of hand_num is in range but the hand is not connected.","If the value of hand_num is in range but the HAND signal represented by that value has not been assigned, the program is aborted with an error."],"env":"UIF"}],"RELEASE":[{"kind":"statement","purpose":"Releases all motion control of the robot arm and auxiliary or extended axes from the KAREL program so that they can be controlled by the teach pendant while a KAREL program is running.","syntax":["RELEASE"],"details":["Motion stopped prior to execution of the RELEASE statement can only be resumed after the execution of the next ATTACH statement.","If motion is initiated from the program while in a released state, the program is aborted with the following error, ``MCTRL Denied because Released.","If RELEASE is executed while motion is in progress or in a HOLD condition, the program is aborted with the following error, \"Detach request failed.\"","All motion control from all KAREL tasks will be released."]}],"RESUME":[{"kind":"action","purpose":"Restarts the last stopped motion issued by the task.","syntax":["RESUME <GROUP[n{,n}]>"],"details":["A motion set is a group of motions issued but not yet terminated when a STOP statement or action is issued.","If there are no stopped motion sets, no motion will result from the RESUME.","If more than one motion set has been stopped, RESUME restarts the most recently stopped, unresumed motion set. Subsequent RESUMEs will start the others in last-in-first-out sequence.","The motions contained in a stopped motion set are resumed in the same order in which they were originally issued.","If a motion is in progress when the RESUME action is issued, any resumed motion(s) occur after the current motion is completed.","If the group clause is not present, all groups for which the task has control (when the condition is defined) will be resumed.","If the motion that is stopped, resumed, canceled, or held is part of a SIMULTANEOUS or COORDINATED motion with other groups, the motions for all groups are stopped, resumed, canceled, or held.","Motion cannot be resumed for a different task."]},{"kind":"statement","purpose":"Restarts the last stopped motion issued by the task.","syntax":["RESUME <GROUP[n{,n}]>"],"details":["A motion set is a group of motions issued but not yet terminated when a STOP statement or action is issued.","If there are no stopped motion sets, no motion will result from the RESUME.","If more than one motion set has been stopped, RESUME restarts the most recently stopped, unresumed motion set. Subsequent RESUMEs will start the others in last-in-first-out sequence.","Those motions in a stopped motion set are resumed in the same order in which they were originally issued.","If a motion is in progress when the RESUME statement is issued, any resumed motion(s) occur after the current motion is completed.","If the group clause is not present, all groups for which the task has control will be resumed.","If the motion that is stopped, resumed, canceled, or held is part of a SIMULTANEOUS or COORDINATED motion with other groups, the motions for all groups are stopped, resumed, canceled, or held.","Motion cannot be resumed for a different task."]}],"RETURN":[{"kind":"statement","purpose":"Returns control from a routine/program to the calling routine/program, optionally returning a result.","syntax":["RETURN < (value) >"],"details":["value is required when returning from functions, but is not permitted when returning from procedures. The data type of value must be the same as the type used in the function declaration.","If a main program executes a RETURN statement, execution is terminated and cannot be resumed. All motions in progress will be completed normally.","If no RETURN is specified, the END statement serves as the return.","If a function routine returns with the END statement instead of a RETURN statement, the program is aborted with the 12321 error, ``END STMT of a func rtn."]}],"ROUTINE":[{"kind":"statement","purpose":"Specifies a routine name, with parameters and types, and a returned value data type for function routines.","syntax":["ROUTINE name < param_list > <: return_type >","where:","name: a valid KAREL identifier","param_list: described below","return_type: any data type that can be returned by a function, that is, any type except FILE, PATH,","and vision types"],"details":["name specifies the routine name.","param_list is of the form (name_group {; name_group }) — name_group is of the form param_name: param_type — param_name is a parameter which can be used within the routine body as a variable of data type param_type. — If a param_type or return_type is an ARRAY, the size is excluded. If the param_type is a STRING, the string length is excluded.","When the routine body follows the ROUTINE statement, the names in param_list are used to associate arguments passed in with references to parameters within the routine body.","When a routine is from another program, the names in the parameter list are of no significance but must be present in order to specify the number and data types of parameters.","If the ROUTINE statement contains a return_type, the routine is a function routine and returns a value. Otherwise, it is a procedure routine.","The ROUTINE statement must be followed by a routine body or a FROM clause."]}],"SEMAPHORE":[{"kind":"condition","purpose":"Monitors the value of the specified semaphore","syntax":["SEMAPHORE[semaphore_no]"],"details":["semaphore_no specifies the semaphore number to use.","semaphore_no must be in the range of 1 to the number of semaphores defined on the controller.","When the value of the indicated semaphore is greater than zero, the condition is satisfied (TRUE)."]}],"SHORT":[{"kind":"data type","purpose":"Defines a variable as a SHORT data type","syntax":["SHORT"],"details":["SHORT, is defined as 2 bytes with the range of (-32768 <= n >= 32766). A SHORT variable assigned to (32767) is considered uninitialized.","SHORTs are allowed only within an array or within a structure.","SHORTs can be assigned to BYTEs and INTEGERs, and BYTEs and INTEGERs can be assigned to SHORTs. An assigned value outside the SHORT range is detected during execution and causes the program to be aborted."]}],"SIGNAL EVENT":[{"kind":"action","purpose":"Signals an event that might satisfy a condition handler or release a waiting program","syntax":["SIGNAL EVENT[event_no]","where:","event_no: an INTEGER expression"],"details":["You can use the SIGNAL EVENT action to indicate a user-defined event has occurred.","event_no occurs when signaled and is not remembered. Thus, if a WHEN clause has the event as its only condition, the associated actions will occur.","If other conditions are specified that are not met at the time the event is signaled, the actions are not taken, even if the other conditions are met at another time.","event_no must be in the range of -32768 to 32767. Otherwise, the program is aborted with an error."],"seeAlso":["EVENT"]},{"kind":"statement","purpose":"Signals an event that might satisfy a condition handler or release a waiting program","syntax":["SIGNAL EVENT [event_no]","where:","event_no: an INTEGER"],"details":["You can use the SIGNAL EVENT statement to indicate a user-defined event has occurred.","event_no occurs when signaled and is not remembered. Thus, if a WHEN clause has the event as its only condition, the associated actions will occur.","If other conditions are specified that are not met at the time the event is signaled, the actions are not taken, even if the other conditions are met at another time.","event_no must be in the range of -32768 to 32767. Otherwise, the program is aborted with an error."],"seeAlso":["EVENT"]}],"SIGNAL SEMAPHORE":[{"kind":"action","purpose":"Adds one to the value of the indicated semaphore","syntax":["SIGNAL SEMAPHORE[semaphore_no]","where:","semaphore_no: an INTEGER expression"],"details":["The semaphore indicated by semaphore_no is incremented by one.","semaphore_no must be in the range of 1 to the number of semaphores defined on the controller."]}],"STD_PTH_NODE":[{"kind":"data type","purpose":"Defines a data type for use in PATHs.","syntax":["STD_PTH_NODE = STRUCTURE","node_pos: POSITION in GROUP[1]","group_data: GROUP_ASSOC in GROUP[1] (no longer used)","common_data: COMMON_ASSOC (no longer used)","ENDSTRUCTURE"],"details":["If the NODEDATA clause is omitted from the PATH declaration, then STD_PTH_NODE will be the default.","Each node in the PATH will be of this type."]}],"STOP":[{"kind":"action","purpose":"Stops any motion in progress, leaving it in a resumable state","syntax":["STOP <GROUP[n{,n}]>"],"details":["Any motion in progress is decelerated to a stop. The unfinished motion as well as any pending motions are grouped together in a motion set and placed on a stack.","More than one motion might be stacked by a single STOP action.","If the KAREL program was waiting for the completion of the motion in progress, it will continue to wait.","The stacked motion set can be removed from the stack and restarted with either a RESUME statement or action or by issuing RESUME from the operator interface (CRT/KB).","If the group clause is not present, all groups for which the task has control (when the condition is defined) will be stopped.","If the motion that is stopped, resumed, canceled, or held is part of a SIMULTANEOUS or COORDINATED motion with other groups, the motions for all groups are stopped, resumed, canceled, or held.","Motion cannot be stopped for a different task."],"seeAlso":["RESUME"]},{"kind":"statement","purpose":"Stops any motion in progress, leaving it in a resumable state","syntax":["STOP <GROUP[n{,n}]>"],"details":["Any motion in progress is decelerated to a stop. The unfinished motion as well as any pending motions are grouped together in a motion set and placed on a stack.","More than one motion might be stacked by a single STOP statement.","If the KAREL program was waiting for the completion of the motion in progress, it will continue to wait.","The stacked motion set can be removed from the stack and restarted with either a RESUME statement or action, or by issuing RESUME from the CRT/KB.","If the group clause is not present, all groups for which the task has control will be stopped.","If the motion that is stopped, resumed, canceled, or held is part of a SIMULTANEOUS or COORDINATED motion with other groups, the motions for all groups are stopped, resumed, canceled, or held.","Motion cannot be stopped for a different task."],"seeAlso":["RESUME"]}],"STRING":[{"kind":"data type","purpose":"Defines a variable or routine parameter as STRING data type","syntax":["STRING[length]","where:","length: an INTEGER constant or literal"],"details":["length, the physical length of the string, indicates the maximum number of characters for which space is allocated for a STRING variable.","length must be in the range 1 through 254 and must be specified in a STRING variable declaration.","A length value is not used when declaring STRING routine parameters; a STRING of any length can be passed to a STRING parameter.","Attempting to assign a STRING to a STRING variable that is longer than the physical length of the variable results in the STRING value being truncated on the right to the physical length of the STRING variable.","Only STRING expressions can be assigned to STRING variables or passed as arguments to STRING parameters.","STRING values cannot be returned by functions.","Valid STRING operators are: — Relational operators (>, >=, =, <>, <, and <=) — Concatenation operator (+)","STRING literals consist of a series of ASCII characters enclosed in single quotes (apostrophes)."]}],"STRUCTURE":[{"kind":"data type","purpose":"Defines a data type as a user-defined structure","syntax":["new_type_name = STRUCTURE","field_name_1: type_name_1","field_name_2: type_name_2","...","ENDSTRUCTURE"],"details":["A user-defined structure is a data type consisting of a list of component fields, each of which can be a standard data type or another, previously defined, user data type.","When a program containing variables of user-defined types is loaded, the definitions of these types is checked against a previously created definition. If this does not exist, it is created.","The following data types are not permitted as part of a data structure: — STRUCTURE definitions (types that are declared structures are permitted) — PATH types — FILE types — Vision types — Variable length arrays — The data structure itself, or any type that includes it, either directly or indirectly","A variable may not be defined as a structure, but as a data type previously defined as a structure"]}],"UNHOLD":[{"kind":"action","purpose":"Releases a HOLD of motion","syntax":["UNHOLD <GROUP [n{,n}]>"],"details":["Any motion that was in progress when the last HOLD was executed is resumed.","If motions are not held, the action has no effect.","Held motions are canceled if a RELEASE statement is executed.","If the group clause is not present, all groups or which the task has control (when the condition is defined) will be resumed.","Motion cannot be stopped for a different task."]},{"kind":"statement","purpose":"Releases a HOLD of motion","syntax":["UNHOLD <GROUP [n{,n}]>"],"details":["Any motion that was in progress when the last HOLD was executed is resumed.","If motions are not held, the statement has no effect.","Held motions are canceled if a RELEASE statement is executed.","If the group clause is not present, all groups or which the task has control (when the condition is defined) will be resumed.","Motion cannot be stopped for a different task."]}],"UNPAUSE":[{"kind":"action","purpose":"Resumes program execution long enough for a routine action to be executed","syntax":["UNPAUSE"],"details":["If a routine is called as an action, but program execution is paused, execution is resumed only for the duration of the routine and then is paused again.","If more than one routine is called, all of the routines will be executed before execution is paused again.","The resume and pause caused by UNPAUSE do not satisfy any RESUME and PAUSE conditions."],"seeAlso":["PAUSE"]}],"VECTOR":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as VECTOR data type","syntax":["VECTOR"],"details":["A VECTOR consists of three REAL values representing a location or direction in three dimensional Cartesian coordinates.","Only VECTOR expressions can be assigned to VECTOR variables, returned from VECTOR function routines, or passed as arguments to VECTOR parameters.","Valid VECTOR operators are: — Addition (+) and subtraction (-) mathematical operators — Equal (=) and the not equal (<>) relational operators — Cross product (#) and the inner product (@) operators. — Multiplication (*) and division (÷) operators — Relative position (:) operator","Component fields of VECTOR variables can be accessed or set as if they were defined as follows: VECTOR Data Type VECTOR = STRUCTURE X: REAL Y: REAL Z: REAL ENDSTRUCTURE Note: All fields are read-write"]}],"WAIT FOR":[{"kind":"statement","purpose":"Delays continuation of program execution until some condition(s) are met","syntax":["WAIT FOR cond_list","where:","cond_list: one or more conditions"],"details":["All of the conditions in a single WAIT FOR statement must be satisfied simultaneously for execution to continue."]}],"WHEN":[{"kind":"clause","purpose":"Used to specify a conditions/actions pair in a global condition handler","syntax":["WHEN cond_list DO action_list","where:","cond_list: one or more conditions","action_list: one or more conditions"],"details":["All of the conditions in the cond_list of a single WHEN clause must be satisfied simultaneously for the condition handler to be triggered.","The action_list represents a list of actions to be taken when the corresponding conditions of a WHEN clause are satisfied simultaneously.","Calls to function routines are not allowed in a CONDITION statement and, therefore, cannot be used in a WHEN clause.","CONDITION statements can include multiple WHEN clauses."]}],"WITH":[{"kind":"clause","purpose":"Used in condition handlers to specify condition handler qualifiers","syntax":["WITH param_spec {, param_spec}","where:","param_spec is of the form: with_sys_var = value","with_sys_var: one of the system variables available for use in the WITH clause","value: an expression of the type corresponding to the type of the system variable"],"details":["The actual system variables specified are not changed.","$PRIORITY and $SCAN_TIME are condition handler qualifiers that can be used in a WITH clause only when the WITH clause is part of a condition handler statement."]}],"WRITE":[{"kind":"statement","purpose":"Writes data to a serial device or file","syntax":["WRITE <file_var> (data_item {,data_item })","where:","file_var: a FILE variable","data_item: an expression and its optional format specifiers or the reserved word CR"],"details":["If file_var is not specified in a WRITE statement the default TPDISPLAY is used. %CRTDEVICE directive will change the default to OUTPUT.","If file_var is specified, it must be one of the output devices or a variable that has been equated to one of them.","If file_var attribute was set with the UF option, data is transmitted to the specified file or device in binary form. Otherwise, data is transmitted as ASCII text.","data_item can be any valid KAREL expression.","If data_item is of type ARRAY, a subscript must be provided.","If data_item is of type PATH, you can specify that the entire path be read, a specific node be read [n], or a range of nodes be read [n.. m].","Optional format specifiers can be used to control the amount of data that is written for each data_item.","The reserved word CR, which can be used as a data item, specifies that the next data item to be written to the file_var will start on the next line.","Use the IO_STATUS Built-In to determine if the write operation was successful."],"seeAlso":["PATH"]}],"XYZWPR":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as XYZWPR data type","syntax":["XYZWPR <IN GROUP [n]>"],"details":["An XYZWPR consists of three REAL components specifying a Cartesian location (x,y,z), three REAL components specifying an orientation (w,p,r), and a component specifying a CONFIG Data Type, 36 bytes total.","The configuration string indicates the joint placements and multiple turns that describe the configuration of the robot when it is at a particular position.","A position is always referenced with respect to a specific coordinate frame.","Components of XYZWPR variables can be accessed or set as if they were defined as follows: XYZWPR Data Type XYZWPR = STRUCTURE X: REAL Y: REAL Z: REAL W: REAL P: REAL R: REAL CONFIG_DATA: CONFIG ENDSTRUCTURE Note: All fields are read-write access."]}],"XYZWPREXT":[{"kind":"data type","purpose":"Defines a variable, function return type, or routine parameter as an XYZWPREXT","syntax":["XYZWPREXT <IN GROUP [n]>"],"details":["An XYZWPREXT consists of three REAL components specifying a Cartesian location (x,y,z), three REAL components specifying an orientation (w,p,r), and a component specifying a configuration string. It also includes three extended axes, 48 bytes total.","The configuration string indicates the joint placements and multiple turns that describe the configuration of the robot when it is at a particular position.","A position is always referenced with respect to a specific coordinate frame.","Components of XYZWPREXT variables can be accessed or set as if they were defined as follows: XYZWPREXT Data Type XYZWPRext = STRUCTURE X: REAL Y: REAL Z: REAL W: REAL P: REAL R: REAL CONFIG_DATA: CONFIG EXT1: REAL EXT2: REAL EXT3: REAL ENDSTRUCTURE --Note: All fields are read-write access."]}]};
